-- Initial schema for the coach app (public schema + storage buckets/policies).
--
-- Generated by replaying the project's historical schema into an empty
-- PostgreSQL database with Supabase's platform schemas (auth, storage) present,
-- then dumping the public schema with pg_dump --schema-only --no-owner.
-- Later changes are forward migrations in this folder, applied in filename order.
--
-- Supabase owns auth.*, storage.* internals, cron and net. This file only adds
-- the app's own buckets and storage policies on top of them.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

