-- Name: FUNCTION auth_clear_password(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auth_clear_password(p_user_id uuid) IS 'Sets auth.users.encrypted_password to NULL. Used by the client-invite edge function so invited accounts stay password-less, since GoTrue admin createUser writes a bcrypt hash even when no password is supplied. service_role only.';

