--
-- Name: check_client_onboarding_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_client_onboarding_readiness(p_onboarding_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  o          public.client_onboarding%rowtype;
  cli        public.clients%rowtype;
  drf        public.program_drafts%rowtype;
  mp         public.client_meal_plans%rowtype;
  v_slots    int := 0;
  v_ck       int := 0;
  v_blocks   int := 0;
  v_reviews  int := 0;
  v_missing  text[] := '{}';
  v_ready    boolean;
begin
  perform public.assert_coach_owns_onboarding(p_onboarding_id);
  select * into o from public.client_onboarding where id = p_onboarding_id;
  if not found then return jsonb_build_object('status','error','reason','onboarding_not_found'); end if;

  select * into cli from public.clients where id = o.client_id;

  select count(*) filter (where b->>'severity' = 'block'),
         count(*) filter (where b->>'severity' = 'review')
    into v_blocks, v_reviews
    from jsonb_array_elements(o.blockers) b;

  -- Account: she signs in with the email she gave on the form, so the account and the
  -- address on the client record both have to exist before anything is released.
  if coalesce(nullif(trim(cli.email),''), '') = '' then
    v_missing := array_append(v_missing,
      'no email on the client record — she would have nothing to sign in with'::text);
  elsif o.account_state not in ('created','existed') then
    v_missing := array_append(v_missing, 'sign-in account not created yet'::text);
  end if;

  -- Program
  if o.program_draft_id is null then
    v_missing := array_append(v_missing, 'no training program drafted'::text);
  else
    select * into drf from public.program_drafts where id = o.program_draft_id;
    if drf.status = 'held_medical' then
      v_missing := array_append(v_missing,
        'program is held for medical review — a human decides this one'::text);
    elsif drf.status = 'rejected' then
      v_missing := array_append(v_missing, 'program draft was rejected'::text);
    elsif jsonb_array_length(coalesce(drf.training->'days','[]'::jsonb)) = 0 then
      v_missing := array_append(v_missing, 'program draft has no training days in it'::text);
    end if;
  end if;

  -- Nutrition
  if o.meal_plan_id is null then
    v_missing := array_append(v_missing, 'no meal plan assembled'::text);
  else
    select * into mp from public.client_meal_plans where id = o.meal_plan_id;
    select count(*) into v_slots from public.client_meal_plan_slots where plan_id = o.meal_plan_id;
    if v_slots = 0 then
      v_missing := array_append(v_missing, 'meal plan exists but has no meals in it'::text);
    end if;
    if mp.status = 'archived' then
      v_missing := array_append(v_missing, 'meal plan was archived'::text);
    end if;
  end if;

  -- Rhythm
  select count(*) into v_ck from public.client_checkin_schedule
   where client_id = o.client_id and status = 'scheduled' and due_on >= current_date;
  if v_ck = 0 then
    v_missing := array_append(v_missing, 'no check-ins scheduled ahead'::text);
  end if;

  if v_blocks > 0 then
    v_missing := array_append(v_missing,
      format('%s unresolved blocker(s) on the onboarding record', v_blocks));
  end if;

  v_ready := (array_length(v_missing,1) is null);

  return jsonb_build_object(
    'status','ok',
    'ready', v_ready,
    'already_released', o.released_at is not null,
    'client_id', o.client_id,
    'client_name', cli.display_name,
    'client_type', cli.client_type,
    'missing', to_jsonb(v_missing),
    'blockers_hard', v_blocks,
    'blockers_review', v_reviews,
    'program_draft_id', o.program_draft_id,
    'meal_plan_id', o.meal_plan_id,
    'meal_slots', v_slots,
    'checkins_scheduled', v_ck,
    'account_state', o.account_state);
end $$;

--
-- Name: FUNCTION check_client_onboarding_readiness(p_onboarding_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_client_onboarding_readiness(p_onboarding_id uuid) IS 'Read-only. Reports exactly what is still missing before a client can be released, in plain language. Returns the gaps as facts; it never fills one in.';

--
-- Name: claim_client_invite(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_client_invite(p_token text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  uid uuid := auth.uid();
  v_confirmed timestamptz;
  v_client public.clients;
  v_role text;
begin
  if uid is null then return 'not_authenticated'; end if;
  if p_token is null or length(p_token) < 16 then return 'invalid'; end if;

  select email_confirmed_at into v_confirmed from auth.users where id = uid;
  if v_confirmed is null then return 'unconfirmed'; end if;

  select * into v_client from public.clients where invite_token = p_token;
  if not found then return 'invalid'; end if;

  if v_client.invite_expires_at is not null and v_client.invite_expires_at < now() then
    return 'expired';
  end if;

  if v_client.client_user_id is not null then
    if v_client.client_user_id = uid then return 'already_yours'; end if;
    return 'already_claimed';
  end if;

  if exists (select 1 from public.clients where client_user_id = uid) then
    return 'other_client';
  end if;

  select role::text into v_role from public.profiles where user_id = uid;
  if v_role is not null and v_role <> 'client' then return 'role_conflict'; end if;

  update public.clients
     set client_user_id    = uid,
         status            = case when status = 'invited' then 'active'::client_status else status end,
         invite_token      = null,
         invite_expires_at = null,
         updated_at        = now()
   where id = v_client.id;

  insert into public.profiles (user_id, role, tenant_id)
  values (uid, 'client', v_client.tenant_id)
  on conflict (user_id) do nothing;

  return 'claimed';
end;
$$;

--
-- Name: claim_my_client(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_my_client() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email text;
begin
  select email into v_email
    from auth.users
   where id = auth.uid() and email_confirmed_at is not null;
  if v_email is null then return 0; end if;
  return public.link_client_by_email(auth.uid(), v_email);
end;
$$;

--
-- Name: clients_guard_self_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clients_guard_self_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  blocked text[] := '{}';
begin
  -- Trusted callers pass straight through.
  --   service_role            -> supabase edge functions
  --   postgres/supabase_admin -> DBA work, and the body of any SECURITY DEFINER
  --                              function owned by postgres (the claim path, and
  --                              intake_match_or_create_client which legitimately
  --                              writes client_type on conversion)
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  -- The coach owns every client record in their tenant; clients_coach_all already
  -- scopes which rows they may touch.
  if public.current_app_role() = 'coach' then
    return new;
  end if;

  -- Anything else is a client editing their own row. They may change only their
  -- own profile details and notification preferences. Collect every protected
  -- column they attempted to change so the error names all of them at once.

  -- Identity and tenancy
  if new.id                     is distinct from old.id                     then blocked := array_append(blocked, 'id'); end if;
  if new.tenant_id              is distinct from old.tenant_id              then blocked := array_append(blocked, 'tenant_id'); end if;
  if new.client_user_id         is distinct from old.client_user_id         then blocked := array_append(blocked, 'client_user_id'); end if;

  -- Coach-controlled lifecycle
  if new.status                 is distinct from old.status                 then blocked := array_append(blocked, 'status'); end if;
  if new.joined_at              is distinct from old.joined_at              then blocked := array_append(blocked, 'joined_at'); end if;
  if new.email                  is distinct from old.email                  then blocked := array_append(blocked, 'email'); end if;
  if new.invite_token           is distinct from old.invite_token           then blocked := array_append(blocked, 'invite_token'); end if;
  if new.invite_expires_at      is distinct from old.invite_expires_at      then blocked := array_append(blocked, 'invite_expires_at'); end if;

  -- Commercial — the actual escalation vector
  if new.coaching_tier          is distinct from old.coaching_tier          then blocked := array_append(blocked, 'coaching_tier'); end if;
  if new.subscription_status    is distinct from old.subscription_status    then blocked := array_append(blocked, 'subscription_status'); end if;
  if new.stripe_customer_id     is distinct from old.stripe_customer_id     then blocked := array_append(blocked, 'stripe_customer_id'); end if;
  if new.stripe_subscription_id is distinct from old.stripe_subscription_id then blocked := array_append(blocked, 'stripe_subscription_id'); end if;

  -- Attestations: a client must never stamp their own verification/consent record
  if new.phone_verified_at      is distinct from old.phone_verified_at      then blocked := array_append(blocked, 'phone_verified_at'); end if;
  if new.sms_consent_at         is distinct from old.sms_consent_at         then blocked := array_append(blocked, 'sms_consent_at'); end if;
  if new.sms_consent_version    is distinct from old.sms_consent_version    then blocked := array_append(blocked, 'sms_consent_version'); end if;

  -- NEW 2026-07-31 — Coaching classification.
  -- client_type drives meal assembly and loop
  -- tagging. show_date/show_name drive the Prep rail. All three are the coach's
  -- judgment about the client, not the client's about himself.
  if new.client_type            is distinct from old.client_type            then blocked := array_append(blocked, 'client_type'); end if;
  if new.show_date              is distinct from old.show_date              then blocked := array_append(blocked, 'show_date'); end if;
  if new.show_name              is distinct from old.show_name              then blocked := array_append(blocked, 'show_name'); end if;

  if array_length(blocked, 1) is not null then
    -- 42501 = insufficient_privilege; PostgREST surfaces this as HTTP 403.
    raise exception 'clients: column(s) % are coach-controlled and cannot be changed by a client',
      array_to_string(blocked, ', ')
      using errcode = '42501';
  end if;

  return new;
end;
$$;

--
-- Name: FUNCTION clients_guard_self_update(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clients_guard_self_update() IS 'Blocks client-role writes to coach-controlled columns on public.clients. Coaches, service_role and SECURITY DEFINER callers (the claim path, intake_match_or_create_client) are exempt. Client-writable: display_name, welcome_seen, unit_pref, age, sex, height_cm, weight_kg, activity_level, body_fat_pct, phone_e164, notif_enabled, notif_channels, push_subscription. Coach-controlled additions 2026-07-31: client_type, show_date, show_name.';

--
-- Name: clients_sync_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clients_sync_units() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  lb_changed boolean := (tg_op='INSERT' and new.weight_lb is not null)
                     or (tg_op='UPDATE' and new.weight_lb is distinct from old.weight_lb);
  kg_changed boolean := (tg_op='INSERT' and new.weight_kg is not null)
                     or (tg_op='UPDATE' and new.weight_kg is distinct from old.weight_kg);
  in_changed boolean := (tg_op='INSERT' and new.height_in is not null)
                     or (tg_op='UPDATE' and new.height_in is distinct from old.height_in);
  cm_changed boolean := (tg_op='INSERT' and new.height_cm is not null)
                     or (tg_op='UPDATE' and new.height_cm is distinct from old.height_cm);
  glb_changed boolean := (tg_op='INSERT' and new.goal_weight_lb is not null)
                      or (tg_op='UPDATE' and new.goal_weight_lb is distinct from old.goal_weight_lb);
  gkg_changed boolean := (tg_op='INSERT' and new.goal_weight_kg is not null)
                      or (tg_op='UPDATE' and new.goal_weight_kg is distinct from old.goal_weight_kg);
begin
  if lb_changed and new.weight_lb is not null then
    new.weight_kg := round((new.weight_lb * 0.45359237)::numeric, 3);
  elsif kg_changed and new.weight_kg is not null then
    new.weight_lb := round((new.weight_kg / 0.45359237)::numeric, 2);
  end if;

  if in_changed and new.height_in is not null then
    new.height_cm := round((new.height_in * 2.54)::numeric, 2);
  elsif cm_changed and new.height_cm is not null then
    new.height_in := round((new.height_cm / 2.54)::numeric, 2);
  end if;

  if glb_changed and new.goal_weight_lb is not null then
    new.goal_weight_kg := round((new.goal_weight_lb * 0.45359237)::numeric, 3);
  elsif gkg_changed and new.goal_weight_kg is not null then
    new.goal_weight_lb := round((new.goal_weight_kg / 0.45359237)::numeric, 2);
  end if;

  return new;
end $$;

--
-- Name: coach_inbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coach_inbox() RETURNS TABLE(client_id uuid, display_name text, last_body text, last_sender_role public.sender_role, last_sent_at timestamp with time zone, unread_count integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with last_msg as (
    select distinct on (m.client_id)
      m.client_id, m.body, m.sender_role, m.sent_at
    from messages m
    where m.tenant_id = current_tenant_id()
    order by m.client_id, m.sent_at desc
  ),
  unread as (
    select m.client_id, count(*)::int as cnt
    from messages m
    left join message_reads r
      on r.client_id = m.client_id
     and r.reader_user_id = auth.uid()
    where m.tenant_id = current_tenant_id()
      and m.sender_role = 'client'
      and (r.last_read_at is null or m.sent_at > r.last_read_at)
    group by m.client_id
  )
  select lm.client_id,
         c.display_name,
         lm.body,
         lm.sender_role,
         lm.sent_at,
         coalesce(u.cnt, 0)
  from last_msg lm
  join clients c on c.id = lm.client_id
  left join unread u on u.client_id = lm.client_id
  order by lm.sent_at desc;
$$;

--
-- Name: complete_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_session(p_session_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cid uuid := public.current_client_id(); s public.workout_sessions;
begin
  select * into s from public.workout_sessions where id = p_session_id;
  if s.id is null or s.client_id <> cid then raise exception 'not your session'; end if;
  update public.workout_sessions set status = 'complete', completed_at = now(), updated_at = now() where id = p_session_id;
  update public.assignments set current_day_index = current_day_index + 1, updated_at = now() where id = s.assignment_id and client_id = cid;
end $$;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: checkin_assessments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.checkin_assessments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    checkin_id uuid NOT NULL,
    client_id uuid NOT NULL,
    summary text,
    summary_model text,
    summary_generated_at timestamp with time zone,
    excluded_fields jsonb DEFAULT '[]'::jsonb NOT NULL,
    proposed_tag text,
    proposed_evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    proposed_at timestamp with time zone,
    no_tag_reason text,
    confirmed_tag text,
    confirmed_by uuid,
    confirmed_at timestamp with time zone,
    needs_review boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT checkin_assessments_confirmed_tag_check CHECK (((confirmed_tag IS NULL) OR (confirmed_tag = ANY (ARRAY['M01'::text, 'M02'::text, 'M03'::text, 'M04'::text, 'M05'::text])))),
    CONSTRAINT checkin_assessments_proposed_tag_check CHECK (((proposed_tag IS NULL) OR (proposed_tag = ANY (ARRAY['M01'::text, 'M02'::text, 'M03'::text, 'M04'::text, 'M05'::text]))))
);

--
-- Name: TABLE checkin_assessments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.checkin_assessments IS 'Coach''s read of a check-in: summary + Default Paralysis Loop position. The proposed tag is a MACHINE PROPOSAL and is never authoritative. Any consumer that drives an action must read confirmed_tag and must NOT fall back to proposed_tag. A wrong loop tag is worse than no tag, because the coach would act on it. Coach-only: never expose to a client-scoped token.';

--
-- Name: COLUMN checkin_assessments.excluded_fields; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.checkin_assessments.excluded_fields IS 'Fields the summary deliberately did not speak to. reason=blank is the CLIENT''s fact (he was asked, answered nothing — real signal). reason=not_asked is the SYSTEM''s fact (never instrumented — the coach''s gap, never a client failing). These two must never render alike.';

--
-- Name: COLUMN checkin_assessments.proposed_tag; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.checkin_assessments.proposed_tag IS 'Machine proposal. Display-only. Counts toward no streak, triggers no automation, and never becomes confirmed by ageing.';

--
-- Name: COLUMN checkin_assessments.no_tag_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.checkin_assessments.no_tag_reason IS 'Why no tag was proposed. Stored, not inferred from a null. "Could not tell" is a finding to report, not an absence to render quietly.';

--
-- Name: COLUMN checkin_assessments.confirmed_tag; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.checkin_assessments.confirmed_tag IS 'The coach''s position. NO DEFAULT and NO FALLBACK — nothing anywhere coalesces proposed_tag into this column. NULL means he has not looked yet, which is a real and visible state.';

--
-- Name: confirm_checkin_tag(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_checkin_tag(p_assessment_id uuid, p_tag text, p_reason text DEFAULT NULL::text) RETURNS public.checkin_assessments
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_row public.checkin_assessments;
  v_old text;
begin
  if current_app_role() <> 'coach' then
    raise exception 'confirm_checkin_tag: coach only' using errcode = '42501';
  end if;
  if p_tag is null or p_tag not in ('M01','M02','M03','M04','M05') then
    raise exception 'confirm_checkin_tag: tag must be M01..M05, got %', coalesce(p_tag,'null')
      using errcode = '22023';
  end if;

  select proposed_tag into v_old from public.checkin_assessments where id = p_assessment_id;

  update public.checkin_assessments
     set confirmed_tag = p_tag,
         confirmed_by  = auth.uid(),
         confirmed_at  = now(),
         needs_review  = false
   where id = p_assessment_id
   returning * into v_row;

  if v_row.id is null then
    raise exception 'confirm_checkin_tag: assessment not found' using errcode = 'P0002';
  end if;

  -- The coach disagreed with the machine (or there was nothing to agree with).
  -- That is a correction and it goes on the permanent record.
  if v_old is distinct from p_tag then
    insert into public.checkin_tag_corrections
      (tenant_id, assessment_id, checkin_id, client_id, from_tag, to_tag, reason, corrected_by)
    values
      (v_row.tenant_id, v_row.id, v_row.checkin_id, v_row.client_id, v_old, p_tag, p_reason, auth.uid());
  end if;

  return v_row;
end;
$$;

--
-- Name: FUNCTION confirm_checkin_tag(p_assessment_id uuid, p_tag text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_checkin_tag(p_assessment_id uuid, p_tag text, p_reason text) IS 'The coach sets the confirmed position. Writes a correction row whenever the confirmed tag differs from what was proposed — including when nothing was proposed. Coach-only.';

--
-- Name: confirm_client_body_metrics(uuid, integer, text, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_client_body_metrics(p_client_id uuid, p_age integer DEFAULT NULL::integer, p_sex text DEFAULT NULL::text, p_height_in numeric DEFAULT NULL::numeric, p_weight_lb numeric DEFAULT NULL::numeric, p_goal_weight_lb numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant   uuid;
  v_caller   uuid := auth.uid();
  v_role     text;
  v_missing  text[] := '{}';
  v_bad      text[] := '{}';
  v_client   public.clients%rowtype;
begin
  if v_caller is null then
    raise exception 'confirm_client_body_metrics: authentication required' using errcode = '42501';
  end if;

  select tenant_id, role into v_tenant, v_role
    from public.profiles where user_id = v_caller;
  if v_role is distinct from 'coach' then
    raise exception 'confirm_client_body_metrics: coach only' using errcode = '42501';
  end if;

  select * into v_client from public.clients where id = p_client_id;
  if not found then
    raise exception 'confirm_client_body_metrics: no such client' using errcode = 'P0002';
  end if;
  if v_client.tenant_id is distinct from v_tenant then
    raise exception 'confirm_client_body_metrics: client is not in your tenant' using errcode = '42501';
  end if;

  -- Every value is required. A partial confirmation would leave the record in exactly the
  -- state this function exists to end -- half-populated, and therefore trusted.
  if p_age            is null then v_missing := v_missing || 'age';            end if;
  if nullif(btrim(coalesce(p_sex,'')),'') is null
                             then v_missing := v_missing || 'sex';             end if;
  if p_height_in      is null then v_missing := v_missing || 'height';         end if;
  if p_weight_lb      is null then v_missing := v_missing || 'weight';         end if;
  if p_goal_weight_lb is null then v_missing := v_missing || 'goal weight';    end if;

  if array_length(v_missing, 1) is not null then
    return jsonb_build_object(
      'status','refused', 'reason','incomplete', 'missing', to_jsonb(v_missing),
      'detail', format(
        'Not written. These are still unstated: %s. A body metric is a fact about one '
        'specific person; the record stays empty until someone supplies it, because an '
        'empty field asks a question and a filled-in guess ends one.',
        array_to_string(v_missing, ', ')));
  end if;

  -- Range checks. Out of range is treated as unstated, never clamped: a clamp is a quieter
  -- way of substituting a number nobody supplied.
  if p_age < 14 or p_age > 90                     then v_bad := v_bad || format('age %s is outside 14-90', p_age); end if;
  if p_sex not in ('male','female','other')       then v_bad := v_bad || format('sex "%s" is not male, female or other', p_sex); end if;
  if p_height_in < 48 or p_height_in > 90         then v_bad := v_bad || format('height %s in is outside 4''0"-7''6"', p_height_in); end if;
  if p_weight_lb < 70 or p_weight_lb > 600        then v_bad := v_bad || format('weight %s lb is outside 70-600', p_weight_lb); end if;
  if p_goal_weight_lb < 70 or p_goal_weight_lb > 600 then v_bad := v_bad || format('goal weight %s lb is outside 70-600', p_goal_weight_lb); end if;

  if array_length(v_bad, 1) is not null then
    return jsonb_build_object(
      'status','refused', 'reason','out_of_range', 'problems', to_jsonb(v_bad),
      'detail', array_to_string(v_bad, '; ') || '. Nothing was written.');
  end if;

  -- Imperial in; the sync trigger derives kg and cm.
  update public.clients
     set age            = p_age,
         sex            = lower(btrim(p_sex)),
         height_in      = p_height_in,
         weight_lb      = p_weight_lb,
         goal_weight_lb = p_goal_weight_lb,
         unit_pref      = coalesce(unit_pref, 'imperial'),
         updated_at     = now()
   where id = p_client_id
   returning * into v_client;

  -- Clear the blockers this confirmation actually answers, on every open onboarding for
  -- this client. Blockers for anything else are left exactly where they are.
  update public.client_onboarding co
     set blockers = (
           select coalesce(jsonb_agg(b), '[]'::jsonb)
             from jsonb_array_elements(co.blockers) b
            where b->>'code' not in (
              'intake_missing_age', 'intake_missing_sex', 'intake_missing_height_cm',
              'intake_missing_weight_kg', 'intake_missing_goal_weight_kg', 'missing_goal_weight')),
         updated_at = now()
   where co.client_id = p_client_id;

  perform public.onboarding_recompute_stage(co.id)
     from public.client_onboarding co where co.client_id = p_client_id;

  return jsonb_build_object(
    'status','confirmed',
    'client_id', p_client_id,
    'confirmed_by', v_caller,
    'confirmed_at', now(),
    'imperial', jsonb_build_object(
      'age', v_client.age, 'sex', v_client.sex, 'height_in', v_client.height_in,
      'weight_lb', v_client.weight_lb, 'goal_weight_lb', v_client.goal_weight_lb),
    -- Echoed back so the caller can see what the generator will actually read, rather than
    -- trusting that the conversion happened.
    'metric_derived', jsonb_build_object(
      'height_cm', v_client.height_cm, 'weight_kg', v_client.weight_kg,
      'goal_weight_kg', v_client.goal_weight_kg),
    'note', case when v_client.sex = 'other'
      then 'Recorded. Note: the Mifflin-St Jeor equation the generator uses has coefficients '
           'for male and female only. It has none for "other", so it will still decline to '
           'compute a calorie target for this client and the coach sets it by hand. That is a '
           'limit of the formula, stated rather than papered over.'
      else 'Recorded. The generator reads the derived metric values above.' end);
end $$;

--
-- Name: FUNCTION confirm_client_body_metrics(p_client_id uuid, p_age integer, p_sex text, p_height_in numeric, p_weight_lb numeric, p_goal_weight_lb numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_client_body_metrics(p_client_id uuid, p_age integer, p_sex text, p_height_in numeric, p_weight_lb numeric, p_goal_weight_lb numeric) IS 'Coach-confirms a client''s body metrics from their intake. Imperial in (lb/in); metric is derived by clients_sync_units(). Refuses on any unstated or out-of-range value rather than writing a partial record. Clears only the body-metric onboarding blockers it answers.';

--
-- Name: current_app_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_app_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'user_role', ''),
    (select role::text from public.profiles where user_id = auth.uid())
  );
$$;

--
-- Name: current_client_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_client_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select id from public.clients where client_user_id = auth.uid();
$$;

--
-- Name: current_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_tenant_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'tenant_id', '')::uuid,
    (select tenant_id from public.profiles where user_id = auth.uid())
  );
$$;

--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare claims jsonb := event -> 'claims'; p record;
begin
  select role::text as role, tenant_id into p from public.profiles where user_id = (event ->> 'user_id')::uuid;
  if p.tenant_id is not null then
    claims := jsonb_set(claims, '{tenant_id}', to_jsonb(p.tenant_id));
    claims := jsonb_set(claims, '{user_role}', to_jsonb(p.role));
  end if;
  return jsonb_set(event, '{claims}', claims);
end $$;

--
-- Name: enforce_tenant_not_suspended(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tenant_not_suspended() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  t uuid;
begin
  -- System callers pass straight through (service_role, postgres, SECURITY DEFINER bodies).
  if current_user not in ('authenticated', 'anon') then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  t := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;

  if t is not null and public.tenant_is_suspended(t) then
    raise exception 'This app is paused: its hosting subscription has lapsed. Existing data stays readable, but new changes are unavailable until it is reactivated.'
      using errcode = '42501';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

--
-- Name: FUNCTION enforce_tenant_not_suspended(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_tenant_not_suspended() IS 'Refuses INSERT/UPDATE/DELETE from an app session when the row''s tenant is suspended. service_role and SECURITY DEFINER callers are exempt so that un-suspending remains possible.';

--
-- Name: get_app_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_config() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select tc.published_snapshot from public.tenant_config tc
   where tc.tenant_id = public.current_tenant_id() and tc.published_snapshot is not null;
$$;

--
-- Name: intake_match_or_create_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intake_match_or_create_client(p_submission_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s            public.intake_submissions%rowtype;
  v_email      text;
  v_matches    int;
  v_client     public.clients%rowtype;
  v_client_id  uuid;
  v_onb_id     uuid;
  v_outcome    text;
begin
  select * into s from public.intake_submissions where id = p_submission_id;
  if not found then return jsonb_build_object('status','error','reason','submission_not_found'); end if;

  v_email := lower(nullif(trim(s.email), ''));
  if v_email is null then
    return jsonb_build_object('status','blocked','reason','no_email',
      'detail','The submission carries no email address. An account cannot be created and the '
               'client cannot sign in. Ask for the address before onboarding.');
  end if;

  if s.client_id is not null then
    select id into v_onb_id from public.client_onboarding
      where submission_id = s.id and client_id = s.client_id;
    return jsonb_build_object('status','ok','outcome','already_converted',
      'client_id', s.client_id, 'onboarding_id', v_onb_id);
  end if;

  select count(*) into v_matches
    from public.clients c
   where c.tenant_id = s.tenant_id and lower(trim(c.email)) = v_email;

  if v_matches > 1 then
    return jsonb_build_object('status','blocked','reason','ambiguous_email_match',
      'detail', format('%s existing client records in this tenant share the address %s. '
                       'Which one this submission belongs to is not knowable from the data. '
                       'Merge or correct the duplicates before converting.', v_matches, v_email));
  end if;

  if v_matches = 1 then
    select * into v_client from public.clients c
      where c.tenant_id = s.tenant_id and lower(trim(c.email)) = v_email;
    v_client_id := v_client.id;
    v_outcome := 'matched_existing';
  else
    insert into public.clients (tenant_id, display_name, email, status)
    values (s.tenant_id,
            coalesce(nullif(trim(s.full_name), ''), split_part(v_email,'@',1)),
            v_email, 'invited')
    returning * into v_client;
    v_client_id := v_client.id;
    v_outcome := 'created';
  end if;

  -- Carry the lifestyle/prep switch forward. CHECK-constrained on both sides, so an
  -- unstated value stays NULL and becomes a named blocker below.
  --
  -- CHANGED 2026-07-31: goal_weight_lb is no longer parsed from the raw string here.
  -- parse_goal_weight_lb() reads "165-170" as 167.5 and stores it in a POUNDS column
  -- without the form ever having said pounds. That is the same unit assumption that made
  -- a 95 kg client indistinguishable from a 210 kg one -- silently, and on the field the
  -- protein target is computed from. Goal weight now arrives only through
  -- confirm_client_body_metrics(), where a human states the unit.
  update public.clients
     set client_type = coalesce(client_type, s.client_type),
         updated_at  = now()
   where id = v_client_id;

  update public.client_allergies
     set client_id = v_client_id, updated_at = now()
   where submission_id = s.id and client_id is null;
  update public.client_dietary_restrictions
     set client_id = v_client_id, updated_at = now()
   where submission_id = s.id and client_id is null;

  update public.intake_submissions
     set client_id = v_client_id, status = 'converted', reviewed_at = coalesce(reviewed_at, now()),
         updated_at = now()
   where id = s.id;

  -- The onboarding row is created BEFORE any blocker is raised against it. This ordering
  -- is the bug fix: every blocker below now has a row to land on.
  insert into public.client_onboarding (tenant_id, client_id, submission_id, stage)
  values (s.tenant_id, v_client_id, s.id, 'started')
  on conflict (client_id, submission_id) do update set updated_at = now()
  returning id into v_onb_id;

  if (select goal_weight_lb from public.clients where id = v_client_id) is null then
    perform public.onboarding_add_blocker(v_onb_id, 'missing_goal_weight',
      format('No confirmed goal weight on this client. The intake said "%s", which carries no '
             'unit, so it was not written. Protein is computed off goal weight and is never '
             'substituted with current weight. Confirm it under Profile -> body metrics.',
             coalesce(nullif(s.goal_weight_raw,''), '(blank)')), 'block');
  end if;

  if v_outcome = 'matched_existing'
     and nullif(trim(s.full_name),'') is not null
     and lower(trim(v_client.display_name)) <> lower(trim(s.full_name)) then
    perform public.onboarding_add_blocker(v_onb_id, 'name_mismatch',
      format('The submission says "%s"; the existing record on %s says "%s". Same address, '
             'different name -- confirm this is the same person before releasing.',
             trim(s.full_name), v_email, v_client.display_name), 'review');
  end if;

  if (select client_type from public.clients where id = v_client_id) is null then
    perform public.onboarding_add_blocker(v_onb_id, 'client_type_unstated',
      'The intake did not state lifestyle or competition prep. This changes both the training '
      'draft and the meal assembly, so it cannot be assumed. Set it on the client record and '
      're-run.', 'block');
  end if;

  -- Body metrics have never been written by anything. Say so on every new onboarding
  -- rather than letting the generator discover it three steps later.
  if exists (
    select 1 from public.clients
     where id = v_client_id
       and (age is null or sex is null or height_in is null or weight_lb is null))
  then
    perform public.onboarding_add_blocker(v_onb_id, 'body_metrics_unconfirmed',
      format('Body metrics are not confirmed on this client. The intake carried age "%s", '
             'height "%s", weight "%s" as raw text, and the form does not ask sex at all. '
             'Nothing is read from those strings automatically. Open Profile -> body metrics, '
             'check them against the intake and confirm.',
             coalesce(nullif(s.age_raw,''),'(blank)'),
             coalesce(nullif(s.height_raw,''),'(blank)'),
             coalesce(nullif(s.weight_raw,''),'(blank)')), 'block');
  end if;

  return jsonb_build_object('status','ok','outcome',v_outcome,
    'client_id', v_client_id, 'onboarding_id', v_onb_id, 'email', v_email);
end $$;

--
-- Name: FUNCTION intake_match_or_create_client(p_submission_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.intake_match_or_create_client(p_submission_id uuid) IS 'Turns an intake_submissions row into a client record. Matches on email within the tenant: zero matches creates, one match attaches, MORE THAN ONE STOPS — merging two people is a guess this function refuses to make. Also re-points the parsed allergy/dietary rows at the client without upgrading their confidence.';

--
-- Name: link_client_by_email(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_client_by_email(p_user_id uuid, p_email text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_linked int;
  v_tenant uuid;
begin
  if p_email is null or p_user_id is null then return 0; end if;
  -- clients_user_unique: one auth user ↔ at most one clients row (schema-enforced).
  -- An already-linked user never claims another row; a multi-tenant email links the
  -- oldest matching row only.
  if exists (select 1 from public.clients where client_user_id = p_user_id) then
    return 0;
  end if;

  update public.clients c
     set client_user_id = p_user_id, updated_at = now()
   where c.id = (
     select id from public.clients
      where client_user_id is null and lower(email) = lower(p_email)
      order by joined_at asc limit 1
   );
  get diagnostics v_linked = row_count;

  if v_linked > 0 and not exists (select 1 from public.profiles where user_id = p_user_id) then
    select tenant_id into v_tenant
      from public.clients where client_user_id = p_user_id limit 1;
    insert into public.profiles (user_id, role, tenant_id)
    values (p_user_id, 'client', v_tenant)
    on conflict (user_id) do nothing;
  end if;
  return v_linked;
end;
$$;

--
-- Name: mark_thread_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_thread_read(p_client_id uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  insert into public.message_reads (tenant_id, client_id, reader_user_id, last_read_at)
  values (current_tenant_id(), p_client_id, auth.uid(), now())
  on conflict (tenant_id, client_id, reader_user_id)
  do update set last_read_at = excluded.last_read_at;
$$;

--
-- Name: messages_guard_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.messages_guard_integrity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  blocked text[] := '{}';
begin
  -- service_role / postgres (importer, DBA, SECURITY DEFINER bodies) pass through.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  -- Authorship and routing can never change once a message exists.
  if new.sender_role is distinct from old.sender_role then blocked := array_append(blocked, 'sender_role'); end if;
  if new.client_id   is distinct from old.client_id   then blocked := array_append(blocked, 'client_id'); end if;
  if new.tenant_id   is distinct from old.tenant_id   then blocked := array_append(blocked, 'tenant_id'); end if;
  if new.sent_at     is distinct from old.sent_at     then blocked := array_append(blocked, 'sent_at'); end if;

  if array_length(blocked, 1) is not null then
    raise exception 'messages: % cannot be changed after a message is sent',
      array_to_string(blocked, ', ')
      using errcode = '42501';
  end if;

  -- A coach may not edit what a client wrote. (Clients can no longer update at
  -- all, so this rule bites only on the coach's ALL policy.)
  if old.sender_role = 'client' and new.body is distinct from old.body then
    raise exception 'messages: a message written by the client cannot be edited'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

--
-- Name: FUNCTION messages_guard_integrity(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.messages_guard_integrity() IS 'Freezes sender_role, client_id, tenant_id and sent_at on public.messages after insert, and stops a coach rewriting a client-authored body. service_role and SECURITY DEFINER callers are exempt.';

--
-- Name: on_auth_user_confirmed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.on_auth_user_confirmed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.email_confirmed_at is not null then
    perform public.link_client_by_email(new.id, new.email);
  end if;
  return new;
end;
$$;

--
-- Name: onboarding_add_blocker(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_add_blocker(p_onboarding_id uuid, p_code text, p_detail text, p_severity text DEFAULT 'block'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.client_onboarding
     set blockers = (
           select coalesce(jsonb_agg(b), '[]'::jsonb)
             from jsonb_array_elements(blockers) b
            where b->>'code' is distinct from p_code
         ) || jsonb_build_object(
           'code', p_code, 'detail', p_detail, 'severity', p_severity, 'at', now())
   where id = p_onboarding_id;

  perform public.onboarding_recompute_stage(p_onboarding_id);
end $$;

--
-- Name: FUNCTION onboarding_add_blocker(p_onboarding_id uuid, p_code text, p_detail text, p_severity text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.onboarding_add_blocker(p_onboarding_id uuid, p_code text, p_detail text, p_severity text) IS 'severity=''block'' stops release and is a missing input a human must resolve. severity=''review'' is a stated assumption that the coach should see and confirm but that does not by itself hold the release. Both stay visible; neither is ever silently resolved.';

--
-- Name: onboarding_clear_blockers(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_clear_blockers(p_onboarding_id uuid, p_codes text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.client_onboarding
     set blockers = (
           select coalesce(jsonb_agg(b), '[]'::jsonb)
             from jsonb_array_elements(blockers) b
            where not (b->>'code' = any(p_codes))
         )
   where id = p_onboarding_id;

  perform public.onboarding_recompute_stage(p_onboarding_id);
end $$;

--
-- Name: FUNCTION onboarding_clear_blockers(p_onboarding_id uuid, p_codes text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.onboarding_clear_blockers(p_onboarding_id uuid, p_codes text[]) IS 'Removes blockers whose cause a later successful step has resolved. Only the step that owns a code may clear it — nothing clears a blocker just because time passed.';

--
-- Name: onboarding_recompute_stage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_recompute_stage(p_onboarding_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_hard int;
begin
  select count(*) into v_hard
    from public.client_onboarding o, jsonb_array_elements(o.blockers) b
   where o.id = p_onboarding_id and b->>'severity' = 'block';

  update public.client_onboarding
     set stage = case
           when released_at is not null then 'released'
           when v_hard > 0 then 'blocked'
           when program_draft_id is not null and meal_plan_id is not null then 'prepared'
           else 'started' end
   where id = p_onboarding_id;
end $$;

--
-- Name: parse_goal_weight_lb(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_goal_weight_lb(p_raw text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  nums numeric[];
begin
  if p_raw is null or btrim(p_raw) = '' then return null; end if;
  select array_agg((m[1])::numeric)
    into nums
    from regexp_matches(p_raw, '([0-9]+(?:\.[0-9]+)?)', 'g') m;
  if nums is null or array_length(nums,1) = 0 then return null; end if;
  if array_length(nums,1) = 1 then return nums[1]; end if;
  -- Range: midpoint of the lowest and highest figures present.
  return round(((select min(x) from unnest(nums) x) + (select max(x) from unnest(nums) x)) / 2.0, 2);
end $$;

--
-- Name: FUNCTION parse_goal_weight_lb(p_raw text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.parse_goal_weight_lb(p_raw text) IS 'Range rule: MIDPOINT. "165-170" -> 167.5. Single number returns as-is. Unparseable returns NULL, never a substitute.';

--
-- Name: parse_intake_health_data(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_intake_health_data() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_allergy  text := coalesce(new.answers->>'Allergies and intolerances','');
  v_gut      text := trim(coalesce(new.answers->>'Digestive tolerances','') || ' ' || coalesce(new.answers->>'Bloat triggers',''));
  v_excluded text := coalesce(new.answers->>'Foods excluded','');
  v_eating   text := coalesce(new.answers->>'Normal day of eating','');
  v_none     text := '^\s*(none|n/a|na|no|nope|nothing|none that i know of|not that i know of|-|—)\s*[.!]?\s*$';
  -- Language that asserts a clinical condition rather than describing digestion.
  v_claim    text := 'allerg|intoleran|anaphyla|epipen|epi-pen|epi pen|throat clos|celiac|coeliac';
  v_declared_none boolean;
  v_gut_claim     boolean;
  v_sev      text;
  v_n        int;
begin
  -- Answered-and-negated is a declaration. Blank is not: blank means nobody got
  -- an answer, which is a different fact and must never be read as "no".
  v_declared_none := (v_allergy <> '' and v_allergy ~* v_none);
  v_gut_claim     := (v_gut ~* v_claim);

  v_sev := case
    when v_allergy ~* 'anaphyla|epipen|epi-pen|epi pen|throat clos' then 'anaphylaxis'
    when v_allergy ~* 'allerg' then 'allergy'
    when v_allergy ~* 'intoleran|sensitiv|lactose' then 'intolerance'
    else 'unknown' end;

  -- Block 1 -- the allergies question itself. Behaviour unchanged from original.
  if v_allergy <> '' and not v_declared_none then
    insert into public.client_allergies
      (tenant_id, client_id, submission_id, allergen_key, allergen_label, severity, raw_text, source, confidence, needs_review)
    select distinct on (d.k) new.tenant_id, null, new.id, d.k, d.label, v_sev, v_allergy, 'intake', 'parsed', true
    from public.allergen_dictionary d
    where lower(v_allergy) ~ ('\m' || d.term)
    order by d.k, d.priority;
    get diagnostics v_n = row_count;
    if v_n = 0 then
      insert into public.client_allergies
        (tenant_id, client_id, submission_id, allergen_key, allergen_label, severity, raw_text, source, confidence, needs_review)
      values (new.tenant_id, null, new.id, 'unparsed', 'Unparsed — read raw_text', v_sev, v_allergy, 'intake', 'parsed', true);
    end if;
  end if;

  -- Block 2 -- digestive prose. THE FIXED BLOCK.
  if v_gut <> '' and v_gut !~* v_none then

    if v_declared_none and not v_gut_claim then
      -- She answered "None", and this text describes digestion rather than
      -- asserting a condition. It informs the plan; it does not gate it.
      insert into public.client_dietary_restrictions
        (tenant_id, client_id, submission_id, kind, restriction_key, restriction_label, raw_text, source, confidence, needs_review)
      select distinct on (d.k) new.tenant_id, null, new.id, 'preference', d.k, d.label, v_gut, 'intake', 'parsed', true
      from public.allergen_dictionary d
      where lower(v_gut) ~ ('\m' || d.term)
        and not exists (select 1 from public.client_dietary_restrictions r
                         where r.submission_id = new.id and r.restriction_key = d.k)
      order by d.k, d.priority;

    else
      -- Either there is no declaration to defer to (allergies left blank), or
      -- the prose asserts a clinical condition that contradicts it. Both keep
      -- the original gating behaviour and land in front of a human.
      insert into public.client_allergies
        (tenant_id, client_id, submission_id, allergen_key, allergen_label, severity, raw_text, source, confidence, needs_review)
      select distinct on (d.k) new.tenant_id, null, new.id, d.k, d.label,
             case when v_gut ~* 'anaphyla|epipen|epi-pen|epi pen|throat clos' then 'anaphylaxis'
                  else 'intolerance' end,
             v_gut, 'intake', 'parsed', true
      from public.allergen_dictionary d
      where lower(v_gut) ~ ('\m' || d.term)
        and not exists (select 1 from public.client_allergies ca where ca.submission_id = new.id and ca.allergen_key = d.k)
      order by d.k, d.priority;
    end if;

  end if;

  -- Block 3 -- dietary patterns. Unchanged.
  insert into public.client_dietary_restrictions
    (tenant_id, client_id, submission_id, kind, restriction_key, restriction_label, raw_text, source, confidence, needs_review)
  select distinct on (p.k) new.tenant_id, null, new.id, 'pattern', p.k, p.label, v_excluded, 'intake', 'parsed', true
  from public.dietary_pattern_dictionary p
  where lower(v_excluded || ' ' || v_eating) ~ ('\m' || p.term)
  order by p.k, p.priority;

  -- Block 4 -- explicit food exclusions. Unchanged.
  if v_excluded <> '' and v_excluded !~* v_none then
    insert into public.client_dietary_restrictions
      (tenant_id, client_id, submission_id, kind, restriction_key, restriction_label, raw_text, source, confidence, needs_review)
    select distinct on (d.k) new.tenant_id, null, new.id, 'exclusion', d.k, d.label, v_excluded, 'intake', 'parsed', true
    from public.allergen_dictionary d
    where lower(v_excluded) ~ ('\m' || d.term)
    order by d.k, d.priority;
    if not exists (select 1 from public.client_dietary_restrictions r where r.submission_id = new.id) then
      insert into public.client_dietary_restrictions
        (tenant_id, client_id, submission_id, kind, restriction_key, restriction_label, raw_text, source, confidence, needs_review)
      values (new.tenant_id, null, new.id, 'exclusion', 'unparsed', 'Unparsed — read raw_text', v_excluded, 'intake', 'parsed', true);
    end if;
  end if;

  return new;
end; $_$;

--
-- Name: provision_coach(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_coach(p_app_name text, p_display_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare uid uuid := auth.uid(); base text; s text; n int := 0; new_t uuid;
begin
  if uid is null then raise exception 'not authenticated'; end if;
  if exists (select 1 from public.profiles where user_id = uid) then return (select tenant_id from public.profiles where user_id = uid); end if;
  base := regexp_replace(lower(coalesce(nullif(p_app_name,''),'coach')), '[^a-z0-9]+', '-', 'g');
  base := trim(both '-' from base);
  if base = '' then base := 'coach'; end if;
  s := base;
  while exists (select 1 from public.tenants where slug = s) loop n := n + 1; s := base || '-' || n; end loop;
  insert into public.tenants(coach_user_id, slug) values (uid, s) returning id into new_t;
  insert into public.profiles(user_id, role, tenant_id) values (uid, 'coach', new_t);
  insert into public.tenant_config(tenant_id, app_name, coach_display_name) values (new_t, coalesce(nullif(p_app_name,''),'My Coaching App'), coalesce(nullif(p_display_name,''),'Coach'));
  return new_t;
end $$;

--
-- Name: publish_program_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_program_draft(p_draft_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  d public.program_drafts%rowtype;
  cli public.clients%rowtype;
  new_program_id uuid;
  v_meal_plan jsonb;
begin
  select * into d from public.program_drafts where id = p_draft_id;
  if not found then raise exception 'draft % not found', p_draft_id; end if;
  if d.status = 'published' and d.published_program_id is not null then
    return d.published_program_id;  -- idempotent
  end if;
  if jsonb_array_length(coalesce(d.training->'days','[]'::jsonb)) = 0 then
    raise exception 'refusing to publish an empty training plan (draft %)', p_draft_id;
  end if;

  select * into cli from public.clients where id = d.client_id;

  -- A hold marker is not a nutrition plan. Never let one reach a live program.
  v_meal_plan := case
    when jsonb_typeof(d.meal_plan) = 'object'
     and (d.meal_plan ? 'held_for_medical_review' or d.meal_plan ? 'held_for_missing_metrics')
    then null
    else d.meal_plan
  end;

  insert into public.programs (tenant_id, name, structure, meal_plan, source_draft_id, is_default)
  values (d.tenant_id,
          'Plan — ' || coalesce(cli.display_name,'Client') || ' — ' || to_char(now(),'YYYY-MM-DD'),
          d.training, v_meal_plan, d.id, false)
  returning id into new_program_id;

  -- one active assignment per client
  update public.assignments set active = false, updated_at = now()
    where client_id = d.client_id and active = true;
  insert into public.assignments (tenant_id, client_id, program_id, active)
  values (d.tenant_id, d.client_id, new_program_id, true);

  update public.program_drafts
    set status = 'published', published_program_id = new_program_id,
        decided_at = coalesce(decided_at, now())
    where id = d.id;

  update public.clients set status = 'active', updated_at = now()
    where id = d.client_id and status <> 'active';

  return new_program_id;
end;
$$;

--
-- Name: publish_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_tenant() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare tid uuid := public.current_tenant_id(); cfg public.tenant_config; snap jsonb; progs jsonb; res jsonb;
begin
  if public.current_app_role() <> 'coach' then raise exception 'only a coach may publish'; end if;
  select * into cfg from public.tenant_config where tenant_id = tid;
  if cfg.tenant_id is null then raise exception 'no config'; end if;
  select coalesce(jsonb_object_agg(p.id::text, jsonb_build_object('id', p.id, 'name', p.name, 'structure', p.structure)), '{}'::jsonb) into progs from public.programs p where p.tenant_id = tid;
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'title', r.title, 'type', r.type, 'file_url', r.file_url, 'sort', r.sort) order by r.sort), '[]'::jsonb) into res from public.resources r where r.tenant_id = tid;
  snap := jsonb_build_object(
    'version', cfg.version + 1,
    'brand', jsonb_build_object('logo_url', cfg.logo_url, 'app_name', cfg.app_name, 'coach_display_name', cfg.coach_display_name, 'theme_key', cfg.theme_key, 'welcome_message', cfg.welcome_message, 'welcome_video_url', cfg.welcome_video_url),
    'about', jsonb_build_object('about_headline', cfg.about_headline, 'about_body', cfg.about_body, 'about_photo_url', cfg.about_photo_url, 'framework_name', cfg.framework_name, 'framework_body', cfg.framework_body, 'framework_media_url', cfg.framework_media_url, 'bio_body', cfg.bio_body, 'bio_photo_url', cfg.bio_photo_url),
    'loop', jsonb_build_object('checkin_cadence', cfg.checkin_cadence, 'checkin_fields', cfg.checkin_fields, 'progress_weight_on', cfg.progress_weight_on, 'progress_photos_on', cfg.progress_photos_on, 'messaging_on', cfg.messaging_on, 'weight_unit', cfg.weight_unit),
    'programs', progs, 'resources', res);
  update public.tenant_config set published_snapshot = snap, version = cfg.version + 1, published_at = now(), updated_at = now() where tenant_id = tid;
  return snap;
end $$;

--
-- Name: record_consent(public.consent_event_type, public.notif_channel, text, text, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_consent(p_event_type public.consent_event_type, p_channel public.notif_channel DEFAULT NULL::public.notif_channel, p_phone text DEFAULT NULL::text, p_disclosures_version text DEFAULT NULL::text, p_prior jsonb DEFAULT NULL::jsonb, p_new jsonb DEFAULT NULL::jsonb, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cid uuid := public.current_client_id(); tid uuid := public.current_tenant_id(); new_id uuid;
begin
  if cid is null then raise exception 'not a client'; end if;
  insert into public.consent_events(tenant_id, client_id, event_type, channel, phone_e164, disclosures_version, prior_state, new_state, source, ip, user_agent)
  values (tid, cid, p_event_type, p_channel, p_phone, p_disclosures_version, p_prior, p_new, 'in_app', p_ip, p_user_agent)
  returning consent_events.id into new_id;
  return new_id;
end $$;

--
-- Name: reject_checkin_tag(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_checkin_tag(p_assessment_id uuid, p_reason text DEFAULT NULL::text) RETURNS public.checkin_assessments
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_row public.checkin_assessments;
  v_old text;
begin
  if current_app_role() <> 'coach' then
    raise exception 'reject_checkin_tag: coach only' using errcode = '42501';
  end if;

  select proposed_tag into v_old from public.checkin_assessments where id = p_assessment_id;

  -- "No tag is right" is a real position, not an absence. needs_review clears
  -- because the coach HAS looked — but confirmed_tag stays NULL, so nothing
  -- downstream counts it as a position.
  update public.checkin_assessments
     set confirmed_tag = null,
         confirmed_by  = auth.uid(),
         confirmed_at  = now(),
         needs_review  = false,
         no_tag_reason = coalesce(p_reason, no_tag_reason, 'coach_rejected')
   where id = p_assessment_id
   returning * into v_row;

  if v_row.id is null then
    raise exception 'reject_checkin_tag: assessment not found' using errcode = 'P0002';
  end if;

  insert into public.checkin_tag_corrections
    (tenant_id, assessment_id, checkin_id, client_id, from_tag, to_tag, reason, corrected_by)
  values
    (v_row.tenant_id, v_row.id, v_row.checkin_id, v_row.client_id, v_old, null, p_reason, auth.uid());

  return v_row;
end;
$$;

--
-- Name: FUNCTION reject_checkin_tag(p_assessment_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reject_checkin_tag(p_assessment_id uuid, p_reason text) IS 'The coach rejects the proposal without substituting one. confirmed_tag stays NULL — reviewed, and correctly untagged. Always writes a correction row. Coach-only.';

--
-- Name: release_client_onboarding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_client_onboarding(p_onboarding_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  o        public.client_onboarding%rowtype;
  v_chk    jsonb;
  v_pid    uuid;
begin
  perform public.assert_coach_owns_onboarding(p_onboarding_id);
  select * into o from public.client_onboarding where id = p_onboarding_id;
  if not found then return jsonb_build_object('status','error','reason','onboarding_not_found'); end if;

  if o.released_at is not null then
    return jsonb_build_object('status','ok','outcome','already_released',
      'released_at', o.released_at, 'client_id', o.client_id);
  end if;

  v_chk := public.check_client_onboarding_readiness(p_onboarding_id);
  if not (v_chk->>'ready')::boolean then
    return jsonb_build_object('status','blocked','reason','not_ready','detail', v_chk);
  end if;

  -- All or nothing, in one transaction.
  select public.publish_program_draft(o.program_draft_id) into v_pid;

  update public.client_meal_plans
     set status = 'assigned', assigned_at = now(), updated_at = now()
   where id = o.meal_plan_id;

  update public.clients set status = 'active', updated_at = now()
   where id = o.client_id and status <> 'active';

  update public.client_onboarding
     set stage = 'released', released_at = now(), released_by = auth.uid(),
         checkins_scheduled = (v_chk->>'checkins_scheduled')::int, updated_at = now()
   where id = p_onboarding_id;

  return jsonb_build_object('status','ok','outcome','released',
    'client_id', o.client_id, 'program_id', v_pid, 'meal_plan_id', o.meal_plan_id,
    'checkins_scheduled', (v_chk->>'checkins_scheduled')::int);
end $$;

--
-- Name: FUNCTION release_client_onboarding(p_onboarding_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.release_client_onboarding(p_onboarding_id uuid) IS 'The single door between "prepared" and "the client can see it". Publishes the program, assigns the meal plan and confirms the check-in schedule together, or does none of them. Refuses while any hard blocker or missing piece remains.';

--
-- Name: request_phone_otp(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_phone_otp(p_phone text, p_code_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cid uuid := public.current_client_id(); tid uuid := public.current_tenant_id(); new_id uuid;
begin
  if cid is null then raise exception 'not a client'; end if;
  update public.clients set phone_e164 = p_phone, updated_at = now() where id = cid;
  insert into public.phone_otps(tenant_id, client_id, phone_e164, code_hash, expires_at)
  values (tid, cid, p_phone, p_code_hash, now() + interval '10 minutes') returning phone_otps.id into new_id;
  return new_id;
end $$;

--
-- Name: rm__ago(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm__ago(p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when p_at is null then 'never'
    when now() - p_at < interval '2 minutes' then 'just now'
    when now() - p_at < interval '1 hour'
      then (extract(epoch from (now() - p_at))::int / 60) || ' minutes ago'
    when now() - p_at < interval '36 hours'
      then (extract(epoch from (now() - p_at))::int / 3600) || ' hours ago'
    else (extract(epoch from (now() - p_at))::int / 86400) || ' days ago'
  end;
$$;

--
-- Name: rm__cfg_text(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm__cfg_text(p_tenant uuid, p_col text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare v text;
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'tenant_config' and column_name = p_col
  ) then
    return null;
  end if;
  execute format('select %I::text from tenant_config where tenant_id = $1', p_col)
    into v using p_tenant;
  return v;
end;
$_$;

--
-- Name: rm__classify_source(timestamp with time zone, interval, integer, integer, boolean, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm__classify_source(p_last_event_at timestamp with time zone, p_expected interval, p_volume_7d integer, p_baseline_28d integer, p_expects_data boolean, p_configured boolean, p_participants_7d integer DEFAULT NULL::integer, p_cohort_size integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    -- Feature switched off in tenant_config. Nothing is broken.
    when not p_configured then 'not_configured'

    -- Never delivered, and given the roster we would not expect it to have.
    -- Honest "nothing here yet", visually distinct from a fault.
    when p_last_event_at is null and not p_expects_data then 'not_configured'

    -- Should have data, has none. Fault.
    when p_last_event_at is null then 'unavailable'

    -- ---------------- THE FLOOR ----------------
    -- The spec specifies an absolute floor: "< 5 events across an active
    -- roster". That is too weak, and I hit the failure live while building.
    -- Mid-build one client logged 7 sets in a single session, which took the
    -- tenant from 1 event to 7 and cleared an absolute floor of 5 — flipping
    -- training to 'live' and instantly flagging the OTHER 29 clients as silent
    -- on the strength of one person's workout. That is precisely the false
    -- accusation this page exists to prevent, arriving through the front door.
    --
    -- Volume cannot answer "is this feed representative of the roster?".
    -- Participation can. 2 distinct clients out of 31 active assignments is a
    -- 6% sample: not a healthy feed, however many rows those 2 produced.
    -- FLAGGED FOR REVIEW — this is a deliberate deviation from the spec's
    -- literal floor, and the threshold is a coaching judgement he should set.
    when p_expects_data
     and p_cohort_size >= 4
     and p_participants_7d is not null
     and p_participants_7d::numeric / p_cohort_size < 0.25 then 'unavailable'

    -- Absolute floor retained for cohorts too small for participation to mean
    -- anything (a 1-3 client tenant).
    when p_expects_data and coalesce(p_cohort_size, 0) < 4 and p_volume_7d < 5
      then 'unavailable'

    -- Silence past twice the expected interval.
    when p_last_event_at < now() - (p_expected * 2) then 'unavailable'

    -- Volume collapse against the 28-day baseline, NORMALISED TO A WEEKLY RATE.
    -- The spec states "volume_7d < 0.2 x baseline_28d". Taken literally that
    -- compares a 7-day count against a 28-day total and would mark almost every
    -- healthy feed unavailable (a steady feed sits at ~25% by construction).
    -- Dividing the baseline by 4 is the reading that preserves the intent.
    -- FLAGGED FOR REVIEW — see the summary.
    when p_baseline_28d >= 20 and p_volume_7d < 0.2 * (p_baseline_28d / 4.0) then 'unavailable'

    -- Arriving, but late.
    when p_last_event_at < now() - p_expected then 'stale'
    when p_baseline_28d >= 20 and p_volume_7d < 0.4 * (p_baseline_28d / 4.0) then 'stale'

    else 'live'
  end;
$$;

--
-- Name: FUNCTION rm__classify_source(p_last_event_at timestamp with time zone, p_expected interval, p_volume_7d integer, p_baseline_28d integer, p_expects_data boolean, p_configured boolean, p_participants_7d integer, p_cohort_size integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rm__classify_source(p_last_event_at timestamp with time zone, p_expected interval, p_volume_7d integer, p_baseline_28d integer, p_expects_data boolean, p_configured boolean, p_participants_7d integer, p_cohort_size integer) IS 'Source health ladder. p_expects_data distinguishes a never-used feed (not_configured) from a broken one (unavailable).';

--
-- Name: rm__confidence(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm__confidence(p_state text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_state
    when 'live'  then 1.0
    when 'stale' then 0.6
    else 0.0
  end::numeric;
$$;

--
-- Name: rm__days_word(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm__days_word(p_n integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_n || case when p_n = 1 then ' day' else ' days' end;
$$;

--
-- Name: rm__interval_words(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm__interval_words(p_i interval) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_i <= interval '1 day'   then 'day'
    when p_i <= interval '7 days'  then 'week'
    when p_i <= interval '14 days' then 'fortnight'
    else 'month'
  end;
$$;

--
-- Name: rm__n(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm__n(p_n bigint, p_word text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_n || ' ' || p_word || case when p_n = 1 then '' else 's' end;
$$;

--
-- Name: rm_attention_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm_attention_candidates() RETURNS TABLE(client_id uuid, display_name text, signal_type text, source_key text, severity numeric, recency numeric, is_decision boolean, deadline timestamp with time zone, since timestamp with time zone, mechanism text, evidence jsonb, actions jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with last_session as (
    select a.client_id,
           max(ws.session_date) as last_date,
           count(ws.id) filter (
             where ws.session_date > (now() - interval '28 days')::date) as sessions_28d
    from assignments a
    left join workout_sessions ws
      on ws.client_id = a.client_id and ws.tenant_id = a.tenant_id
    where a.tenant_id = current_tenant_id() and a.active
    group by a.client_id
  ),
  sil as (
    select
      c.id as client_id, c.display_name,
      'training_silent'::text as signal_type, 'training'::text as source_key,
      0.9::numeric as severity,
      least(1.0, greatest(0.05,
        (coalesce(now()::date - ls.last_date, 30) - 3)::numeric / 11.0))::numeric as recency,
      false as is_decision, null::timestamptz as deadline,
      ls.last_date::timestamptz as since,
      case when ls.last_date is null
        then 'No session has ever been logged against an active assignment.'
        else rm__days_word((now()::date - ls.last_date)::int)
             || ' without a logged session against an active assignment.'
      end as mechanism,
      jsonb_build_array(
        jsonb_build_object('label','last session',
          'value', coalesce(to_char(ls.last_date, 'DD Mon'), 'never')),
        jsonb_build_object('label','sessions 28d', 'value', ls.sessions_28d::text)
      ) as evidence,
      jsonb_build_array(
        jsonb_build_object('key','open_client','label','Open client','primary',true),
        jsonb_build_object('key','draft_message','label','Draft message','primary',false)
      ) as actions
    from last_session ls
    join clients c on c.id = ls.client_id and c.status = 'active'
    where coalesce(now()::date - ls.last_date, 999) > 3
  ),
  topsets as (
    select
      wl.client_id, wl.exercise_id, ws.session_date,
      max(wl.weight) as top_weight,
      count(*)       as set_count,
      max(wl.logged_at) as logged_at,
      row_number() over (partition by wl.client_id, wl.exercise_id
                         order by ws.session_date desc) as rn
    from workout_logs wl
    join workout_sessions ws on ws.id = wl.session_id
    where wl.tenant_id = current_tenant_id() and wl.done and wl.weight is not null
    group by wl.client_id, wl.exercise_id, ws.session_date
  ),
  regress as (
    select
      t.client_id, t.exercise_id,
      count(*) as n_sessions,
      max(t.logged_at) as last_at,
      string_agg(t.top_weight::text, ' -> ' order by t.session_date) as trail,
      min(t.set_count) as sets_held,
      (array_agg(t.top_weight order by t.session_date desc))[1] as newest,
      (array_agg(t.top_weight order by t.session_date desc))[3] as oldest
    from topsets t
    where t.rn <= 3
    group by t.client_id, t.exercise_id
    having count(*) >= 3
       and (array_agg(t.top_weight order by t.session_date desc))[1]
         < (array_agg(t.top_weight order by t.session_date desc))[3]
  ),
  reg as (
    select
      c.id, c.display_name,
      'load_regression'::text, 'training'::text,
      0.85::numeric,
      least(1.0, greatest(0.2,
        ((r.oldest - r.newest) / nullif(r.oldest,0) * 100) / 10.0))::numeric,
      false, null::timestamptz, r.last_at,
      'Top-set load down ' || r.n_sessions || ' sessions running on '
        || coalesce((select ex->>'name'
              from programs p,
                   jsonb_array_elements(p.structure->'days') d,
                   jsonb_array_elements(d->'groups') g,
                   jsonb_array_elements(g->'exercises') ex
             where p.tenant_id = current_tenant_id()
               and (ex->>'exercise_id')::uuid = r.exercise_id
             limit 1), 'the same lift')
        || '. Volume held, intensity dropped. Sessions still logged, so adherence hides it.',
      jsonb_build_array(
        jsonb_build_object('label','top set', 'value', r.trail),
        jsonb_build_object('label','sets held at', 'value', r.sets_held::text)
      ),
      jsonb_build_array(
        jsonb_build_object('key','open_client','label','Open client','primary',true),
        jsonb_build_object('key','adjust_block','label','Adjust block','primary',false)
      )
    from regress r
    join clients c on c.id = r.client_id and c.status = 'active'
  ),
  inv as (
    select
      c.id, c.display_name,
      'account_unreachable'::text, 'roster'::text,
      0.8::numeric,
      case
        when c.invite_expires_at is not null then
          least(1.0, greatest(0.15,
            1.0 - (extract(epoch from (c.invite_expires_at - now())) / 86400.0 / 14.0)))
        else 1.0
      end::numeric,
      c.invite_expires_at is not null, c.invite_expires_at, c.joined_at,
      case when c.invite_token is not null then
        'Invite issued ' || rm__days_word((now()::date - c.joined_at::date)::int)
          || ' ago, never claimed. The account record exists; the client has never reached it.'
      else
        'Client record created ' || rm__days_word((now()::date - c.joined_at::date)::int)
          || ' ago with no account attached and no invite issued. They cannot open the app.'
      end,
      jsonb_build_array(
        jsonb_build_object('label','account', 'value','not linked'),
        jsonb_build_object('label','invite',
          'value', case when c.invite_token is null then 'never issued'
                        else coalesce('expires ' || to_char(c.invite_expires_at,'DD Mon'),
                                      'issued, no expiry') end),
        jsonb_build_object('label','on record',
          'value', rm__days_word((now()::date - c.joined_at::date)::int))
      ),
      jsonb_build_array(
        jsonb_build_object('key','send_invite','label',
          case when c.invite_token is null then 'Send invite' else 'Resend invite' end,
          'primary',true),
        jsonb_build_object('key','open_client','label','Open client','primary',false)
      )
    from clients c
    where c.tenant_id = current_tenant_id()
      and c.client_user_id is null
      and c.status <> 'paused'
  ),
  nomeal as (
    select
      c.id, c.display_name,
      'no_meal_plan'::text, 'roster'::text,
      0.7::numeric, 0.7::numeric,
      false, null::timestamptz, a.assigned_at,
      'Active assignment with no meal plan attached. The nutrition surface is blank on their side.',
      jsonb_build_array(
        jsonb_build_object('label','assigned','value', to_char(a.assigned_at, 'DD Mon')),
        jsonb_build_object('label','meal plan','value','none')
      ),
      jsonb_build_array(
        jsonb_build_object('key','build_meal_plan','label','Build meal plan','primary',true),
        jsonb_build_object('key','open_client','label','Open client','primary',false)
      )
    from assignments a
    join clients c on c.id = a.client_id
    where a.tenant_id = current_tenant_id() and a.active and c.status = 'active'
      and not exists (
        select 1 from meal_plans mp
        where mp.client_id = c.id and mp.tenant_id = current_tenant_id())
  ),
  unread as (
    select
      c.id, c.display_name,
      'unread_message'::text, 'messages'::text,
      0.7::numeric,
      least(1.0, extract(epoch from (now() - m.first_unread)) / 86400.0 / 3.0)::numeric,
      false, null::timestamptz, m.first_unread,
      'Message waiting ' || rm__ago(m.first_unread) || ', unanswered.',
      jsonb_build_array(
        jsonb_build_object('label','unread','value', m.n::text),
        jsonb_build_object('label','waiting since', 'value', to_char(m.first_unread,'DD Mon HH24:MI'))
      ),
      jsonb_build_array(
        jsonb_build_object('key','open_thread','label','Open thread','primary',true)
      )
    from (
      select messages.client_id, min(messages.sent_at) as first_unread, count(*)::int as n
      from messages
      where messages.tenant_id = current_tenant_id()
        and messages.sender_role = 'client' and messages.read_at is null
      group by messages.client_id
    ) m
    join clients c on c.id = m.client_id
    where m.first_unread < now() - interval '24 hours'
  ),
  presc as (
    select a.client_id,
      (select count(*) from jsonb_array_elements(p.structure->'days') d
        where d->>'kind' = 'training')::int as prescribed,
      (select count(*) from workout_sessions ws
        where ws.client_id = a.client_id and ws.tenant_id = current_tenant_id()
          and ws.session_date > (now() - interval '7 days')::date)::int as s7
    from assignments a
    join programs p on p.id = a.program_id
    where a.tenant_id = current_tenant_id() and a.active
  ),
  overreach as (
    select
      c.id, c.display_name,
      'overreach'::text, 'training'::text,
      0.5::numeric, 0.6::numeric,
      false, null::timestamptz, now(),
      o.s7 || ' sessions logged in seven days against a ' || o.prescribed
        || '-day program. Adding work that was not prescribed.',
      jsonb_build_array(
        jsonb_build_object('label','sessions 7d','value', o.s7::text),
        jsonb_build_object('label','program','value', o.prescribed || '-day')
      ),
      jsonb_build_array(
        jsonb_build_object('key','open_client','label','Open client','primary',false),
        jsonb_build_object('key','draft_message','label','Draft message','primary',false)
      )
    from presc o
    join clients c on c.id = o.client_id and c.status = 'active'
    where o.s7 > o.prescribed and o.prescribed > 0
  ),
  -- NOW RESOLVABLE: gated on pause_resume_date, so setting a date silences it.
  paused as (
    select
      c.id, c.display_name,
      'paused_no_resume'::text, 'roster'::text,
      0.45::numeric, 0.6::numeric,
      false, null::timestamptz, coalesce(c.paused_at, c.updated_at),
      'Paused ' || rm__days_word((now()::date - coalesce(c.paused_at, c.updated_at)::date)::int)
        || ' ago with no resume date set, so nothing will surface this client again on its own.',
      jsonb_build_array(
        jsonb_build_object('label','status','value','paused'),
        jsonb_build_object('label','resume date','value','not set')
      ),
      jsonb_build_array(
        jsonb_build_object('key','set_resume_date','label','Set resume date','primary',true),
        jsonb_build_object('key','open_client','label','Open client','primary',false)
      )
    from clients c
    where c.tenant_id = current_tenant_id() and c.status = 'paused'
      and c.pause_resume_date is null
  ),
  -- NOW COMPUTABLE: assignments.ends_on exists. NULL ends_on suppresses the
  -- signal rather than faking a deadline, which is how every current assignment
  -- behaves until a coach sets a block length.
  ending as (
    select
      c.id, c.display_name,
      'program_ending'::text, 'roster'::text,
      0.75::numeric,
      least(1.0, greatest(0.2, 1.0 - ((a.ends_on - now()::date) / 7.0)))::numeric,
      true, a.ends_on::timestamptz, a.assigned_at,
      'Program completes in ' || rm__days_word((a.ends_on - now()::date)::int)
        || '. No next block assigned. Left alone, they finish and have nothing waiting.',
      jsonb_build_array(
        jsonb_build_object('label','ends','value', to_char(a.ends_on,'DD Mon')),
        jsonb_build_object('label','next block','value','none')
      ),
      jsonb_build_array(
        jsonb_build_object('key','assign_next','label','Assign next block','primary',true)
      )
    from assignments a
    join clients c on c.id = a.client_id and c.status = 'active'
    where a.tenant_id = current_tenant_id() and a.active
      and a.ends_on is not null
      and a.ends_on <= now()::date + 7
      and a.next_program_id is null
  ),
  strong as (
    select
      c.id, c.display_name,
      'first_week_strong'::text, 'training'::text,
      0.3::numeric, 0.8::numeric,
      false, null::timestamptz, c.joined_at,
      'First full week complete. ' || f.s7 || ' of ' || f.prescribed
        || ' sessions logged. Worth naming while it is still new behaviour.',
      jsonb_build_array(
        jsonb_build_object('label','sessions','value', f.s7 || ' / ' || f.prescribed),
        jsonb_build_object('label','joined','value', to_char(c.joined_at,'DD Mon'))
      ),
      jsonb_build_array(
        jsonb_build_object('key','draft_message','label','Draft message','primary',false)
      )
    from presc f
    join clients c on c.id = f.client_id and c.status = 'active'
    where c.joined_at > now() - interval '14 days'
      and f.prescribed > 0 and f.s7 >= f.prescribed
  )
  select * from sil
  union all select * from reg
  union all select * from inv
  union all select * from nomeal
  union all select * from unread
  union all select * from overreach
  union all select * from paused
  union all select * from ending
  union all select * from strong;
$$;

--
-- Name: FUNCTION rm_attention_candidates(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rm_attention_candidates() IS 'Unranked attention candidates with severity and recency. Confidence, ranking and suppression are applied in rm_coach_overview.';

--
-- Name: rm_coach_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm_coach_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_tenant  uuid := current_tenant_id();
  v_sources jsonb;
  v_conf    jsonb;
  v_out     jsonb;
begin
  if v_tenant is null then
    raise exception 'rm_coach_overview: no tenant in session';
  end if;

  -- Sources first. Nothing below is readable without them.
  select jsonb_agg(to_jsonb(s) order by
           case s.key when 'training' then 1 when 'checkins' then 2
                      when 'messages' then 3 else 4 end)
    into v_sources
  from rm_source_health() s;

  select jsonb_object_agg(s->>'key', (s->>'confidence')::numeric)
    into v_conf
  from jsonb_array_elements(v_sources) s;

  with cand as (
    select c.*, coalesce((v_conf->>c.source_key)::numeric, 0) as conf
    from rm_attention_candidates() c
  ),
  scored as (
    select cand.*, round(severity * recency * conf, 4) as score from cand
  ),
  banded as (
    select scored.*,
      case
        -- 'decide' is not a score band. It is any item whose resolution is a
        -- coach decision with a deadline, and it always renders.
        when is_decision then 'decide'
        when score >= 0.7 then 'act'
        when score >= 0.4 then 'watch'
        else 'hold'
      end as band
    from scored
    -- RULE 1: a signal from a source that is not live or stale cannot produce
    -- an attention item. conf = 0 for unavailable / not_configured.
    where conf > 0
  ),
  -- ---------------- grouping ----------------
  -- The mockup collapses a repeated signal into one card ("6 clients — Active
  -- assignment, no meal plan") rather than printing six. Without this the queue
  -- is 33 rows deep on the current data and stops being a ranking at all.
  -- Threshold 3: up to three named clients read as individuals; four or more is
  -- a pattern, and for a pattern the coach wants a list, not a queue.
  sized as (
    select b.*, count(*) over (partition by b.signal_type) as sig_n from banded b
  ),
  singles as (
    select client_id, display_name, band, score, signal_type, source_key,
           mechanism, evidence, actions, since, deadline, 1 as member_count
    from sized where sig_n <= 3
  ),
  grouped as (
    select
      null::uuid as client_id,
      rm__n(count(*), 'client') as display_name,
      -- A group is at least as urgent as its most urgent member.
      (array_agg(band order by score desc))[1] as band,
      max(score) as score,
      signal_type, source_key,
      -- Plural copy per signal, in SQL, so the connector reads the same sentence
      -- The coach reads.
      case signal_type
        when 'training_silent' then
          'No logged session in over three days against an active assignment.'
        when 'account_unreachable' then
          'Client records with no account attached and no invite issued. They cannot open the app.'
        when 'no_meal_plan' then
          'Active assignment with no meal plan attached. The nutrition surface is blank on their side.'
        when 'unread_message' then 'Messages waiting over 24 hours, unanswered.'
        when 'overreach' then
          'More sessions logged in seven days than the program prescribes.'
        when 'paused_no_resume' then
          'Paused with no resume date recorded, so nothing will surface them again on its own.'
        when 'load_regression' then
          'Top-set load falling across three sessions running while volume holds.'
        when 'first_week_strong' then
          'First full week complete, every prescribed session logged.'
        else 'Multiple clients on the same signal.'
      end as mechanism,
      jsonb_build_array(
        jsonb_build_object('label', 'clients', 'value', count(*)::text),
        jsonb_build_object('label', 'longest waiting',
          'value', (array_agg(display_name order by score desc, display_name))[1]
                   || case when count(*) > 1 then ' +' || (count(*) - 1) else '' end)
      ) as evidence,
      jsonb_build_array(
        jsonb_build_object('key','review_list','label','Review list','primary',true)
      ) as actions,
      min(since) as since,
      min(deadline) as deadline,
      count(*)::int as member_count
    from sized where sig_n > 3
    group by signal_type, source_key
  ),
  queue as (
    select * from singles
    union all
    select * from grouped
  )
  select jsonb_build_object(
    'schema_version', 1,
    'generated_at',   now(),

    -- ---------------- tenant brand ----------------
    'tenant', (
      select jsonb_build_object(
        'tenant_id',          t.id,
        'slug',               t.slug,
        'app_name',           coalesce(tc.app_name, 'Coach App'),
        'coach_display_name', tc.coach_display_name,
        'logo_url',           tc.logo_url,
        'brand_color',        tc.brand_color,
        'theme_key',          tc.theme_key,
        -- surface_mode / type_key are pending columns; the client-side resolver
        -- defaults until the schema-gap migration is applied.
        'surface_mode',       coalesce(rm__cfg_text(tc.tenant_id, 'surface_mode'), 'dark'),
        'type_key',           coalesce(rm__cfg_text(tc.tenant_id, 'type_key'), 'grotesk'),
        'weight_unit',        tc.weight_unit,
        'features', jsonb_build_object(
          'messaging',       tc.messaging_on,
          'progress_photos', tc.progress_photos_on,
          'progress_weight', tc.progress_weight_on,
          'approval_gate',   tc.program_approval_gate
        ))
      from tenant_config tc join tenants t on t.id = tc.tenant_id
      where tc.tenant_id = v_tenant
    ),

    'sources', v_sources,

    -- ---------------- roster pulse ----------------
    -- A metric whose backing source is unhealthy is returned as JSON null, NOT
    -- 0. The UI renders null as a hatched em-dash. A false zero here is the
    -- specific failure this page exists to prevent: 0 reads as "nobody trained"
    -- and would have a coach message a client who did train.
    'roster', (
      select jsonb_build_object(
        'total',   count(*),
        'active',  count(*) filter (where status = 'active'),
        'paused',  count(*) filter (where status = 'paused'),
        'invited', count(*) filter (where status = 'invited'),
        'trained_7d', case when (v_conf->>'training')::numeric > 0 then (
            select count(distinct ws.client_id) from workout_sessions ws
            where ws.tenant_id = v_tenant
              and ws.session_date > (now() - interval '7 days')::date) end,
        'silent_7d', case when (v_conf->>'training')::numeric > 0 then (
            select count(*) from assignments a
            join clients cc on cc.id = a.client_id and cc.status = 'active'
            where a.tenant_id = v_tenant and a.active
              and not exists (select 1 from workout_sessions ws
                where ws.client_id = a.client_id
                  and ws.session_date > (now() - interval '7 days')::date)) end,
        'checked_in_7d', case when (v_conf->>'checkins')::numeric > 0 then (
            select count(distinct ck.client_id) from checkins ck
            where ck.tenant_id = v_tenant
              and ck.submitted_at > now() - interval '7 days') end
      )
      from clients where tenant_id = v_tenant
    ),

    -- ---------------- ranked attention ----------------
    'attention', coalesce((
      select jsonb_agg(jsonb_build_object(
        'client_id', client_id, 'display_name', display_name,
        'band', band, 'score', score,
        'signal_type', signal_type, 'source_key', source_key,
        'mechanism', mechanism, 'evidence', evidence, 'actions', actions,
        'since', since, 'deadline', deadline,
        -- >1 means this card stands for a group, not one person. The UI uses it
        -- to label the action button and to avoid implying a single client.
        'member_count', member_count)
      order by case band when 'act' then 1 when 'decide' then 2
                         when 'watch' then 3 else 4 end,
               score desc, display_name)
      from queue), '[]'::jsonb),

    -- ---------------- suppression ----------------
    -- RULE 2: an unhealthy source yields a count, never a flag. RULE 3: the UI
    -- renders this hatched, and never as an empty queue.
    'suppressed', coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_key', x.source_key, 'withheld_count', x.n,
        'reason', x.reason, 'since', x.since) order by x.n desc)
      from (
        select c.source_key, count(*)::int as n,
          (select s->>'note' from jsonb_array_elements(v_sources) s
            where s->>'key' = c.source_key) as reason,
          (select (s->>'last_event_at')::timestamptz from jsonb_array_elements(v_sources) s
            where s->>'key' = c.source_key) as since
        from rm_attention_candidates() c
        where coalesce((v_conf->>c.source_key)::numeric, 0) = 0
        group by c.source_key
      ) x), '[]'::jsonb),

    -- ---------------- decisions ----------------
    -- Roster-derived, so this card never empties just because a feed died.
    'decisions', coalesce((
      select jsonb_agg(d order by d->>'ord')
      from (
        select jsonb_build_object('ord','1','kind','draft_approval',
          'title','Program drafts awaiting approval',
          'detail', case when (select program_approval_gate from tenant_config
                               where tenant_id = v_tenant)
                    then 'Approval gate is on. Nothing reaches a client until you release it.'
                    else 'Approval gate is off — drafts publish without review.' end,
          'count', (select count(*) from program_drafts
                     where tenant_id = v_tenant and status = 'draft')) as d
        union all
        select jsonb_build_object('ord','2','kind','no_meal_plan',
          'title','Active clients without a meal plan',
          'detail','Assignment live, nutrition surface blank on their side.',
          'count', (select count(*) from assignments a
                     join clients c on c.id = a.client_id and c.status = 'active'
                     where a.tenant_id = v_tenant and a.active
                       and not exists (select 1 from meal_plans mp
                         where mp.client_id = c.id)))
        union all
        -- Drafted but never released. One click each, and the client currently
        -- sees a blank nutrition surface despite the work already being done.
        select jsonb_build_object('ord','3','kind','meal_plan_unreleased',
          'title','Meal plans drafted, never released',
          'detail','The work is done. Until it is assigned, the client cannot see it.',
          'count', (select count(*) from meal_plans
                     where tenant_id = v_tenant and assigned_at is null))
        union all
        select jsonb_build_object('ord','4','kind','account_unreachable',
          'title','Clients with no account attached',
          'detail','Record created, no invite issued. They cannot open the app.',
          'count', (select count(*) from clients where tenant_id = v_tenant
                     and client_user_id is null and status <> 'paused'),
          'deadline', (select min(invite_expires_at) from clients where tenant_id = v_tenant
                     and client_user_id is null))
        union all
        select jsonb_build_object('ord','5','kind','paused_no_resume',
          'title','Paused without a resume date',
          'detail','Will not resurface on its own until a resume date is set.',
          'count', (select count(*) from clients
                     where tenant_id = v_tenant and status = 'paused'
                       and pause_resume_date is null))
      ) dec_rows
      where (d->>'count')::int > 0), '[]'::jsonb),

    -- ---------------- prep timelines ----------------
    -- SCHEMA GAP: clients has no show_date. The rail reports the gap rather than
    -- inventing dates, and switches itself on once the column exists.
    -- clients.show_date now exists (20260729120100). Undated clients are EXCLUDED
    -- from this rail, never ranked lower on it. With every show_date still null
    -- this returns [] with unavailable=false, so the UI shows the SOLID "no dates
    -- set" empty state -- we know, and there are none -- not the hatched
    -- "cannot see" state. That distinction is the whole point of the page.
    'timelines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'client_id', c.id, 'display_name', c.display_name,
        'event_date', c.show_date,
        'weeks_out', ceil((c.show_date - now()::date) / 7.0),
        'phase', case
          when c.show_date - now()::date <= 7  then 'peak week'
          when c.show_date - now()::date <= 28 then 'final month'
          else 'build' end,
        'note', coalesce(c.show_name, 'no show name set'))
      order by c.show_date)
      from clients c
      where c.tenant_id = v_tenant and c.status = 'active'
        and c.show_date is not null and c.show_date >= now()::date
    ), '[]'::jsonb),
    'timelines_unavailable', false,
    'timelines_note', null,

    -- Signals the read model knows about but cannot compute on this schema.
    -- Reported so the page can be honest instead of silently omitting them.
    -- program_ending is now computable: assignments.ends_on exists and the
    -- signal is live in rm_attention_candidates. Nothing is currently
    -- uncomputable, so this list is empty and the UI hides the block.
    'unavailable_signals', '[]'::jsonb,

    -- ---------------- activity ----------------
    -- Chronological, deliberately last, capped at 8.
    'activity', coalesce((
      select jsonb_agg(e order by (e->>'at') desc)
      from (
        select jsonb_build_object('at', ws.completed_at, 'client_id', ws.client_id,
          'display_name', c.display_name, 'kind','session_complete',
          'summary','completed a session'
            || coalesce((select ' — ' || count(*) || ' sets' from workout_logs wl
                 where wl.session_id = ws.id and wl.done
                 having count(*) > 0), '')) as e
        from workout_sessions ws join clients c on c.id = ws.client_id
        where ws.tenant_id = v_tenant and ws.completed_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', wl.logged_at, 'client_id', wl.client_id,
          'display_name', c.display_name, 'kind','set_logged',
          'summary','logged a set'
            || coalesce(' — ' || wl.weight || ' x ' || wl.reps, ''))
        from workout_logs wl join clients c on c.id = wl.client_id
        where wl.tenant_id = v_tenant and wl.logged_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', m.sent_at, 'client_id', m.client_id,
          'display_name', c.display_name, 'kind','message', 'summary','messaged you')
        from messages m join clients c on c.id = m.client_id
        where m.tenant_id = v_tenant and m.sender_role = 'client'
          and m.sent_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', ck.submitted_at, 'client_id', ck.client_id,
          'display_name', c.display_name, 'kind','checkin','summary','submitted a check-in')
        from checkins ck join clients c on c.id = ck.client_id
        where ck.tenant_id = v_tenant and ck.submitted_at > now() - interval '24 hours'
        order by 1 desc
        limit 8
      ) ev), '[]'::jsonb)
  ) into v_out;

  return v_out;
end;
$$;

--
-- Name: FUNCTION rm_coach_overview(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rm_coach_overview() IS 'THE read model for the coach home page, and the payload for the MCP get_coach_overview tool. One function, two surfaces, so ranking can never diverge between what the coach sees and what the model sees.';

--
-- Name: rm_source_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rm_source_health() RETURNS TABLE(key text, state text, last_event_at timestamp with time zone, expected_interval interval, volume_7d integer, baseline_28d integer, confidence numeric, note text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_tenant   uuid := current_tenant_id();
  v_msg_on   boolean;
  v_cadence  text;
  v_active   int;
  v_paused   int;
  v_assign   int;
  v_plans    int;
  v_notes    int;
  v_exp      interval;
  v_last     timestamptz;
  v_v7       int;
  v_v28      int;
  v_extra    int;
  v_part     int;   -- distinct clients that produced an event in the last 7d
  v_state    text;
begin
  select coalesce(tc.messaging_on, true), coalesce(tc.checkin_cadence, 'weekly')
    into v_msg_on, v_cadence
  from tenant_config tc where tc.tenant_id = v_tenant;

  select count(*) filter (where status = 'active'),
         count(*) filter (where status = 'paused')
    into v_active, v_paused
  from clients where tenant_id = v_tenant;

  select count(*) into v_assign from assignments where tenant_id = v_tenant and active;
  select count(*) into v_plans  from meal_plans   where tenant_id = v_tenant;
  select count(*) into v_notes  from client_notes where tenant_id = v_tenant;

  -- ======================= TRAINING =======================
  select greatest(
           (select max(logged_at)  from workout_logs     where tenant_id = v_tenant),
           (select max(updated_at) from workout_sessions where tenant_id = v_tenant))
    into v_last;
  select count(*) into v_v7  from workout_logs
    where tenant_id = v_tenant and logged_at > now() - interval '7 days';
  select count(*) into v_v28 from workout_logs
    where tenant_id = v_tenant and logged_at > now() - interval '28 days';
  select count(*) into v_extra from workout_sessions
    where tenant_id = v_tenant and session_date > (now() - interval '7 days')::date;
  -- Participation, not volume, decides whether this feed represents the roster.
  select count(distinct client_id) into v_part from workout_sessions
    where tenant_id = v_tenant and session_date > (now() - interval '7 days')::date;

  v_exp := interval '2 days';
  v_state := rm__classify_source(v_last, v_exp, v_v7, v_v28, v_assign > 0, true,
                                 v_part, v_assign);

  return query select
    'training'::text, v_state, v_last, v_exp, v_v7, v_v28, rm__confidence(v_state),
    case v_state
      when 'live' then
        rm__n(v_v7, 'set') || ' logged in the last 7 days across '
        || rm__n(v_assign, 'active assignment') || '. Last event ' || rm__ago(v_last) || '.'
      when 'stale' then
        'Arriving, but behind pace. ' || rm__n(v_v7, 'set')
        || ' in 7 days against a 28-day count of ' || v_v28
        || '. Last event ' || rm__ago(v_last) || '.'
      when 'unavailable' then
        rm__n(v_extra, 'session') || ' and ' || rm__n(v_v7, 'set') || ' logged, from '
        || v_part || ' of ' || rm__n(v_assign, 'active assignment')
        || '. Too small a share of the roster to read adherence from, so training is '
        || 'treated as unavailable and no client is being flagged on it. Whether the '
        || 'feed is broken or the roster genuinely is not logging cannot be told apart '
        || 'from here — at this volume the two look identical. To settle it: open one '
        || 'client who should have trained and check whether their app shows the session.'
      else
        'No training data has ever arrived. Nothing is broken — nothing has been logged yet.'
    end;

  -- ======================= CHECK-INS =======================
  v_exp := case v_cadence
    when 'daily'    then interval '1 day'
    when 'biweekly' then interval '14 days'
    when 'monthly'  then interval '30 days'
    else interval '7 days' end;

  select max(submitted_at) into v_last from checkins where tenant_id = v_tenant;
  select count(*) into v_v7  from checkins
    where tenant_id = v_tenant and submitted_at > now() - interval '7 days';
  select count(*) into v_v28 from checkins
    where tenant_id = v_tenant and submitted_at > now() - interval '28 days';
  select count(*) into v_extra from checkin_hub_archive where tenant_id = v_tenant;
  select count(distinct client_id) into v_part from checkins
    where tenant_id = v_tenant and submitted_at > now() - interval '7 days';

  v_state := rm__classify_source(v_last, v_exp, v_v7, v_v28, v_active > 0, true,
                                 v_part, v_active);

  return query select
    'checkins'::text, v_state, v_last, v_exp, v_v7, v_v28, rm__confidence(v_state),
    case v_state
      when 'live' then
        rm__n(v_v7, 'check-in') || ' received in the last 7 days. Last event '
        || rm__ago(v_last) || '.'
      when 'stale' then
        'Expected every ' || rm__interval_words(v_exp) || '. Last submission '
        || rm__ago(v_last) || '.'
      when 'unavailable' then
        case when v_last is null then
          'No submissions on record'
          || case when v_extra > 0
               then ', ' || rm__n(v_extra, 'archived from the prior hub') else '' end
          || '. Expected every ' || rm__interval_words(v_exp)
          || '. Nothing has ever arrived, so a sync path that never delivered cannot be '
          || 'separated from a roster that has never been asked to check in. To settle it: '
          || 'confirm one client has check-ins switched on and can see the form.'
        else
          'Nothing has arrived since ' || to_char(v_last, 'DD Mon') || '. Expected every '
          || rm__interval_words(v_exp)
          || '. No client is being flagged for a missed check-in while that remains true. '
          || 'Submissions stopped rather than never started, which leans towards the sync '
          || 'path — but a roster that went quiet on the same date looks the same from here. '
          || 'To settle it: check one client who submitted before that date.'
        end
      else 'Check-ins are switched off for this tenant.'
    end;

  -- ======================= MESSAGES =======================
  -- expects_data stays false until the thread store has ever carried traffic. An
  -- empty inbox on a new tenant is disuse, not a fault. Once messages flow, a
  -- gap becomes a fault.
  select max(sent_at) into v_last from messages where tenant_id = v_tenant;
  select count(*) into v_v7  from messages
    where tenant_id = v_tenant and sent_at > now() - interval '7 days';
  select count(*) into v_v28 from messages
    where tenant_id = v_tenant and sent_at > now() - interval '28 days';
  select count(*) into v_extra from messages
    where tenant_id = v_tenant and sender_role = 'client' and read_at is null;

  -- Messages deliberately stay on the volume/recency rules: a single message
  -- from a single client is a real event that needs a reply, so low
  -- participation is not evidence of a broken feed here.
  v_exp := interval '3 days';
  v_state := rm__classify_source(v_last, v_exp, v_v7, v_v28, v_last is not null, v_msg_on,
                                 null, null);

  return query select
    'messages'::text, v_state, v_last, v_exp, v_v7, v_v28, rm__confidence(v_state),
    case v_state
      when 'live' then
        case when v_extra > 0 then v_extra || ' unread from clients. ' else 'No unread. ' end
        || 'Last event ' || rm__ago(v_last) || '.'
      when 'stale' then 'Quiet. Last message ' || rm__ago(v_last) || '.'
      when 'unavailable' then
        'Messages have stopped arriving since ' || to_char(v_last, 'DD Mon')
        || '. Treated as unavailable rather than as silence from clients, because a '
        || 'delivery fault and a genuinely quiet roster are indistinguishable from here.'
      else
        case when v_msg_on
          then 'Thread store empty. Nothing sent or received in-app yet.'
          else 'Messaging is switched off for this tenant.' end
    end;

  -- ======================= ROSTER & PROGRAMS =======================
  -- The fallback source: this is the database itself, not an external sync, so
  -- it is live whenever a roster exists. Everything the page can still say when
  -- every other feed is dark is derived from here.
  select greatest(
           (select max(updated_at) from clients     where tenant_id = v_tenant),
           (select max(updated_at) from assignments where tenant_id = v_tenant))
    into v_last;

  v_state := case when v_active + v_paused = 0 then 'not_configured' else 'live' end;

  return query select
    'roster'::text, v_state, v_last, interval '30 days', v_active, v_active,
    rm__confidence(v_state),
    case when v_state = 'not_configured'
      then 'No clients on the roster yet. Invite a client to bring this page to life.'
      else v_active || ' active, ' || v_paused || ' paused. '
           || rm__n(v_assign, 'active assignment') || ', ' || rm__n(v_plans, 'meal plan')
           || ', ' || rm__n(v_notes, 'note') || '. Live.'
    end;
end;
$$;

--
-- Name: FUNCTION rm_source_health(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rm_source_health() IS 'Per-source feed health for the caller tenant. note is coach-facing prose, rendered verbatim by the UI.';

--
-- Name: schedule_client_checkins(uuid, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_client_checkins(p_client_id uuid, p_occurrences integer DEFAULT 12, p_start date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c          public.clients%rowtype;
  v_cadence  text;
  v_dow      smallint;
  v_step     int;
  v_first    date;
  v_made     int := 0;
  i          int;
  v_due      date;
begin
  perform public.assert_coach_owns_client(p_client_id);
  select * into c from public.clients where id = p_client_id;
  if not found then return jsonb_build_object('status','error','reason','client_not_found'); end if;

  -- Per-client cadence, falling back to the tenant default. NULL on both sides is a real
  -- configuration gap, not a reason to invent 'weekly'.
  select coalesce(c.checkin_cadence, tc.checkin_cadence) into v_cadence
    from public.tenant_config tc where tc.tenant_id = c.tenant_id;

  if v_cadence is null then
    return jsonb_build_object('status','blocked','reason','no_cadence_configured',
      'detail','Neither this client nor the tenant defines a check-in cadence. Nothing was '
               'scheduled — an empty schedule here would look identical to a client who is '
               'simply not due yet.');
  end if;

  v_step := case v_cadence when 'weekly' then 7 when 'biweekly' then 14 else 30 end;
  v_first := coalesce(p_start, current_date);
  v_dow := c.checkin_day_of_week;

  -- Anchor to the client's chosen weekday when one is set; otherwise the first check-in
  -- falls one full cadence period after they start, which is the honest reading of
  -- "weekly from today".
  if v_dow is not null and v_cadence in ('weekly','biweekly') then
    v_first := v_first + ((v_dow - extract(dow from v_first)::int + 7) % 7);
    if v_first = current_date then v_first := v_first + v_step; end if;
  else
    v_first := v_first + v_step;
  end if;

  for i in 0 .. greatest(p_occurrences, 1) - 1 loop
    v_due := v_first + (i * v_step);
    insert into public.client_checkin_schedule (tenant_id, client_id, due_on, cadence, status)
    values (c.tenant_id, p_client_id, v_due, v_cadence, 'scheduled')
    on conflict (client_id, due_on) do nothing;
    if found then v_made := v_made + 1; end if;
  end loop;

  return jsonb_build_object('status','ok','cadence',v_cadence,'first_due',v_first,
    'scheduled', v_made,
    'total', (select count(*) from public.client_checkin_schedule
               where client_id = p_client_id and status = 'scheduled'));
end $$;

--
-- Name: FUNCTION schedule_client_checkins(p_client_id uuid, p_occurrences integer, p_start date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.schedule_client_checkins(p_client_id uuid, p_occurrences integer, p_start date) IS 'Writes future check-in occurrences so a new client opens the app to a rhythm rather than an empty tab. Refuses when no cadence is configured anywhere, because an empty schedule and an unconfigured one look the same on screen and mean very different things.';

--
-- Name: submit_checkin(numeric, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_checkin(p_weight numeric DEFAULT NULL::numeric, p_photo_urls jsonb DEFAULT '[]'::jsonb, p_answers jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cid uuid := public.current_client_id(); tid uuid := public.current_tenant_id(); ck uuid; ph jsonb;
begin
  if cid is null then raise exception 'not a client'; end if;
  insert into public.checkins(tenant_id, client_id, weight, photo_urls, answers) values (tid, cid, p_weight, p_photo_urls, p_answers) returning id into ck;
  if p_weight is not null then
    insert into public.progress_weights(tenant_id, client_id, date, weight, source_checkin_id) values (tid, cid, (now() at time zone 'utc')::date, p_weight, ck);
  end if;
  for ph in select * from jsonb_array_elements(coalesce(p_photo_urls, '[]'::jsonb)) loop
    insert into public.progress_photos(tenant_id, client_id, photo_url, pose_tag, source_checkin_id) values (tid, cid, ph ->> 'url', ph ->> 'pose_tag', ck);
  end loop;
  return ck;
end $$;

--
-- Name: tenant_is_suspended(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_is_suspended(p_tenant uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select status = 'suspended' from public.tenants where id = p_tenant), false);
$$;

--
-- Name: FUNCTION tenant_is_suspended(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tenant_is_suspended(p_tenant uuid) IS 'True when the given tenant is suspended. SECURITY DEFINER so the suspension check cannot be dodged by a caller who cannot see the tenants row.';

--
-- Name: tenants_guard_commercial_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenants_guard_commercial_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  blocked text[] := '{}';
begin
  -- Trusted callers pass straight through:
  --   service_role            -> license-provision / license-reconcile edge functions
  --   postgres/supabase_admin -> DBA work, and the body of any SECURITY DEFINER
  --                              function owned by postgres (provision_coach)
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  -- Identity and ownership
  if new.id                  is distinct from old.id                  then blocked := array_append(blocked, 'id'); end if;
  if new.coach_user_id       is distinct from old.coach_user_id       then blocked := array_append(blocked, 'coach_user_id'); end if;
  if new.created_at          is distinct from old.created_at          then blocked := array_append(blocked, 'created_at'); end if;

  -- Public identity. No write path exists for this; locking it also stops a coach
  -- silently changing the key that license-provision looks tenants up by.
  if new.slug                is distinct from old.slug                then blocked := array_append(blocked, 'slug'); end if;

  -- Commercial state — the actual escalation vector. status='suspended' -> 'active'
  -- is a coach un-suspending their own non-paying account.
  if new.status              is distinct from old.status              then blocked := array_append(blocked, 'status'); end if;
  if new.plan                is distinct from old.plan                then blocked := array_append(blocked, 'plan'); end if;
  if new.subscription_status is distinct from old.subscription_status then blocked := array_append(blocked, 'subscription_status'); end if;
  if new.subscription_id     is distinct from old.subscription_id     then blocked := array_append(blocked, 'subscription_id'); end if;
  if new.stripe_customer_id  is distinct from old.stripe_customer_id  then blocked := array_append(blocked, 'stripe_customer_id'); end if;
  if new.license_stripe_ref  is distinct from old.license_stripe_ref  then blocked := array_append(blocked, 'license_stripe_ref'); end if;
  if new.licensed_at         is distinct from old.licensed_at         then blocked := array_append(blocked, 'licensed_at'); end if;

  if array_length(blocked, 1) is not null then
    -- 42501 = insufficient_privilege; PostgREST surfaces this as HTTP 403.
    raise exception 'tenants: column(s) % are billing-controlled and cannot be changed from the app',
      array_to_string(blocked, ', ')
      using errcode = '42501';
  end if;

  return new;
end;
$$;

--
-- Name: FUNCTION tenants_guard_commercial_update(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tenants_guard_commercial_update() IS 'Blocks app-session writes to billing/identity columns on public.tenants (status, plan, subscription_*, stripe_customer_id, license_*, slug, id, coach_user_id, created_at). Only service_role and SECURITY DEFINER callers may change them. updated_at is owned by trg_touch_tenants.';

--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin new.updated_at := now(); return new; end $$;

--
-- Name: verify_phone_otp(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_phone_otp(p_code_hash text, p_disclosures_version text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cid uuid := public.current_client_id(); tid uuid := public.current_tenant_id(); o public.phone_otps;
begin
  if cid is null then raise exception 'not a client'; end if;
  select * into o from public.phone_otps where client_id = cid and code_hash = p_code_hash and consumed_at is null and expires_at > now() order by created_at desc limit 1;
  if o.id is null then return false; end if;
  update public.phone_otps set consumed_at = now() where id = o.id;
  update public.clients set phone_verified_at = now(), sms_consent_at = now(), sms_consent_version = p_disclosures_version,
    notif_channels = jsonb_set(notif_channels, '{sms}', 'true'::jsonb), notif_enabled = true, updated_at = now() where id = cid;
  insert into public.consent_events(tenant_id, client_id, event_type, channel, phone_e164, disclosures_version, prior_state, new_state, source)
  values (tid, cid, 'sms_opt_in', 'sms', o.phone_e164, p_disclosures_version, '{"sms":false}'::jsonb, '{"sms":true}'::jsonb, 'in_app');
  return true;
end $$;

--
-- Name: video_library_reorder(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.video_library_reorder(p_ordered_ids uuid[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_count  integer;
begin
  if public.current_app_role() <> 'coach' then
    raise exception 'video_library_reorder: coaches only';
  end if;

  select count(*) into v_count from public.coach_videos where tenant_id = v_tenant;

  if v_count <> coalesce(array_length(p_ordered_ids, 1), 0) then
    raise exception 'video_library_reorder: expected all % videos, got %',
      v_count, coalesce(array_length(p_ordered_ids, 1), 0);
  end if;

  update public.coach_videos cv
     set slot = t.new_slot, updated_at = now()
    from (select id, ord as new_slot
            from unnest(p_ordered_ids) with ordinality as u(id, ord)) t
   where cv.id = t.id
     and cv.tenant_id = v_tenant;
end;
$$;

