--
-- Name: TABLE client_onboarding; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.client_onboarding IS 'One row per intake-to-client onboarding run. Holds the RELEASE GATE: stage only reaches ''released'' when the program draft, the meal plan and the check-in schedule are all ready together, so a client can never sign in and find a program but no food, or food but no check-in. blockers is an array of {code, detail} — each one is a real missing input that a human has to resolve. A blocker is a finding to report, never a value to fill in.';

