--

CREATE TABLE public.clients (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_user_id uuid,
    display_name text NOT NULL,
    status public.client_status DEFAULT 'invited'::public.client_status NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notif_enabled boolean DEFAULT false NOT NULL,
    notif_channels jsonb DEFAULT '{"sms": false, "push": false}'::jsonb NOT NULL,
    push_subscription jsonb,
    phone_e164 text,
    phone_verified_at timestamp with time zone,
    sms_consent_at timestamp with time zone,
    sms_consent_version text,
    welcome_seen boolean DEFAULT false NOT NULL,
    invite_token text,
    invite_expires_at timestamp with time zone,
    email text,
    stripe_customer_id text,
    stripe_subscription_id text,
    subscription_status text,
    coaching_tier text,
    age smallint,
    sex text,
    height_cm numeric(6,2),
    weight_kg numeric(7,3),
    activity_level text,
    body_fat_pct numeric(4,1),
    unit_pref text DEFAULT 'imperial'::text NOT NULL,
    show_date date,
    show_name text,
    pause_resume_date date,
    paused_at timestamp with time zone,
    client_type text,
    checkin_cadence text,
    checkin_day_of_week smallint,
    weight_lb numeric(6,2),
    height_in numeric(5,2),
    goal_weight_lb numeric(6,2),
    goal_weight_kg numeric(7,3),
    CONSTRAINT clients_activity_ck CHECK (((activity_level IS NULL) OR (activity_level = ANY (ARRAY['sedentary'::text, 'light'::text, 'moderate'::text, 'active'::text, 'very_active'::text])))),
    CONSTRAINT clients_age_ck CHECK (((age IS NULL) OR ((age >= 0) AND (age <= 120)))),
    CONSTRAINT clients_bodyfat_ck CHECK (((body_fat_pct IS NULL) OR ((body_fat_pct >= (0)::numeric) AND (body_fat_pct <= (75)::numeric)))),
    CONSTRAINT clients_checkin_cadence_ck CHECK (((checkin_cadence IS NULL) OR (checkin_cadence = ANY (ARRAY['weekly'::text, 'biweekly'::text, 'monthly'::text])))),
    CONSTRAINT clients_checkin_dow_ck CHECK (((checkin_day_of_week IS NULL) OR ((checkin_day_of_week >= 0) AND (checkin_day_of_week <= 6)))),
    CONSTRAINT clients_client_type_ck CHECK (((client_type IS NULL) OR (client_type = ANY (ARRAY['lifestyle'::text, 'prep'::text])))),
    CONSTRAINT clients_coaching_tier_check CHECK ((coaching_tier = ANY (ARRAY['entry'::text, 'standard'::text]))),
    CONSTRAINT clients_sex_ck CHECK (((sex IS NULL) OR (sex = ANY (ARRAY['male'::text, 'female'::text, 'other'::text])))),
    CONSTRAINT clients_unit_pref_ck CHECK ((unit_pref = ANY (ARRAY['imperial'::text, 'metric'::text])))
);

--
-- Name: COLUMN clients.weight_kg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.weight_kg IS 'DERIVED from weight_lb for Mifflin-St Jeor. Never display this; display weight_lb.';

--
-- Name: COLUMN clients.show_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.show_date IS 'Target competition/photoshoot date. NULL = not a dated client; undated clients are excluded from the Prep rail, never ranked lower on it.';

--
-- Name: COLUMN clients.pause_resume_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.pause_resume_date IS 'Date a paused client is expected back. NULL on a paused client is what the home page flags.';

--
-- Name: COLUMN clients.client_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.client_type IS 'lifestyle or prep. Drives BOTH the program draft and the meal assembly: prep gets repetition and precision (fixed rotation, locked substitutions); lifestyle gets substitution room and a bad-week fallback. NULL means the intake did not state it — that is a gap to resolve with the client, never a value to default. Nothing downstream may assume lifestyle because the column is empty.';

--
-- Name: COLUMN clients.checkin_cadence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.checkin_cadence IS 'Per-client override of tenant_config.checkin_cadence. NULL = inherit the tenant default. Distinct from a zero: NULL is "not set here", not "no check-ins".';

--
-- Name: COLUMN clients.checkin_day_of_week; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.checkin_day_of_week IS '0=Sunday..6=Saturday. The anchor weekday for scheduled check-ins. NULL = inherit the day the client started.';

--
-- Name: COLUMN clients.weight_lb; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.weight_lb IS 'What the client actually typed, in pounds. CANONICAL FOR DISPLAY. weight_kg is derived from this and is for arithmetic only.';

--
-- Name: COLUMN clients.height_in; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.height_in IS 'What the client actually typed, in inches. CANONICAL FOR DISPLAY. height_cm is derived from this.';

--
-- Name: COLUMN clients.goal_weight_lb; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.goal_weight_lb IS 'Goal weight in pounds. CANONICAL FOR DISPLAY. Protein is computed off this, not off current weight.';

--
-- Name: COLUMN clients.goal_weight_kg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.goal_weight_kg IS 'DERIVED from goal_weight_lb. Never display.';

