--
-- Name: meals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.meals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid,
    slug text NOT NULL,
    name text NOT NULL,
    summary text,
    category text NOT NULL,
    base_servings integer DEFAULT 1 NOT NULL,
    prep_time_min integer,
    cook_time_min integer,
    kcal numeric,
    protein_g numeric,
    fat_g numeric,
    carb_g numeric,
    fiber_g numeric,
    macro_state text DEFAULT 'incomplete'::text NOT NULL,
    disruption_floor integer,
    downgrade_to_meal_id uuid,
    macro_lesson text,
    serves_lifestyle boolean DEFAULT true NOT NULL,
    serves_prep boolean DEFAULT false NOT NULL,
    allergen_review_state text DEFAULT 'unreviewed'::text NOT NULL,
    photo_path text,
    photo_source text,
    photo_alt text,
    status text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT meals_allergen_review_state_check CHECK ((allergen_review_state = ANY (ARRAY['reviewed'::text, 'unreviewed'::text]))),
    CONSTRAINT meals_base_servings_check CHECK ((base_servings > 0)),
    CONSTRAINT meals_category_check CHECK ((category = ANY (ARRAY['breakfast'::text, 'chicken'::text, 'beef'::text, 'fish'::text, 'eggs'::text, 'carb_side'::text, 'vegetable'::text, 'no_cook'::text, 'freezer'::text]))),
    CONSTRAINT meals_disruption_floor_check CHECK (((disruption_floor >= 1) AND (disruption_floor <= 4))),
    CONSTRAINT meals_macro_state_check CHECK ((macro_state = ANY (ARRAY['computed'::text, 'manual'::text, 'incomplete'::text]))),
    CONSTRAINT meals_photo_source_check CHECK ((photo_source = ANY (ARRAY['generated'::text, 'photographed'::text, 'licensed'::text]))),
    CONSTRAINT meals_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text])))
);

--
-- Name: TABLE meals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.meals IS 'Shared meal library. tenant_id NULL = global row readable by every tenant and writable by service_role only (no write policy covers those rows). tenant_id set = that tenant''s private meal. macro_state=''incomplete'' means an ingredient could not be resolved to a weight — such a meal must never be assigned or render a macro number. allergen_review_state=''unreviewed'' means absence of an allergen tag is NOT evidence of absence.';

--
-- Name: COLUMN meals.kcal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.meals.kcal IS 'Per serving. Library convention: kcal = protein*4 + carb*4 + fat*9 on TOTAL carbohydrate, so the number always equals the arithmetic of the macros shown beside it.';

--
-- Name: COLUMN meals.disruption_floor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.meals.disruption_floor IS 'Worst conditions under which this meal still works. 1 kitchen+40min · 2 batch-cooked, needs only fridge+microwave · 3 no kitchen, needs a cooler · 4 edible cold, no fridge, no equipment. Lets a plan be assembled as a good-week and a bad-week version from the same shelf so a client downgrades instead of quitting.';

--
-- Name: COLUMN meals.macro_lesson; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.meals.macro_lesson IS 'One sentence naming the mechanism of this plate — why this portion, which component is the dial. The library teaching its way out of being needed.';

