    type public.resource_type NOT NULL,
    file_url text NOT NULL,
    sort integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: tenant_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_config (
    tenant_id uuid NOT NULL,
    version integer DEFAULT 0 NOT NULL,
    published_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    logo_url text,
    app_name text,
    coach_display_name text,
    theme_key text DEFAULT 'liquid_glass'::text NOT NULL,
    welcome_message text,
    welcome_video_url text,
    about_headline text,
    about_body text,
    about_photo_url text,
    framework_name text,
    framework_body text,
    framework_media_url text,
    bio_body text,
    bio_photo_url text,
    checkin_cadence text DEFAULT 'weekly'::text NOT NULL,
    checkin_fields jsonb DEFAULT '{"photos": false, "weight": true, "questions": []}'::jsonb NOT NULL,
    progress_weight_on boolean DEFAULT true NOT NULL,
    progress_photos_on boolean DEFAULT true NOT NULL,
    messaging_on boolean DEFAULT true NOT NULL,
    weight_unit text DEFAULT 'lb'::text NOT NULL,
    published_snapshot jsonb,
    program_approval_gate boolean DEFAULT true NOT NULL,
    client_payment_url text,
    brand_color text DEFAULT '#0a0a0a'::text NOT NULL,
    surface_mode text DEFAULT 'dark'::text NOT NULL,
    type_key text DEFAULT 'grotesk'::text NOT NULL,
    coach_doctrine jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tenant_config_surface_mode_check CHECK ((surface_mode = ANY (ARRAY['dark'::text, 'light'::text]))),
    CONSTRAINT tenant_config_type_key_check CHECK ((type_key = ANY (ARRAY['grotesk'::text, 'serif'::text, 'condensed'::text])))
);

--
-- Name: COLUMN tenant_config.surface_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_config.surface_mode IS 'Home-page surface. Scoped to the coach overview; does not override the app-wide light/dark toggle in src/lib/theme.js.';

--
-- Name: COLUMN tenant_config.type_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_config.type_key IS 'Display typeface. grotesk = Archivo (installed), serif = New York/Georgia, condensed = Bebas Neue. Body and mono are fixed.';

--
-- Name: COLUMN tenant_config.coach_doctrine; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_config.coach_doctrine IS 'Structured coaching doctrine: { training_doctrine, intervention_rules[], voice, boundaries[] }. Coach-only — never exposed to a client-scoped token.';

