--
-- Name: trainerize_staging; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trainerize_staging (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    source_client_id text NOT NULL,
    source_client_email text,
    source_client_name text,
    matched_client_id uuid,
    match_status text NOT NULL,
    kind text NOT NULL,
    occurred_at timestamp with time zone,
    payload jsonb NOT NULL,
    promoted_at timestamp with time zone,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trainerize_staging_kind_check CHECK ((kind = ANY (ARRAY['profile'::text, 'consultation'::text, 'workout_session'::text, 'workout_set'::text, 'weight'::text, 'body_measurement'::text, 'progress_photo'::text, 'cardio_activity'::text, 'message'::text, 'nutrition_goal'::text]))),
    CONSTRAINT trainerize_staging_match_status_check CHECK ((match_status = ANY (ARRAY['matched'::text, 'unmatched'::text, 'ambiguous'::text])))
);

--
-- Name: v_pending_program_drafts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pending_program_drafts AS
 SELECT d.id AS draft_id,
    d.tenant_id,
    d.client_id,
    c.display_name,
    c.email,
    d.status,
    d.health_flags,
    d.macros,
    d.rationale,
    d.generated_at,
    jsonb_array_length(COALESCE((d.training -> 'days'::text), '[]'::jsonb)) AS training_days
   FROM (public.program_drafts d
     JOIN public.clients c ON ((c.id = d.client_id)))
  WHERE (d.status = ANY (ARRAY['draft'::public.program_draft_status, 'held_medical'::public.program_draft_status]));

