-- ===== migration 20260826120000_resource_library.sql =====
-- ---------------------------------------------------------------------------
-- Coach resources library — adds a description field to the existing
-- `resources` table (already RLS-ready for coach writes, see
-- resources_coach_all / resources_client_read from the original schema) and
-- one new storage read policy so a client can read a tenant-wide library file,
-- not just their own per-client nutrition PDF.
--
-- WHY A NEW POLICY, NOT AN EDIT TO res_owner_read. res_owner_read requires a
-- client's path to match their own client_id at foldername[2]. A shared
-- library file has no owning client — it lives at
-- <tenant_id>/library/<resource_id>.pdf — so it needs its own read rule.
-- res_owner_read, res_coach_write, and res_coach_update are untouched: the
-- coach can already write anywhere under <tenant_id>/... (no client_id
-- segment required), which is why only a new SELECT policy is needed here.
-- ---------------------------------------------------------------------------

alter table public.resources add column if not exists description text;

create policy res_library_client_read on storage.objects
  for select to authenticated
  using (
    bucket_id = 'resources'
    and (storage.foldername(name))[1] = (current_tenant_id())::text
    and (storage.foldername(name))[2] = 'library'
  );

-- Gap found during live verification (2026-08-26): the `resources` bucket had
-- SELECT/INSERT/UPDATE policies but no DELETE policy at all — nothing needed
-- one before, since the meal-plan PDF path only ever upserts in place, never
-- removes a file. removeResource() in src/lib/resourceLibrary.js does delete
-- a library file, and without this the delete was silently blocked by RLS:
-- the resources row disappeared but the underlying file stayed orphaned.
create policy res_coach_delete on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'resources'
    and current_app_role() = 'coach'
    and (storage.foldername(name))[1] = (current_tenant_id())::text
  );

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260826170000_coach_overview_perf.sql =====
-- ---------------------------------------------------------------------------
-- Coach Home performance fix, safe tier only (2026-08-26).
--
-- Found while testing the "Refresh signals" button: rm_coach_overview() runs
-- ~2.4s on average and up to ~8s over 282 real calls (pg_stat_statements),
-- occasionally hitting the statement timeout outright. Measured live as the
-- real owner-tenant coach account (not superuser): 1.66s. As superuser/service role
-- (which bypasses RLS), the same call runs in single-digit milliseconds —
-- proving the cost is RLS-path work, not data volume (37 clients, low
-- hundreds of rows per table).
--
-- Two changes here, both additive/subtractive only — same JSON output,
-- verified byte-for-byte against a live call before and after:
--
-- 1. rm__cfg_text(tenant_id, 'surface_mode' | 'type_key') ran a live
--    information_schema.columns existence check on every single call, for
--    two columns that have existed for weeks (confirmed: no other function
--    calls rm__cfg_text). Replaced with a direct column read.
--
-- 2. rm_attention_candidates() — the full 9-signal severity/recency/scoring
--    pipeline — was called twice per page load: once to build the ranked
--    queue, once again from scratch to compute the suppressed-signal counts.
--    Confirmed by counting call sites in the live function body. Now
--    computed once into a CTE (cand_raw) and reused by both blocks.
--
-- The bigger, higher-payoff cause (every table carries two separate RLS
-- policies — a client-ownership check and a coach-tenant check — so a coach
-- read still pays for an expensive, always-false client lookup on every row;
-- confirmed against pg_policies and independently flagged 900+ times by
-- Supabase's own performance advisor across this schema) is NOT touched
-- here. That fix rewrites RLS policies across most of the database and
-- needs its own written plan and the platform owner's explicit approval before any code
-- is touched — this migration is deliberately the safe, no-security-surface
-- half only.
-- ---------------------------------------------------------------------------

create index if not exists workout_sessions_tenant_session_date_idx
  on public.workout_sessions (tenant_id, session_date);

create index if not exists workout_sessions_tenant_completed_at_idx
  on public.workout_sessions (tenant_id, completed_at);

create index if not exists checkins_tenant_submitted_at_idx
  on public.checkins (tenant_id, submitted_at);

create index if not exists workout_logs_tenant_logged_at_idx
  on public.workout_logs (tenant_id, logged_at);

create index if not exists messages_tenant_sent_at_idx
  on public.messages (tenant_id, sent_at);

-- meal_plans already has a (tenant_id, client_id) unique index, but the
-- no_meal_plan decision's NOT EXISTS subquery filters by client_id alone —
-- tenant_id leading the composite index doesn't serve a client_id-only
-- lookup. A dedicated index on the trailing column does.
create index if not exists meal_plans_client_id_idx
  on public.meal_plans (client_id);

create or replace function public.rm_coach_overview()
returns jsonb
language plpgsql stable security invoker
set search_path = public as $fn$
declare
  v_tenant  uuid := current_tenant_id();
  v_sources jsonb;
  v_conf    jsonb;
  v_out     jsonb;
begin
  if v_tenant is null then
    raise exception 'rm_coach_overview: no tenant in session';
  end if;

  -- Sources first. Nothing below is readable without them.
  select jsonb_agg(to_jsonb(s) order by
           case s.key when 'training' then 1 when 'checkins' then 2
                      when 'messages' then 3 else 4 end)
    into v_sources
  from rm_source_health() s;

  select jsonb_object_agg(s->>'key', (s->>'confidence')::numeric)
    into v_conf
  from jsonb_array_elements(v_sources) s;

  with cand_raw as (
    -- Computed once. Previously called a second time, from scratch, by the
    -- suppressed-signal count below — the whole severity/recency/scoring
    -- pipeline ran twice per page load for one page.
    select * from rm_attention_candidates()
  ),
  cand as (
    select c.*, coalesce((v_conf->>c.source_key)::numeric, 0) as conf
    from cand_raw c
  ),
  scored as (
    select cand.*, round(severity * recency * conf, 4) as score from cand
  ),
  banded as (
    select scored.*,
      case
        -- 'decide' is not a score band. It is any item whose resolution is a
        -- coach decision with a deadline, and it always renders.
        when is_decision then 'decide'
        when score >= 0.7 then 'act'
        when score >= 0.4 then 'watch'
        else 'hold'
      end as band
    from scored
    -- RULE 1: a signal from a source that is not live or stale cannot produce
    -- an attention item. conf = 0 for unavailable / not_configured.
    where conf > 0
  ),
  -- ---------------- grouping ----------------
  -- The mockup collapses a repeated signal into one card ("6 clients — Active
  -- assignment, no meal plan") rather than printing six. Without this the queue
  -- is 33 rows deep on the current data and stops being a ranking at all.
  -- Threshold 3: up to three named clients read as individuals; four or more is
  -- a pattern, and for a pattern the coach wants a list, not a queue.
  sized as (
    select b.*, count(*) over (partition by b.signal_type) as sig_n from banded b
  ),
  singles as (
    select client_id, display_name, band, score, signal_type, source_key,
           mechanism, evidence, actions, since, deadline, 1 as member_count
    from sized where sig_n <= 3
  ),
  grouped as (
    select
      null::uuid as client_id,
      rm__n(count(*), 'client') as display_name,
      -- A group is at least as urgent as its most urgent member.
      (array_agg(band order by score desc))[1] as band,
      max(score) as score,
      signal_type, source_key,
      -- Plural copy per signal, in SQL, so the connector reads the same sentence
      -- The coach reads.
      case signal_type
        when 'training_silent' then
          'No logged session in over three days against an active assignment.'
        when 'account_unreachable' then
          'Client records with no account attached and no invite issued. They cannot open the app.'
        when 'no_meal_plan' then
          'Active assignment with no meal plan attached. The nutrition surface is blank on their side.'
        when 'unread_message' then 'Messages waiting over 24 hours, unanswered.'
        when 'overreach' then
          'More sessions logged in seven days than the program prescribes.'
        when 'paused_no_resume' then
          'Paused with no resume date recorded, so nothing will surface them again on its own.'
        when 'load_regression' then
          'Top-set load falling across three sessions running while volume holds.'
        when 'first_week_strong' then
          'First full week complete, every prescribed session logged.'
        else 'Multiple clients on the same signal.'
      end as mechanism,
      jsonb_build_array(
        jsonb_build_object('label', 'clients', 'value', count(*)::text),
        jsonb_build_object('label', 'longest waiting',
          'value', (array_agg(display_name order by score desc, display_name))[1]
                   || case when count(*) > 1 then ' +' || (count(*) - 1) else '' end)
      ) as evidence,
      jsonb_build_array(
        jsonb_build_object('key','review_list','label','Review list','primary',true)
      ) as actions,
      min(since) as since,
      min(deadline) as deadline,
      count(*)::int as member_count
    from sized where sig_n > 3
    group by signal_type, source_key
  ),
  queue as (
    select * from singles
    union all
    select * from grouped
  )
  select jsonb_build_object(
    'schema_version', 1,
    'generated_at',   now(),

    -- ---------------- tenant brand ----------------
    'tenant', (
      select jsonb_build_object(
        'tenant_id',          t.id,
        'slug',               t.slug,
        'app_name',           coalesce(tc.app_name, 'Coach App'),
        'coach_display_name', tc.coach_display_name,
        'logo_url',           tc.logo_url,
        'brand_color',        tc.brand_color,
        'theme_key',          tc.theme_key,
        -- Direct column reads. Previously routed through rm__cfg_text(), which
        -- ran a live information_schema.columns existence check on every call
        -- for two columns that have existed since the schema-gap migration —
        -- see 2026-08-26 perf fix note at the top of this migration.
        'surface_mode',       coalesce(tc.surface_mode, 'dark'),
        'type_key',           coalesce(tc.type_key, 'grotesk'),
        'weight_unit',        tc.weight_unit,
        'features', jsonb_build_object(
          'messaging',       tc.messaging_on,
          'progress_photos', tc.progress_photos_on,
          'progress_weight', tc.progress_weight_on,
          'approval_gate',   tc.program_approval_gate
        ))
      from tenant_config tc join tenants t on t.id = tc.tenant_id
      where tc.tenant_id = v_tenant
    ),

    'sources', v_sources,

    -- ---------------- roster pulse ----------------
    -- A metric whose backing source is unhealthy is returned as JSON null, NOT
    -- 0. The UI renders null as a hatched em-dash. A false zero here is the
    -- specific failure this page exists to prevent: 0 reads as "nobody trained"
    -- and would have a coach message a client who did train.
    'roster', (
      select jsonb_build_object(
        'total',   count(*),
        'active',  count(*) filter (where status = 'active'),
        'paused',  count(*) filter (where status = 'paused'),
        'invited', count(*) filter (where status = 'invited'),
        'trained_7d', case when (v_conf->>'training')::numeric > 0 then (
            select count(distinct ws.client_id) from workout_sessions ws
            where ws.tenant_id = v_tenant
              and ws.session_date > (now() - interval '7 days')::date) end,
        'silent_7d', case when (v_conf->>'training')::numeric > 0 then (
            select count(*) from assignments a
            join clients cc on cc.id = a.client_id and cc.status = 'active'
            where a.tenant_id = v_tenant and a.active
              and not exists (select 1 from workout_sessions ws
                where ws.client_id = a.client_id
                  and ws.session_date > (now() - interval '7 days')::date)) end,
        'checked_in_7d', case when (v_conf->>'checkins')::numeric > 0 then (
            select count(distinct ck.client_id) from checkins ck
            where ck.tenant_id = v_tenant
              and ck.submitted_at > now() - interval '7 days') end
      )
      from clients where tenant_id = v_tenant
    ),

    -- ---------------- ranked attention ----------------
    'attention', coalesce((
      select jsonb_agg(jsonb_build_object(
        'client_id', client_id, 'display_name', display_name,
        'band', band, 'score', score,
        'signal_type', signal_type, 'source_key', source_key,
        'mechanism', mechanism, 'evidence', evidence, 'actions', actions,
        'since', since, 'deadline', deadline,
        -- >1 means this card stands for a group, not one person. The UI uses it
        -- to label the action button and to avoid implying a single client.
        'member_count', member_count)
      order by case band when 'act' then 1 when 'decide' then 2
                         when 'watch' then 3 else 4 end,
               score desc, display_name)
      from queue), '[]'::jsonb),

    -- ---------------- suppression ----------------
    -- RULE 2: an unhealthy source yields a count, never a flag. RULE 3: the UI
    -- renders this hatched, and never as an empty queue.
    'suppressed', coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_key', x.source_key, 'withheld_count', x.n,
        'reason', x.reason, 'since', x.since) order by x.n desc)
      from (
        select c.source_key, count(*)::int as n,
          (select s->>'note' from jsonb_array_elements(v_sources) s
            where s->>'key' = c.source_key) as reason,
          (select (s->>'last_event_at')::timestamptz from jsonb_array_elements(v_sources) s
            where s->>'key' = c.source_key) as since
        from cand_raw c
        where coalesce((v_conf->>c.source_key)::numeric, 0) = 0
        group by c.source_key
      ) x), '[]'::jsonb),

    -- ---------------- decisions ----------------
    -- Roster-derived, so this card never empties just because a feed died.
    'decisions', coalesce((
      select jsonb_agg(d order by d->>'ord')
      from (
        select jsonb_build_object('ord','1','kind','draft_approval',
          'title','Program drafts awaiting approval',
          'detail', case when (select program_approval_gate from tenant_config
                               where tenant_id = v_tenant)
                    then 'Approval gate is on. Nothing reaches a client until you release it.'
                    else 'Approval gate is off — drafts publish without review.' end,
          'count', (select count(*) from program_drafts
                     where tenant_id = v_tenant and status = 'draft')) as d
        union all
        select jsonb_build_object('ord','2','kind','no_meal_plan',
          'title','Active clients without a meal plan',
          'detail','Assignment live, nutrition surface blank on their side.',
          'count', (select count(*) from assignments a
                     join clients c on c.id = a.client_id and c.status = 'active'
                     where a.tenant_id = v_tenant and a.active
                       and not exists (select 1 from meal_plans mp
                         where mp.client_id = c.id)))
        union all
        -- Drafted but never released. One click each, and the client currently
        -- sees a blank nutrition surface despite the work already being done.
        select jsonb_build_object('ord','3','kind','meal_plan_unreleased',
          'title','Meal plans drafted, never released',
          'detail','The work is done. Until it is assigned, the client cannot see it.',
          'count', (select count(*) from meal_plans
                     where tenant_id = v_tenant and assigned_at is null))
        union all
        select jsonb_build_object('ord','4','kind','account_unreachable',
          'title','Clients with no account attached',
          'detail','Record created, no invite issued. They cannot open the app.',
          'count', (select count(*) from clients where tenant_id = v_tenant
                     and client_user_id is null and status <> 'paused'),
          'deadline', (select min(invite_expires_at) from clients where tenant_id = v_tenant
                     and client_user_id is null))
        union all
        select jsonb_build_object('ord','5','kind','paused_no_resume',
          'title','Paused without a resume date',
          'detail','Will not resurface on its own until a resume date is set.',
          'count', (select count(*) from clients
                     where tenant_id = v_tenant and status = 'paused'
                       and pause_resume_date is null))
      ) dec_rows
      where (d->>'count')::int > 0), '[]'::jsonb),

    -- ---------------- prep timelines ----------------
    -- clients.show_date now exists (20260729120100). Undated clients are EXCLUDED
    -- from this rail, never ranked lower on it. With every show_date still null
    -- this returns [] with unavailable=false, so the UI shows the SOLID "no dates
    -- set" empty state -- we know, and there are none -- not the hatched
    -- "cannot see" state. That distinction is the whole point of the page.
    'timelines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'client_id', c.id, 'display_name', c.display_name,
        'event_date', c.show_date,
        'weeks_out', ceil((c.show_date - now()::date) / 7.0),
        'phase', case
          when c.show_date - now()::date <= 7  then 'peak week'
          when c.show_date - now()::date <= 28 then 'final month'
          else 'build' end,
        'note', coalesce(c.show_name, 'no show name set'))
      order by c.show_date)
      from clients c
      where c.tenant_id = v_tenant and c.status = 'active'
        and c.show_date is not null and c.show_date >= now()::date
    ), '[]'::jsonb),
    'timelines_unavailable', false,
    'timelines_note', null,

    -- Signals the read model knows about but cannot compute on this schema.
    -- Reported so the page can be honest instead of silently omitting them.
    -- program_ending is now computable: assignments.ends_on exists and the
    -- signal is live in rm_attention_candidates. Nothing is currently
    -- uncomputable, so this list is empty and the UI hides the block.
    'unavailable_signals', '[]'::jsonb,

    -- ---------------- activity ----------------
    -- Chronological, deliberately last, capped at 8.
    'activity', coalesce((
      select jsonb_agg(e order by (e->>'at') desc)
      from (
        select jsonb_build_object('at', ws.completed_at, 'client_id', ws.client_id,
          'display_name', c.display_name, 'kind','session_complete',
          'summary','completed a session'
            || coalesce((select ' — ' || count(*) || ' sets' from workout_logs wl
                 where wl.session_id = ws.id and wl.done
                 having count(*) > 0), '')) as e
        from workout_sessions ws join clients c on c.id = ws.client_id
        where ws.tenant_id = v_tenant and ws.completed_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', wl.logged_at, 'client_id', wl.client_id,
          'display_name', c.display_name, 'kind','set_logged',
          'summary','logged a set'
            || coalesce(' — ' || wl.weight || ' x ' || wl.reps, ''))
        from workout_logs wl join clients c on c.id = wl.client_id
        where wl.tenant_id = v_tenant and wl.logged_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', m.sent_at, 'client_id', m.client_id,
          'display_name', c.display_name, 'kind','message', 'summary','messaged you')
        from messages m join clients c on c.id = m.client_id
        where m.tenant_id = v_tenant and m.sender_role = 'client'
          and m.sent_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', ck.submitted_at, 'client_id', ck.client_id,
          'display_name', c.display_name, 'kind','checkin','summary','submitted a check-in')
        from checkins ck join clients c on c.id = ck.client_id
        where ck.tenant_id = v_tenant and ck.submitted_at > now() - interval '24 hours'
        order by 1 desc
        limit 8
      ) ev), '[]'::jsonb)
  ) into v_out;

  return v_out;
end;
$fn$;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260826180000_rls_initplan_perf.sql =====
-- ---------------------------------------------------------------------------
-- Coach Home performance fix, tier 2 — Part A only (2026-08-26).
--
-- See the original design notes (not included) for the full writeup.
-- Verified in a rolled-back transaction before this was committed:
--
--   - Wraps the three lookup functions (current_tenant_id, current_client_id,
--     current_app_role) in scalar subqueries everywhere they appear bare in
--     an RLS policy across the 9 tables the Coach Home call chain reads.
--     `x = current_tenant_id()` becomes `x = (select current_tenant_id())`.
--     This is the exact pattern Supabase's own performance advisor
--     recommends (auth_rls_initplan) -- it changes nothing about WHO can see
--     WHAT, only how many times Postgres has to re-run the lookup. Every
--     policy's boolean predicate is mathematically identical before and
--     after; only the evaluation/caching strategy changes.
--
--   - Correctness: ran the same read as 4 real identities (the owner's
--     coach account, a second real coach account on a different tenant, and
--     two real distinct client accounts) across all 9 tables -- 36
--     combinations -- before and after this change, in a rolled-back
--     transaction. Every row set returned was identical, including two
--     non-trivial cases: the programs table's EXISTS-based client policy,
--     and confirming the cross-tenant coach still sees zero rows of the owner tenant's
--     multi-client dataset (not a trivial empty-vs-empty comparison -- the owner tenant
--     has real data to leak into a broken policy and didn't).
--
--   - Performance: measured rm_coach_overview() as the platform owner's real coach
--     account, same test as the tier-1 migration. 2.4s average / ~8s peak
--     originally -> ~1.0s after tier-1's indexes and dedup work -> 240ms
--     with this change added on top, same rolled-back-transaction test run
--     twice for consistency. Buffer reads dropped from ~28,900 (pre-tier-1)
--     to ~6,400.
--
-- Part B from the plan doc (actually merging each table's client-policy and
-- coach-policy into one combined policy, rather than just wrapping the
-- function calls) is NOT included here. Verification surfaced real added
-- complexity the original plan underestimated -- several tables split
-- coach access across ALL-scoped and client access across SELECT-only
-- policies, so a true merge needs restructuring command scope, not a
-- straight 2-into-1 swap. Given Part A alone already gets this down to
-- 240ms, Part B is being deferred rather than pushed through to match the
-- plan document's original framing.
-- ---------------------------------------------------------------------------

alter policy assign_coach_all on public.assignments
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'))
  with check ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));
alter policy assign_client_read on public.assignments
  using (client_id = (select current_client_id()));

alter policy cha_client_read on public.checkin_hub_archive
  using (client_id = (select current_client_id()));
alter policy cha_coach_read on public.checkin_hub_archive
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));

alter policy checkins_coach_rw on public.checkins
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'))
  with check ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));
alter policy checkins_client_insert on public.checkins
  with check ((client_id = (select current_client_id())) and (tenant_id = (select current_tenant_id())));
alter policy checkins_client_read on public.checkins
  using (client_id = (select current_client_id()));

alter policy clients_coach_all on public.clients
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'))
  with check ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));

alter policy meal_plans_coach_all on public.meal_plans
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'))
  with check ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));
alter policy meal_plans_client_read on public.meal_plans
  using ((client_id = (select current_client_id())) and (status = 'assigned'));

alter policy msg_coach_all on public.messages
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'))
  with check ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach') and (sender_role = 'coach'));
alter policy msg_client_insert on public.messages
  with check ((client_id = (select current_client_id())) and (tenant_id = (select current_tenant_id())) and (sender_role = 'client'));
alter policy msg_client_read on public.messages
  using (client_id = (select current_client_id()));

alter policy programs_coach_all on public.programs
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'))
  with check ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));
alter policy programs_client_read on public.programs
  using (exists (select 1 from assignments a where a.program_id = programs.id and a.client_id = (select current_client_id())));

alter policy logs_client_all on public.workout_logs
  using (client_id = (select current_client_id()))
  with check ((client_id = (select current_client_id())) and (tenant_id = (select current_tenant_id())));
alter policy logs_coach_read on public.workout_logs
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));

alter policy sess_client_all on public.workout_sessions
  using (client_id = (select current_client_id()))
  with check ((client_id = (select current_client_id())) and (tenant_id = (select current_tenant_id())));
alter policy sess_coach_read on public.workout_sessions
  using ((tenant_id = (select current_tenant_id())) and ((select current_app_role()) = 'coach'));

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260826190000_archive_notes_and_programs.sql =====
-- ============================================================================
-- Retirement paths for coach notes and programs.
--
-- WHY. The coach's live roster session (2026-08-26) hit a program library with
-- duplicate and stale entries per client and no way to clean it up. Nothing
-- retires a program, and nothing retires a note. The only "cleanup" available
-- was DELETE, and deleting a program is not a cleanup — assignments.program_id
-- is ON DELETE CASCADE (see the production baseline), so deleting a program
-- with any assignment history silently takes those assignment rows with it and
-- orphans the client's logged workout history behind them.
--
-- ADDITIVE ONLY. Two nullable timestamp columns. No existing row changes
-- meaning: archived_at IS NULL is the state every current row is already in,
-- and every existing query that does not mention archived_at keeps returning
-- exactly what it returns today. Nothing is hidden from an existing surface by
-- this migration alone.
--
-- Rollback:
--   alter table public.client_notes drop column archived_at;
--   alter table public.programs     drop column archived_at;
-- ============================================================================

alter table public.client_notes
  add column if not exists archived_at timestamp with time zone;

comment on column public.client_notes.archived_at is
  'Set when a coach archives a note. Soft hide, never a delete — a note is a '
  'record of what the coach observed and when, and that record is worth more '
  'than a tidy list. NULL means active.';

alter table public.programs
  add column if not exists archived_at timestamp with time zone;

comment on column public.programs.archived_at is
  'Set when a coach retires a program from the library. The program, its '
  'structure uuids, and every assignment and workout log anchored to them stay '
  'intact — an archived program still resolves for a client mid-cycle and still '
  'names itself correctly in that client program history. NULL means active.';

-- Partial indexes: every default listing filters archived_at is null, and that
-- is the only shape these need to serve.
create index if not exists client_notes_active_idx
  on public.client_notes (tenant_id, client_id, created_at desc)
  where archived_at is null;

create index if not exists programs_active_idx
  on public.programs (tenant_id, created_at desc)
  where archived_at is null;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260826190100_support_tickets_and_message_templates.sql =====
-- ============================================================================
-- Two new tenant-scoped tables: support_tickets and message_templates.
--
-- WHY. The coach's endpoint wishlist
-- asks for create_support_ticket, get_escalation_history, get_message_templates
-- and save_message_template. There is no ticket table and no template table
-- anywhere in this schema — verified against the production baseline and all
-- 47 migrations before writing this. These are genuinely new, not a column add.
--
-- ADDITIVE ONLY. Two tables, their RLS, and the suspension guard. No existing
-- table, type, policy, function or trigger is altered or dropped.
--
-- THE SUSPENSION GUARD IS ATTACHED HERE, EXPLICITLY. 20260728234500 attached
-- trg_tenant_suspension_guard by looping over every tenant_id table that
-- existed AT THE TIME IT RAN — it does not fire on future CREATE TABLE, which
-- is exactly how 23 tables ended up with no guard at all (see
-- 20260824180000_suspension_guard_missing_tables.sql). Any new tenant-scoped
-- table must attach it itself or it repeats that bug on day one.
--
-- Rollback:
--   drop table public.support_tickets;
--   drop table public.message_templates;
-- ============================================================================

-- ---------------------------------------------------------------------------
-- support_tickets — an issue logged on a client's behalf, and its escalation
-- history. client_id is NULLABLE on purpose: not every issue is about a
-- client. A billing problem, an app bug, a "the intake link 404s" is about the
-- business, and forcing it to name a client would mean picking one at random.
-- ---------------------------------------------------------------------------
create table if not exists public.support_tickets (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  client_id    uuid references public.clients(id) on delete set null,

  title        text not null,
  detail       text,

  -- low / normal / high. Deliberately three, not five: a five-point scale gets
  -- used as a two-point scale plus noise.
  severity     text not null default 'normal',

  -- open -> acknowledged -> resolved. `resolution` is required to resolve (see
  -- the CHECK below) so a ticket cannot be closed with no account of what
  -- happened — a silently closed ticket is worse than an open one, because it
  -- stops anyone looking.
  status       text not null default 'open',
  resolution   text,

  -- The coach auth user who opened it. Nullable so a ticket opened by an
  -- automated path is not forced to invent an author.
  opened_by    uuid,

  created_at   timestamp with time zone not null default now(),
  updated_at   timestamp with time zone not null default now(),
  resolved_at  timestamp with time zone,

  constraint support_tickets_severity_check
    check (severity in ('low', 'normal', 'high')),
  constraint support_tickets_status_check
    check (status in ('open', 'acknowledged', 'resolved')),
  -- A resolved ticket must say how it was resolved, and must carry the time.
  constraint support_tickets_resolution_required
    check (status <> 'resolved' or (resolution is not null and resolved_at is not null))
);

create index if not exists support_tickets_tenant_status_idx
  on public.support_tickets (tenant_id, status, created_at desc);
create index if not exists support_tickets_client_idx
  on public.support_tickets (tenant_id, client_id, created_at desc)
  where client_id is not null;

comment on table public.support_tickets is
  'Issues logged by a coach (or their AI) on a client''s behalf, plus the '
  'escalation history read back by get_escalation_history. client_id is null '
  'for business-level issues that are about no particular client.';

-- ---------------------------------------------------------------------------
-- message_templates — reusable message bodies for a coach's own workspace.
-- Bodies may contain {{display_name}} / {{first_name}}; substitution lives in
-- supabase/functions/mcp/messaging.ts, NOT here, so the template table never
-- has to know what a placeholder means.
-- ---------------------------------------------------------------------------
create table if not exists public.message_templates (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,

  -- The name the coach says out loud ("send them the check-in nudge").
  -- Unique per tenant so "the check-in nudge" always names one thing.
  slug        text not null,
  title       text not null,
  body        text not null,

  -- Free text. Not enum-constrained, matching the dm_inbound.keyword_tag
  -- precedent — a coach inventing their own grouping should not need a
  -- migration.
  category    text,

  created_by  uuid,
  created_at  timestamp with time zone not null default now(),
  updated_at  timestamp with time zone not null default now()
);

create unique index if not exists message_templates_tenant_slug_uniq
  on public.message_templates (tenant_id, slug);

comment on table public.message_templates is
  'Reusable coach message bodies, per tenant. Placeholder substitution is the '
  'sending code''s job (supabase/functions/mcp/messaging.ts), not this table''s.';

-- ---------------------------------------------------------------------------
-- RLS. Same shape as coach_videos (20260731060000): tenant resolved from the
-- caller''s own profile row via current_tenant_id(), never from a parameter.
-- Neither table is client-readable — support tickets can contain a coach''s
-- candid account of a client''s situation, and templates are internal drafting
-- material. Clients get no policy at all, which is the deny.
-- ---------------------------------------------------------------------------
alter table public.support_tickets   enable row level security;
alter table public.message_templates enable row level security;

create policy support_tickets_coach_all on public.support_tickets
  for all to authenticated
  using      (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach')
  with check (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach');

create policy message_templates_coach_all on public.message_templates
  for all to authenticated
  using      (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach')
  with check (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach');

-- ---------------------------------------------------------------------------
-- Suspension guard — see the header. Same function, same exemptions
-- (service_role and SECURITY DEFINER bodies) as the other 55 tenant tables.
-- ---------------------------------------------------------------------------
do $attach$
declare
  t text;
begin
  foreach t in array array['support_tickets', 'message_templates'] loop
    execute format('drop trigger if exists trg_tenant_suspension_guard on public.%I', t);
    execute format(
      'create trigger trg_tenant_suspension_guard
         before insert or update or delete on public.%I
         for each row execute function public.enforce_tenant_not_suspended()', t);
  end loop;
end
$attach$;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260826200000_client_documents.sql =====
-- ============================================================================
-- client_documents — signed PAR-Q forms, waivers, IDs, medical notes.
--
-- WHY. The original MCP endpoint spec held this back as an open question:
-- should raw client PII documents transit an AI tool call at all? The coach's answer, verbatim:
-- "Everything should be readable so a coach can operate high caliber as the only human in the
-- loop giving more ownership and control while overhead kept low and output increases." That
-- picks the FULL option, not the restrictive kind-allowlist fallback the spec proposed as a
-- cautious default — every kind (parq, waiver, id, medical, other) is readable through the MCP
-- surface, not just parq + waiver.
--
-- "Everything readable" is a scope decision, not a security exemption. The signed-URL,
-- coach-only, no-raw-bytes discipline this migration applies is unchanged by it — it is the same
-- discipline already applied to progress-photos and resources, and dropping it would not make
-- more things readable, it would just make them readable less safely.
--
-- SCOPE. This is a new bucket and a new table — no existing bucket or table held any of this
-- before now (confirmed by reading 20260728214500_storage_scope_private_files_to_owning_client.sql,
-- which lists progress-photos, resources and meal-photos as the only three buckets that exist).
--
-- BUCKET RLS shape mirrors 20260728214500 exactly: current_tenant_id() + current_client_id() for
-- the owning client, OR current_app_role() = 'coach' for the tenant's coach. Unlike that
-- migration, there is deliberately no client-facing feature reading this bucket today — a client
-- reading back their own uploaded ID is a real, separate product question, not a side effect of
-- this migration. The owner-read policy is written to already be correct WHEN that feature is
-- built, rather than needing a second RLS pass then.
--
-- TABLE RLS is coach-only, no client policy at all (the deny), matching support_tickets and
-- message_templates from 20260826190100 — a coach's note that a client's ID looked altered, or a
-- record of what medical documentation is on file, is not something a client's own token should
-- be able to enumerate.
--
-- THE SUSPENSION GUARD IS ATTACHED HERE, EXPLICITLY, for the same reason 20260826190100 attaches
-- it explicitly: 20260728234500 only looped over tables that existed when it ran, so any new
-- tenant-scoped table must attach trg_tenant_suspension_guard itself or it silently joins the 23
-- tables the project notes already documents as unguarded.
--
-- Rollback:
--   drop table public.client_documents;
--   drop policy if exists client_documents_owner_read  on storage.objects;
--   drop policy if exists client_documents_owner_write on storage.objects;
--   delete from storage.buckets where id = 'client-documents';
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Bucket. Private — these are the most sensitive files this schema will ever hold.
-- 10 MB matches the application-level cap in supabase/functions/mcp/documents.ts
-- (MAX_DOCUMENT_BASE64_CHARS, ~6 MB of real file); the bucket limit is set a little above that
-- so the two never disagree at the boundary in a confusing direction.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'client-documents',
  'client-documents',
  false,
  10485760,
  array['application/pdf', 'image/jpeg', 'image/png', 'image/heic', 'image/webp']
)
on conflict (id) do nothing;

-- READ: the owning client, or the tenant's coach. No app feature calls this yet — the MCP tools
-- use the service-role client and bypass RLS entirely — this exists so the policy is already
-- correct the day a client-facing "my documents" view is built, instead of needing this same
-- review done under time pressure then.
create policy client_documents_owner_read on storage.objects
  for select to authenticated
  using (
    bucket_id = 'client-documents'
    and (
      (
        (storage.foldername(name))[1] = (current_tenant_id())::text
        and (storage.foldername(name))[2] = (current_client_id())::text
      )
      or (
        current_app_role() = 'coach'
        and (storage.foldername(name))[1] = (current_tenant_id())::text
      )
    )
  );

-- WRITE: coach only. upload_client_document in the MCP surface is coach-only by construction
-- (it lives in COACH_TOOLS, never CLIENT_TOOLS, and toolSurface.test.ts enforces that split) —
-- this policy makes the same true for any future direct app-level upload path, so the guarantee
-- does not depend on every future caller remembering to route through the MCP surface.
create policy client_documents_owner_write on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'client-documents'
    and current_app_role() = 'coach'
    and (storage.foldername(name))[1] = (current_tenant_id())::text
  );

-- ---------------------------------------------------------------------------
-- Table. One row of metadata per stored file; the bytes live in the bucket above.
-- ---------------------------------------------------------------------------
create table if not exists public.client_documents (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  client_id     uuid not null references public.clients(id) on delete cascade,

  kind          text not null,
  title         text,
  filename      text not null,
  storage_path  text not null unique,
  mime_type     text not null,
  size_bytes    integer not null,

  uploaded_by   uuid,
  created_at    timestamp with time zone not null default now(),

  constraint client_documents_kind_check
    check (kind in ('parq', 'waiver', 'id', 'medical', 'other')),
  constraint client_documents_size_check
    check (size_bytes > 0)
);

create index if not exists client_documents_client_idx
  on public.client_documents (tenant_id, client_id, created_at desc);
create index if not exists client_documents_kind_idx
  on public.client_documents (tenant_id, client_id, kind);

comment on table public.client_documents is
  'Metadata for files in the client-documents storage bucket — signed PAR-Q forms, waivers, IDs, '
  'medical notes. storage_path points into that bucket; the MCP surface always returns a '
  'short-lived signed URL, never the path or raw bytes, to any caller.';

-- ---------------------------------------------------------------------------
-- RLS. Coach-only, same shape as support_tickets / message_templates (20260826190100).
-- ---------------------------------------------------------------------------
alter table public.client_documents enable row level security;

create policy client_documents_coach_all on public.client_documents
  for all to authenticated
  using      (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach')
  with check (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach');

-- ---------------------------------------------------------------------------
-- Suspension guard — see the header.
-- ---------------------------------------------------------------------------
drop trigger if exists trg_tenant_suspension_guard on public.client_documents;
create trigger trg_tenant_suspension_guard
  before insert or update or delete on public.client_documents
  for each row execute function public.enforce_tenant_not_suspended();

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260830120000_brief_slides.sql =====
-- ============================================================================
-- brief_slides — the ordered strip of still images on the Brief tab.
--
-- WHY. The Brief tab (coach front door, mirrored read-only on the client front door)
-- shows one reel via tenant_config.welcome_video_url. The coach asked for slides alongside
-- it (2026-08-30, the original design notes (not included)): uploaded
-- stills, ordered, visible to coach AND clients — a supporting deck for the weekly reel.
--
-- STORAGE DEPENDENCY — the `brand` bucket, which exists in production but in NO
-- migration file (created via dashboard; verified live 2026-08-30: public=true,
-- no size limit, policies brand_coach_read/write/update/delete all scoped to
-- foldername[1] = current_tenant_id() and role coach). Slide images live there under
-- <tenant_id>/brief-slides/. This migration deliberately does NOT create or alter that
-- bucket: codifying dashboard-created objects is a separate, reviewed decision, not a
-- side effect of a feature migration. Marketing-grade content only — the UI and the MCP
-- tool descriptions both say no client PII in slides.
--
-- POSITION. 1..12, same cap and same reasoning as coach_videos_slot_range
-- (20260731060000): a position is a landmark, and past a dozen it stops being one.
-- Unlike coach_videos there is no UNIQUE on (tenant_id, position): reordering is a
-- two-row swap from the browser, which cannot run in one transaction through PostgREST,
-- so a unique constraint would make every swap a three-step temp-slot dance. Render
-- order is (position, created_at, id) — deterministic even mid-swap. The 12-slide COUNT
-- cap is enforced by the app and the MCP tool, not the database; the position range is
-- enforced here.
--
-- RLS mirrors coach_videos exactly: coach full control within tenant, tenant-wide
-- member read (every client of this coach sees the same strip).
--
-- SUSPENSION GUARD attached explicitly — 20260728234500 only looped over tables that
-- existed when it ran; every new tenant-scoped table attaches it itself or silently
-- joins the unguarded list the project notes documents.
--
-- Rollback:
--   drop table public.brief_slides;
--   (storage objects under <tenant>/brief-slides/ in `brand` are cleaned up by hand)
-- ============================================================================

create table if not exists public.brief_slides (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,

  position      integer not null,
  image_path    text not null unique,   -- path in the public `brand` bucket
  caption       text,

  created_at    timestamp with time zone not null default now(),
  updated_at    timestamp with time zone not null default now(),

  constraint brief_slides_position_range check (position between 1 and 12),
  constraint brief_slides_caption_length check (caption is null or char_length(caption) <= 200)
);

create index if not exists brief_slides_tenant_order_idx
  on public.brief_slides (tenant_id, position, created_at);

comment on table public.brief_slides is
  'Ordered still images on the Brief tab (coach front door + client front door). '
  'image_path points into the public brand bucket under <tenant>/brief-slides/. '
  'Marketing-grade content only — never client PII. Count cap of 12 is app/MCP-enforced; '
  'the position range 1..12 is enforced here.';

alter table public.brief_slides enable row level security;

create policy brief_slides_coach_all on public.brief_slides
  for all to authenticated
  using      (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach')
  with check (tenant_id = public.current_tenant_id() and public.current_app_role() = 'coach');

-- Tenant-wide read: every client of this coach sees the same strip.
-- Mirrors coach_videos_member_read / resources_client_read.
create policy brief_slides_member_read on public.brief_slides
  for select to authenticated
  using (tenant_id = public.current_tenant_id());

drop trigger if exists trg_tenant_suspension_guard on public.brief_slides;
create trigger trg_tenant_suspension_guard
  before insert or update or delete on public.brief_slides
  for each row execute function public.enforce_tenant_not_suspended();

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260830190000_brief_slides_integrity.sql =====
-- ============================================================================
-- brief_slides integrity — positions become a database invariant, not an app promise.
--
-- WHY. The 2026-08-30 review of commit d559021 confirmed four related defects in the
-- app-enforced model shipped that morning: (1) delete-then-add manufactures duplicate
-- positions via the clamp-at-12 rule; (2) a swap between two equal positions is a
-- silent no-op, so duplicates are permanently un-reorderable from the UI; (3) the
-- 12-count cap is read-then-insert on every surface, so concurrent adds admit a 13th
-- row; (4) the MCP update tool can write onto an occupied position on demand. All four
-- share one root: position density and the count cap lived in application code that
-- cannot be atomic. This migration moves both invariants into the database while the
-- table is still empty (verified 0 rows in production before writing this).
--
-- THE MODEL AFTER THIS MIGRATION:
--   * INSERT: a BEFORE trigger takes a per-tenant advisory lock, compacts existing
--     positions to dense 1..n, rejects at n >= 12, and ASSIGNS new.position := n+1 —
--     caller-supplied positions on insert are deliberately ignored. No caller can
--     race the cap or create a duplicate.
--   * REORDER: one RPC, set_brief_slide_order(p_ids), renumbers the tenant's full
--     slide set to 1..n atomically in the order given. It requires the FULL set so a
--     partial list can never collide with unlisted rows.
--   * DELETE: leaves a gap (harmless — order is unaffected); the next insert's
--     compaction closes it.
--   * BACKSTOP: a deferrable UNIQUE (tenant_id, position) so any future code path
--     that tries to write a duplicate fails loudly at commit instead of silently
--     rendering by created_at tiebreak.
--
-- The RPC is SECURITY DEFINER (it must renumber rows regardless of the fine-grained
-- RLS evaluation order), so it carries its own authorization: a signed-in caller must
-- be a coach and is pinned to their own tenant (p_tenant is ignored for them); only
-- the service role (the MCP edge function) may name a tenant explicitly. This is the
-- same trust shape as the other definer functions the project notes documents. The tenant
-- suspension guard still applies — it is a row trigger on the table and fires inside
-- the RPC's updates.
--
-- Rollback:
--   drop function if exists public.set_brief_slide_order(uuid[], uuid);
--   drop trigger if exists trg_brief_slides_assign_position on public.brief_slides;
--   drop function if exists public.brief_slides_assign_position();
--   alter table public.brief_slides drop constraint if exists brief_slides_tenant_position_key;
-- ============================================================================

-- Backstop uniqueness. Deferrable so the RPC's single-statement renumber (which
-- transiently passes through duplicate values) is checked once at commit.
alter table public.brief_slides
  add constraint brief_slides_tenant_position_key
  unique (tenant_id, position) deferrable initially deferred;

-- ---------------------------------------------------------------------------
-- INSERT path: compact, enforce the cap, assign the position. The advisory lock
-- serializes concurrent inserts for one tenant without blocking other tenants.
-- Runs as the invoking user: a coach's RLS scope already covers exactly their
-- tenant's rows; the service role sees everything and the tenant_id filter pins it.
-- ---------------------------------------------------------------------------
create or replace function public.brief_slides_assign_position()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_n integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('brief_slides:' || new.tenant_id::text, 0));

  update public.brief_slides s
     set position = x.ord
    from (
      select id, row_number() over (order by position, created_at, id) as ord
        from public.brief_slides
       where tenant_id = new.tenant_id
    ) x
   where s.id = x.id
     and s.position is distinct from x.ord;

  select count(*) into v_n from public.brief_slides where tenant_id = new.tenant_id;
  if v_n >= 12 then
    raise exception 'the strip is full at 12 slides — remove one first';
  end if;

  new.position := v_n + 1;
  return new;
end;
$$;

drop trigger if exists trg_brief_slides_assign_position on public.brief_slides;
create trigger trg_brief_slides_assign_position
  before insert on public.brief_slides
  for each row execute function public.brief_slides_assign_position();

-- ---------------------------------------------------------------------------
-- Atomic reorder. Pass every slide id for the tenant, in the desired order.
-- Returns the number of slides renumbered.
-- ---------------------------------------------------------------------------
create or replace function public.set_brief_slide_order(p_ids uuid[], p_tenant uuid default null)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tenant  uuid;
  v_count   integer;
  v_touched integer;
begin
  if auth.role() = 'service_role' then
    v_tenant := p_tenant;
  else
    if public.current_app_role() is distinct from 'coach' then
      raise exception 'only a coach can reorder slides';
    end if;
    v_tenant := public.current_tenant_id();
  end if;
  if v_tenant is null then
    raise exception 'tenant could not be resolved';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('brief_slides:' || v_tenant::text, 0));

  select count(*) into v_count from public.brief_slides where tenant_id = v_tenant;
  if v_count is distinct from coalesce(array_length(p_ids, 1), 0) then
    raise exception 'pass the full slide order: % slide(s) exist, % id(s) given',
      v_count, coalesce(array_length(p_ids, 1), 0);
  end if;

  update public.brief_slides s
     set position = x.ord,
         updated_at = now()
    from unnest(p_ids) with ordinality as x(id, ord)
   where s.id = x.id
     and s.tenant_id = v_tenant;

  get diagnostics v_touched = row_count;
  if v_touched is distinct from v_count then
    -- A duplicated id, or an id from another tenant: refuse loudly rather than
    -- leave some rows renumbered and others not (the exception rolls it all back).
    raise exception 'slide order rejected: % of % ids matched this tenant''s slides',
      v_touched, v_count;
  end if;
  return v_count;
end;
$$;

comment on function public.set_brief_slide_order(uuid[], uuid) is
  'Atomically renumbers a tenant''s Brief slides to 1..n in the order given. Requires the '
  'full slide set. Coach callers are pinned to their own tenant; only the service role may '
  'pass p_tenant. The deferrable unique constraint is the backstop for any other write path.';

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260831090000_client_schedule_adjustments.sql =====
-- ============================================================================
-- Client schedule adjustments — "swap today's planned day with a later day in
-- this block". Training here is sequence-based, not date-scheduled
-- (current_day_index walks program.structure.days), so "reorder the days" is the
-- only feature this needs — a missed day already slides everything forward with
-- no extra work.
--
-- THE INVARIANT. current_day_index becomes an index into the EFFECTIVE order
-- (assignments.day_order if set, else the program's own structure.days order).
-- Every reader in the app now goes through one shared resolver
-- (src/lib/effectiveDays.js + its Deno twin) instead of indexing
-- program.structure.days directly. This migration only adds the column and the
-- write path; the read-side fix is entirely application code (no schema change
-- needed there).
--
-- WHY A SEPARATE OVERRIDE COLUMN, NOT AN EDIT TO programs.structure: The coach's
-- program and its day_ids anchor workout history (the project notes, decision 4 in the
-- plan) and must never be touched by a client-initiated change. The override
-- lives on the client's own assignment and applies to exactly one block — a
-- fresh cycle (closeDayCore's rollover insert) always starts a new assignment
-- with day_order left null, so nothing carries forward (decision 3).
--
-- WHY A NULLABLE ARRAY, NO BACKFILL: null means "no override — use the program's
-- own order," which is the correct, harmless state of every assignment row that
-- exists today. No existing row needs touching.
--
-- WRITES GO THROUGH adjust_my_schedule() ONLY (SECURITY DEFINER). There is
-- deliberately no direct client INSERT/UPDATE policy on schedule_adjustments and
-- no direct client UPDATE policy on assignments.day_order (the existing
-- assignments RLS already doesn't grant clients UPDATE at all — see
-- src/lib/workouts.js's header: "day advancement goes through the workout-close
-- edge function because clients are SELECT-only on assignments"). The RPC
-- re-derives the CURRENT effective order itself from the database rather than
-- trusting anything the caller claims it was, and independently validates the
-- new order is an exact permutation of the program's day_ids with every
-- position before current_day_index left untouched (decision 5: past days are
-- immutable).
--
-- THE SUSPENSION GUARD IS ATTACHED HERE, EXPLICITLY, for the same reason
-- 20260826190100 / 20260826200000 attach it explicitly: 20260728234500 only
-- looped over tables that existed when it ran, so any new tenant-scoped table
-- must attach trg_tenant_suspension_guard itself or it silently joins the list
-- of tables the 20260824180000 catch-up sweep had to fix later. adjust_my_schedule
-- is SECURITY DEFINER and so bypasses this trigger for its own writes (same
-- exemption every other definer function relies on to keep working under
-- suspension-adjacent conditions) — this is defense-in-depth against any future
-- direct write path, exactly the rationale client_documents.sql gives for doing
-- the same on a table with no direct write path today either.
--
-- Rollback:
--   drop trigger if exists trg_tenant_suspension_guard on public.schedule_adjustments;
--   drop function if exists public.adjust_my_schedule(uuid, uuid[], text, text);
--   drop policy if exists schedule_adjustments_client_read on public.schedule_adjustments;
--   drop policy if exists schedule_adjustments_coach_read on public.schedule_adjustments;
--   drop table if exists public.schedule_adjustments;
--   alter table public.assignments drop column if exists day_order;
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. assignments.day_order — nullable, no default, no backfill.
-- ---------------------------------------------------------------------------
alter table public.assignments
  add column if not exists day_order uuid[];

comment on column public.assignments.day_order is
  'Null (every row today) means "use the program''s own day order." When set, a permutation '
  'of the program''s current structure.days day_ids for THIS assignment only — written only by '
  'adjust_my_schedule(). Resolve through src/lib/effectiveDays.js (or its Deno twin), never by '
  'indexing program.structure.days with current_day_index directly.';

-- ---------------------------------------------------------------------------
-- 2. schedule_adjustments — one row per client-initiated reorder. Event log,
--    not a mutable settings table: never updated after insert.
-- ---------------------------------------------------------------------------
create table if not exists public.schedule_adjustments (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  client_id     uuid not null references public.clients(id) on delete cascade,
  assignment_id uuid not null references public.assignments(id) on delete cascade,

  -- The full effective day-id order immediately before/after this adjustment, as
  -- computed by the RPC from the database — never trusted from caller input for
  -- old_order. jsonb (not uuid[]) so the event log is self-contained and legible
  -- without a join back to a program that may since have changed shape.
  old_order     jsonb not null,
  new_order     jsonb not null,

  -- Optional, structured + free text. NULL means "skipped" and is displayed as
  -- "not given" — a fact about the flow, not about the client (twin-facts rule).
  -- Never defaulted to a plausible-looking value; THE GATE applies.
  reason_tag    text,
  reason_note   text,

  created_at    timestamptz not null default now()
);

create index if not exists schedule_adjustments_client_idx
  on public.schedule_adjustments (tenant_id, client_id, created_at desc);
create index if not exists schedule_adjustments_assignment_idx
  on public.schedule_adjustments (assignment_id, created_at desc);

comment on table public.schedule_adjustments is
  'Event log of client-initiated day-order swaps within their current training block. Written '
  'only by adjust_my_schedule(). reason_tag/reason_note are optional and NULL means the client '
  'skipped the reason prompt, not that no reason exists — render as "not given," never blank or '
  'defaulted.';

alter table public.schedule_adjustments enable row level security;

drop policy if exists schedule_adjustments_coach_read on public.schedule_adjustments;
create policy schedule_adjustments_coach_read on public.schedule_adjustments
  for select to authenticated
  using (
    tenant_id = public.current_tenant_id()
    and public.current_app_role() = 'coach'
  );

drop policy if exists schedule_adjustments_client_read on public.schedule_adjustments;
create policy schedule_adjustments_client_read on public.schedule_adjustments
  for select to authenticated
  using (client_id = public.current_client_id());

-- Deliberately no insert/update/delete policy for `authenticated` at all — every
-- write goes through adjust_my_schedule(), which is SECURITY DEFINER and so does
-- not need one. This is the same shape as submit_checkin()/complete_session()
-- (no direct client insert policy on checkins/workout_sessions for those calls
-- either) applied here for the same reason: the RPC is the only place the
-- validation (ownership, permutation, frozen-past-days) can be enforced
-- atomically against the live row, so it must be the only write path.

drop trigger if exists trg_tenant_suspension_guard on public.schedule_adjustments;
create trigger trg_tenant_suspension_guard
  before insert or update or delete on public.schedule_adjustments
  for each row execute function public.enforce_tenant_not_suspended();

-- ---------------------------------------------------------------------------
-- 3. adjust_my_schedule() — the only write path. Modeled closely on
--    complete_session() / submit_checkin() (migration 20260824190000): same
--    current_client_id()/current_tenant_id() helpers, same tenant_is_suspended
--    check and wording. Modeled on set_brief_slide_order() (20260830190000) for
--    the "full-set permutation, verified by matched row count" technique.
-- ---------------------------------------------------------------------------
create or replace function public.adjust_my_schedule(
  p_assignment_id uuid,
  p_new_order uuid[],
  p_reason_tag text default null,
  p_reason_note text default null
)
returns void
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  cid uuid := public.current_client_id();
  tid uuid := public.current_tenant_id();
  a public.assignments%rowtype;
  v_program_days jsonb;
  v_program_ids uuid[];
  v_old_order uuid[];
  v_program_count integer;
  v_new_count integer;
  v_distinct_count integer;
  i integer;
begin
  if cid is null then
    raise exception 'not a client';
  end if;

  select * into a from public.assignments where id = p_assignment_id;
  if a.id is null or a.client_id is distinct from cid then
    raise exception 'not your assignment';
  end if;
  if not a.active then
    raise exception 'this assignment is no longer active — adjustments only apply to your current block';
  end if;

  if public.tenant_is_suspended(tid) then
    raise exception 'This app is paused: its hosting subscription has lapsed. Existing data stays readable, but new changes are unavailable until it is reactivated.'
      using errcode = '42501';
  end if;

  select structure -> 'days' into v_program_days
    from public.programs where id = a.program_id;
  if v_program_days is null or jsonb_typeof(v_program_days) is distinct from 'array' then
    raise exception 'program has no days to reorder';
  end if;

  select array_agg((d ->> 'day_id')::uuid order by ord)
    into v_program_ids
    from jsonb_array_elements(v_program_days) with ordinality as t(d, ord);

  v_program_count := coalesce(array_length(v_program_ids, 1), 0);
  if v_program_count = 0 then
    raise exception 'program has no days to reorder';
  end if;
  if a.current_day_index < 0 or a.current_day_index > v_program_count then
    raise exception 'assignment day index is out of range for this program';
  end if;

  -- p_new_order must be an EXACT permutation of the program's day_ids: same
  -- length, no duplicates, every id drawn from the program. (Same length +
  -- all-distinct + all-members-of-a-same-size-set together force a bijection —
  -- no separate "every program id is present" check is needed.)
  v_new_count := coalesce(array_length(p_new_order, 1), 0);
  if v_new_count <> v_program_count then
    raise exception 'pass the full day order: % day(s) exist in this program, % given',
      v_program_count, v_new_count;
  end if;

  select count(distinct x) into v_distinct_count from unnest(p_new_order) as x;
  if v_distinct_count <> v_program_count then
    raise exception 'day order must name each of this program''s days exactly once';
  end if;

  if exists (select 1 from unnest(p_new_order) as x where x <> all (v_program_ids)) then
    raise exception 'day order references a day that is not part of this program''s current days';
  end if;

  -- The CURRENT effective order, re-derived from the database (never trusted from
  -- the caller) — same fallback rule as effectiveDays.js: a stale day_order (the
  -- coach edited the program since the last adjustment) is treated as if it were
  -- never set.
  if a.day_order is not null
     and array_length(a.day_order, 1) = v_program_count
     and (select count(distinct x) from unnest(a.day_order) as x) = v_program_count
     and not exists (select 1 from unnest(a.day_order) as x where x <> all (v_program_ids))
  then
    v_old_order := a.day_order;
  else
    v_old_order := v_program_ids;
  end if;

  -- Past days are immutable (decision 5): every position before current_day_index
  -- must be byte-identical between the current effective order and the requested
  -- one. Postgres arrays are 1-indexed; current_day_index is 0-based, so position
  -- k (0-based) is array index k+1 — the loop below covers indices 1..current_day_index,
  -- i.e. every 0-based position strictly before current_day_index.
  if a.current_day_index > 0 then
    for i in 1..a.current_day_index loop
      if v_old_order[i] is distinct from p_new_order[i] then
        raise exception 'day % has already passed and cannot be rearranged', i;
      end if;
    end loop;
  end if;

  insert into public.schedule_adjustments
    (tenant_id, client_id, assignment_id, old_order, new_order, reason_tag, reason_note)
  values (
    tid, cid, a.id,
    to_jsonb(v_old_order), to_jsonb(p_new_order),
    nullif(btrim(p_reason_tag), ''), nullif(btrim(p_reason_note), '')
  );

  update public.assignments
     set day_order = p_new_order, updated_at = now()
   where id = a.id;
end;
$function$;

comment on function public.adjust_my_schedule(uuid, uuid[], text, text) is
  'Client-only. Reorders the remaining days (at/after current_day_index) of the caller''s own '
  'active assignment. Rejects a change to any day at or before current_day_index, and rejects '
  'any order that is not an exact permutation of the program''s current day_ids. Writes exactly '
  'one schedule_adjustments row per call. reason_tag/reason_note pass through as given — NULL '
  'stays NULL, never substituted.';

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260903100000_tenant_config_mode.sql =====
-- tenant_config.mode — the one fact the client app learns about its tenant:
-- coached (a human coach exists; every existing tenant) or self_serve (self-serve plan:
-- no coach, no messaging, no approval gate, connector 'owner' scope permitted).
-- Default 'coached' so no existing tenant changes behaviour. Apply with:
--   supabase db query --linked -f supabase/migrations/20260903100000_tenant_config_mode.sql
alter table public.tenant_config
  add column if not exists mode text not null default 'coached';

alter table public.tenant_config
  drop constraint if exists tenant_config_mode_check;
alter table public.tenant_config
  add constraint tenant_config_mode_check check (mode in ('coached', 'self_serve'));

comment on column public.tenant_config.mode is
  'coached = a human coach runs this tenant (default, every pre-2026-09 tenant). self_serve = self-serve plan: coachless by design; client UI hides coach surfaces; connector owner scope is mintable. Only value the owner-scope trigger trusts.';

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260903101000_meal_plan_assembly_core.sql =====
-- Split assemble_client_meal_plan into a core (pure assembly, no caller-identity check) and
-- two callers: the existing coach wrapper (unchanged behaviour, keeps assert_coach_owns_client)
-- and a new self-serve wrapper for the self-serve plan (asserts tenant_config.mode = 'self_serve'
-- instead — a coach's Release button is not the door for a coachless tenant).
--
-- READ LIVE FIRST (2026-09-02, not from the repo baseline): assemble_client_meal_plan
-- RETURNS JSONB, not uuid — {status: 'ok', plan_id, ...} on success, {status: 'blocked'|
-- 'error', reason, ...} on every refusal (missing body metrics, allergy unreviewed, meal
-- pool too thin, etc — the plan's own Gates A-D). The system wrapper below extracts plan_id
-- on success and re-raises the reason as a real exception on any other status, so a self-serve
-- buyer's refusal surfaces as a named, honest error (THE GATE) instead of a silent no-op.
--
-- client_meal_plans.status CHECK allows only ('draft','assigned','archived') — there is no
-- 'superseded' value. The function itself already uses 'archived' for "no longer current"
-- (its own draft-superseding step: "update ... set status = 'archived' ... where status =
-- 'draft'"), so the self-serve wrapper reuses that same existing convention for the previous
-- 'assigned' plan rather than widening the constraint for a new value that already has one.

-- (1) Core — verbatim body of assemble_client_meal_plan, minus its one caller-identity line
-- (perform public.assert_coach_owns_client(p_client_id);). Never callable directly by anon/
-- authenticated: only the two wrappers below call it, both SECURITY DEFINER.
create or replace function public.assemble_client_meal_plan_core(
  p_client_id uuid,
  p_meals_per_day integer default null::integer,
  p_rotation_days integer default null::integer
)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  c                public.clients%rowtype;
  v_onb_id         uuid;
  v_prep           boolean;
  v_unconfirmed    text[];
  v_unmapped       text[];
  v_diet_unmapped  text[];
  v_diet_advisory  text[];
  v_excluded_tags  text[];
  v_required_tags  text[];
  v_macros         jsonb;
  v_kcal           numeric;
  v_protein        numeric;
  v_fat            numeric;
  v_carb           numeric;
  v_mpd            int;
  v_days           int;
  v_pool_n         int;
  v_badweek_n      int;
  v_plan_id        uuid;
  v_assumptions    text[] := '{}';
  d                int;
  s                int;
  v_slot_id        uuid;
  v_meal           record;
  v_target_kcal    numeric;
  v_prot_ratio     numeric;
  v_delivered_prot numeric;
  v_servings       numeric;
  v_used           uuid[];
  v_slots_made     int := 0;
  v_missing_fb     int := 0;
begin
  select * into c from public.clients where id = p_client_id;
  if not found then return jsonb_build_object('status','error','reason','client_not_found'); end if;

  select id into v_onb_id from public.client_onboarding
   where client_id = p_client_id order by created_at desc limit 1;

  -- Gate A: the lifestyle/prep switch must be stated.
  if c.client_type is null then
    if v_onb_id is not null then perform public.onboarding_add_blocker(v_onb_id,
      'client_type_unstated',
      'Cannot assemble: the client is neither marked lifestyle nor prep. The two produce '
      'different plans (fixed repetition vs rotation with fallbacks); defaulting would be a '
      'guess about how this person trains and eats.', 'block'); end if;
    return jsonb_build_object('status','blocked','reason','client_type_unstated');
  end if;
  v_prep := (c.client_type = 'prep');

  -- Gate B: allergy safety.
  select array_agg(distinct coalesce(nullif(allergen_label,''), allergen_key))
    into v_unconfirmed
    from public.client_allergies
   where client_id = p_client_id and active
     and (needs_review or confidence = 'parsed');

  if v_unconfirmed is not null and array_length(v_unconfirmed,1) > 0 then
    if v_onb_id is not null then perform public.onboarding_add_blocker(v_onb_id,
      'allergy_unreviewed',
      format('Not assembled. These allergies are still machine-parsed from free text and have '
             'not been confirmed with the client: %s. Confirm each one (set confidence to '
             'coach_confirmed or client_confirmed and clear needs_review), then re-run. An '
             'automated meal plan built on a regex-parsed allergy is a safety claim that '
             'cannot be made.', array_to_string(v_unconfirmed, ', ')), 'block'); end if;
    return jsonb_build_object('status','blocked','reason','allergy_unreviewed',
      'allergies', to_jsonb(v_unconfirmed));
  end if;

  select array_agg(distinct ca.allergen_key) into v_unmapped
    from public.client_allergies ca
   where ca.client_id = p_client_id and ca.active
     and not exists (select 1 from public.allergen_tag_crosswalk x
                      where x.allergen_key = ca.allergen_key);

  if v_unmapped is not null and array_length(v_unmapped,1) > 0 then
    if v_onb_id is not null then perform public.onboarding_add_blocker(v_onb_id,
      'allergen_not_representable',
      format('Not assembled. The meal library has never been reviewed for: %s. Every published '
             'meal is marked reviewed against fourteen allergen tags, and these are not among '
             'them — so "no meal is tagged with it" is a fact about the library, not evidence '
             'the food is safe. Build this plan by hand, or review the library for these '
             'allergens and add the crosswalk rows.',
             array_to_string(v_unmapped, ', ')), 'block'); end if;
    return jsonb_build_object('status','blocked','reason','allergen_not_representable',
      'allergen_keys', to_jsonb(v_unmapped));
  end if;

  -- Gate C: dietary restrictions the library cannot express.
  -- Only kinds with real risk if silently ignored still hard-block: a stated
  -- diet ('pattern') or a reported physical reaction ('intolerance'). A plain
  -- dislike or exclusion is not a safety fact, so an unrepresented one is
  -- reported below (post-success, 'review' severity) instead of holding the
  -- whole plan shut over our own cataloguing gap.
  select array_agg(distinct r.restriction_key) into v_diet_unmapped
    from public.client_dietary_restrictions r
   where r.client_id = p_client_id and r.active
     and r.kind in ('pattern','intolerance')
     and not exists (select 1 from public.meal_tags t where t.key = r.restriction_key)
     and not exists (select 1 from public.allergen_tag_crosswalk x where x.allergen_key = r.restriction_key);

  if v_diet_unmapped is not null and array_length(v_diet_unmapped,1) > 0 then
    if v_onb_id is not null then perform public.onboarding_add_blocker(v_onb_id,
      'dietary_restriction_not_representable',
      format('Not assembled. These stated diets or intolerances have no equivalent in the meal '
             'library, so the filter cannot honour them: %s. A plan that quietly ignores a '
             'diet or a reported reaction the client wrote down is worse than no plan. Handle '
             'by hand, or mark the restriction inactive if it no longer applies.',
             array_to_string(v_diet_unmapped, ', ')), 'block'); end if;
    return jsonb_build_object('status','blocked','reason','dietary_restriction_not_representable',
      'restriction_keys', to_jsonb(v_diet_unmapped));
  end if;

  select array_agg(distinct r.restriction_key) into v_diet_advisory
    from public.client_dietary_restrictions r
   where r.client_id = p_client_id and r.active
     and r.kind in ('exclusion','dislike')
     and not exists (select 1 from public.meal_tags t where t.key = r.restriction_key)
     and not exists (select 1 from public.allergen_tag_crosswalk x where x.allergen_key = r.restriction_key);

  -- Gate D: macro targets must rest on real body metrics.
  if c.weight_kg is null or c.height_cm is null or c.age is null or c.sex is null then
    if v_onb_id is not null then perform public.onboarding_add_blocker(v_onb_id,
      'missing_body_metrics',
      format('Not assembled. Macro targets need real numbers and these are empty on the client '
             'record: %s. The existing generator silently substitutes 80 kg / 178 cm / age 30 / '
             'male when they are missing, which produces a calorie target that looks '
             'authoritative and belongs to nobody.',
             concat_ws(', ',
               case when c.weight_kg is null then 'weight' end,
               case when c.height_cm is null then 'height' end,
               case when c.age       is null then 'age' end,
               case when c.sex       is null then 'sex' end)), 'block'); end if;
    return jsonb_build_object('status','blocked','reason','missing_body_metrics');
  end if;

  select pd.macros into v_macros from public.program_drafts pd
   where pd.client_id = p_client_id and pd.macros ? 'calories'
   order by pd.generated_at desc limit 1;

  if v_macros is null then
    if v_onb_id is not null then perform public.onboarding_add_blocker(v_onb_id,
      'no_macro_targets',
      'Not assembled. No program draft with computed macros exists for this client yet, so '
      'there is no calorie or protein target to build the plan against. Generate the program '
      'draft first — the pipeline normally does this before the meal step.', 'block'); end if;
    return jsonb_build_object('status','blocked','reason','no_macro_targets');
  end if;

  v_kcal    := (v_macros->>'calories')::numeric;
  v_protein := (v_macros->>'protein_g')::numeric;
  v_fat     := (v_macros->>'fat_g')::numeric;
  v_carb    := (v_macros->>'carb_g')::numeric;

  v_mpd := p_meals_per_day;
  if v_mpd is null then
    select nullif(regexp_replace(coalesce(kv.value, ''), '\D', '', 'g'), '')::int
      into v_mpd
      from public.intake_submissions sub
      cross join lateral jsonb_each_text(sub.answers) kv
     where sub.client_id = p_client_id
       and (kv.key = 'meals_per_day'
            or lower(kv.key) like '%meal%per%day%'
            or lower(kv.key) like '%how many meals%')
       and coalesce(kv.value,'') ~ '\d'
     order by sub.submitted_at desc limit 1;
  end if;
  if v_mpd is null or v_mpd < 1 or v_mpd > 8 then
    v_mpd := 4;
    v_assumptions := array_append(v_assumptions, 'meals_per_day was not stated on the intake; drafted at 4.'::text);
  end if;

  v_days := coalesce(p_rotation_days, case when v_prep then 1 else 7 end);

  select array_agg(distinct x.tag_key) into v_excluded_tags
    from public.allergen_tag_crosswalk x
   where x.allergen_key in (
     select ca.allergen_key from public.client_allergies ca
      where ca.client_id = p_client_id and ca.active
     union
     select r.restriction_key from public.client_dietary_restrictions r
      where r.client_id = p_client_id and r.active and r.kind in ('exclusion','dislike'));
  v_excluded_tags := coalesce(v_excluded_tags, '{}');

  select array_agg(distinct r.restriction_key) into v_required_tags
    from public.client_dietary_restrictions r
    join public.meal_tags t on t.key = r.restriction_key and t.kind = 'diet'
   where r.client_id = p_client_id and r.active and r.kind = 'pattern';
  v_required_tags := coalesce(v_required_tags, '{}');

  -- ON COMMIT DROP does not fire between two calls inside one transaction.
  drop table if exists _pool;
  create temp table _pool on commit drop as
  select m.id, m.name, m.category, m.kcal, m.protein_g, m.fat_g, m.carb_g,
         m.disruption_floor, m.downgrade_to_meal_id,
         md5(m.id::text || p_client_id::text) as ord
    from public.meals m
   where m.status = 'published'
     and m.macro_state = 'computed'
     and m.allergen_review_state = 'reviewed'
     and (m.tenant_id is null or m.tenant_id = c.tenant_id)
     and (case when v_prep then m.serves_prep else m.serves_lifestyle end)
     and coalesce(m.kcal,0) > 0
     and not exists (
       select 1 from public.meal_tag_map mm join public.meal_tags t on t.id = mm.tag_id
        where mm.meal_id = m.id and t.key = any(v_excluded_tags))
     and not exists (
       select 1 from unnest(v_required_tags) rq
        where not exists (
          select 1 from public.meal_tag_map mm join public.meal_tags t on t.id = mm.tag_id
           where mm.meal_id = m.id and t.key = rq));

  select count(*) into v_pool_n from _pool;
  select count(*) into v_badweek_n from _pool where disruption_floor >= 3;

  if v_pool_n < v_mpd then
    if v_onb_id is not null then perform public.onboarding_add_blocker(v_onb_id,
      'meal_pool_too_thin',
      format('Not assembled. After applying this client''s confirmed allergies and '
             'restrictions, only %s reviewed library meals remain — fewer than the %s meals a '
             'day the plan calls for. This is a gap in the library, not in the client.',
             v_pool_n, v_mpd), 'block'); end if;
    return jsonb_build_object('status','blocked','reason','meal_pool_too_thin',
      'safe_meals', v_pool_n, 'meals_per_day', v_mpd);
  end if;

  update public.client_meal_plans set status = 'archived', updated_at = now()
   where client_id = p_client_id and status = 'draft';

  insert into public.client_meal_plans (
    tenant_id, client_id, title, status, assembly_mode, rotation_days, substitution_policy,
    target_calories, target_protein_g, target_fat_g, target_carb_g, meals_per_day, notes)
  values (c.tenant_id, p_client_id,
    format('%s — %s plan — %s', c.display_name,
           case when v_prep then 'prep' else 'lifestyle' end, to_char(now(),'YYYY-MM-DD')),
    'draft',
    case when v_prep then 'fixed' else 'rotation' end,
    v_days,
    case when v_prep then 'locked' else 'open' end,
    v_kcal, v_protein, v_fat, v_carb, v_mpd,
    case when array_length(v_assumptions,1) > 0
         then 'Drafted assumptions: ' || array_to_string(v_assumptions, ' ') else null end)
  returning id into v_plan_id;

  v_target_kcal := v_kcal / v_mpd;
  -- Servings are scaled to hit calories, so what actually decides whether the
  -- protein target lands is each meal's protein DENSITY, not its absolute grams.
  v_prot_ratio  := v_protein / nullif(v_kcal, 0);

  for d in 0 .. v_days - 1 loop
    v_used := '{}';
    for s in 0 .. v_mpd - 1 loop
      select p.* into v_meal from _pool p
       where p.id <> all(v_used)
         and (s > 0 or p.category = 'breakfast' or v_days = 1)
       order by
         case when s = 0 and p.category = 'breakfast' then 0 else 1 end,
         round(abs((p.protein_g / nullif(p.kcal,0)) - v_prot_ratio) / nullif(v_prot_ratio,0), 2),
         abs(p.kcal - v_target_kcal),
         (p.ord || d::text)
       limit 1;

      if not found then
        select p.* into v_meal from _pool p where p.id <> all(v_used)
         order by round(abs((p.protein_g / nullif(p.kcal,0)) - v_prot_ratio) / nullif(v_prot_ratio,0), 2),
                  abs(p.kcal - v_target_kcal), (p.ord || d::text) limit 1;
      end if;
      exit when not found;

      v_used := v_used || v_meal.id;
      v_servings := round(least(greatest(v_target_kcal / v_meal.kcal, 0.5), 3.0) * 4) / 4.0;

      insert into public.client_meal_plan_slots
        (plan_id, tenant_id, client_id, day_index, slot_index, slot_label, meal_id, servings, is_locked)
      values (v_plan_id, c.tenant_id, p_client_id, d, s,
              case when s = 0 then 'Meal 1' else format('Meal %s', s + 1) end,
              v_meal.id, v_servings, v_prep)
      returning id into v_slot_id;
      v_slots_made := v_slots_made + 1;

      if not v_prep then
        insert into public.client_meal_plan_slot_options (slot_id, tenant_id, client_id, meal_id, position)
        select v_slot_id, c.tenant_id, p_client_id, o.id, row_number() over (order by o.dist)
          from (
            select p.id, abs(p.kcal - v_meal.kcal) as dist
              from _pool p
             where p.id <> v_meal.id
               and p.kcal between v_meal.kcal * 0.75 and v_meal.kcal * 1.25
             order by abs(p.kcal - v_meal.kcal), p.ord limit 2) o;

        insert into public.client_meal_plan_slot_options (slot_id, tenant_id, client_id, meal_id, position)
        select v_slot_id, c.tenant_id, p_client_id, fb.id, 9
          from (
            select coalesce(
                     (select p.id from _pool p
                       where p.id = v_meal.downgrade_to_meal_id and p.disruption_floor >= 3),
                     (select p.id from _pool p
                       where p.disruption_floor >= 3 and p.id <> v_meal.id
                       order by abs(p.kcal - v_meal.kcal), p.ord limit 1)) as id) fb
         where fb.id is not null
           and not exists (select 1 from public.client_meal_plan_slot_options ex
                            where ex.slot_id = v_slot_id and ex.meal_id = fb.id);

        if not exists (
          select 1 from public.client_meal_plan_slot_options op
            join _pool p on p.id = op.meal_id
           where op.slot_id = v_slot_id and p.disruption_floor >= 3)
        then v_missing_fb := v_missing_fb + 1; end if;
      end if;
    end loop;
  end loop;

  -- What the plan actually delivers, per day, against what it promised.
  select round(sum(m.protein_g * sl.servings) / nullif(v_days,0))
    into v_delivered_prot
    from public.client_meal_plan_slots sl join public.meals m on m.id = sl.meal_id
   where sl.plan_id = v_plan_id;

  if v_onb_id is not null and v_delivered_prot is not null
     and v_delivered_prot < v_protein * 0.95 then
    perform public.onboarding_add_blocker(v_onb_id, 'protein_target_not_met',
      format('This plan delivers about %s g protein a day against a %s g target — %s g short. '
             'The library does not contain enough protein-dense meals that survive this client''s '
             'restrictions to reach it. The plan is not wrong; the target is not reachable from the '
             'current pool. Either lower the target or add protein-dense reviewed meals.',
             v_delivered_prot, round(v_protein), round(v_protein - v_delivered_prot)), 'review');
  end if;

  if v_onb_id is not null then
    update public.client_onboarding set meal_plan_id = v_plan_id, updated_at = now()
     where id = v_onb_id;

    -- Everything below is a reason this function previously refused. It just succeeded,
    -- so those reasons are gone; leaving them behind would hold the release gate shut on
    -- a problem that no longer exists.
    perform public.onboarding_clear_blockers(v_onb_id, array[
      'allergy_unreviewed','allergen_not_representable','dietary_restriction_not_representable',
      'missing_body_metrics','no_macro_targets','client_type_unstated','meal_pool_too_thin',
      'meal_assembly_error','no_bad_week_fallback','drafted_assumption','protein_target_not_met',
      'dietary_restriction_gap_reported']);

    if v_diet_advisory is not null and array_length(v_diet_advisory,1) > 0 then
      perform public.onboarding_add_blocker(v_onb_id, 'dietary_restriction_gap_reported',
        format('Assembled, but the meal library cannot yet honour these stated food dislikes or '
               'exclusions, so meals containing them may still appear in this plan: %s. This is a '
               'gap in the library, not the client — review the plan by hand before release, and '
               'add these foods to the library''s vocabulary so future runs filter them '
               'automatically.', array_to_string(v_diet_advisory, ', ')), 'review');
    end if;

    if v_missing_fb > 0 then
      perform public.onboarding_add_blocker(v_onb_id, 'no_bad_week_fallback',
        format('%s of %s slots have no no-kitchen alternate (disruption_floor 3 or 4) that '
               'survives this client''s restrictions. Those slots hold on a good week only. '
               'The library currently has %s reviewed meals at floor 3+ in total.',
               v_missing_fb, v_slots_made, v_badweek_n), 'review');
    end if;

    if array_length(v_assumptions,1) > 0 then
      perform public.onboarding_add_blocker(v_onb_id, 'drafted_assumption',
        array_to_string(v_assumptions, ' '), 'review');
    end if;
  end if;

  return jsonb_build_object(
    'status','ok', 'plan_id', v_plan_id, 'mode', case when v_prep then 'fixed' else 'rotation' end,
    'rotation_days', v_days, 'meals_per_day', v_mpd, 'slots', v_slots_made,
    'safe_pool', v_pool_n, 'bad_week_meals_available', v_badweek_n,
    'slots_without_bad_week_fallback', v_missing_fb,
    'dietary_gaps_reported', to_jsonb(v_diet_advisory),
    'targets', jsonb_build_object('calories', v_kcal, 'protein_g', v_protein,
                                  'fat_g', v_fat, 'carb_g', v_carb),
    'assumptions', to_jsonb(v_assumptions));
end $function$;

comment on function public.assemble_client_meal_plan_core(uuid, integer, integer) is
  'Pure meal-plan assembly — every gate and the insert loop from the original assemble_client_meal_plan, minus its caller-identity check. Never called directly by a client; only assemble_client_meal_plan (coach) and assemble_client_meal_plan_system (the self-serve plan) call it.';

revoke all on function public.assemble_client_meal_plan_core(uuid, integer, integer) from public, anon, authenticated;
grant execute on function public.assemble_client_meal_plan_core(uuid, integer, integer) to service_role;

-- (2) Coach wrapper — same signature and behaviour as before the split, verified by matching
-- the live definition byte-for-byte other than delegating to the core.
create or replace function public.assemble_client_meal_plan(
  p_client_id uuid,
  p_meals_per_day integer default null::integer,
  p_rotation_days integer default null::integer
)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
  perform public.assert_coach_owns_client(p_client_id);
  return public.assemble_client_meal_plan_core(p_client_id, p_meals_per_day, p_rotation_days);
end;
$function$;

comment on function public.assemble_client_meal_plan(uuid, integer, integer) is
  'Coach-facing meal-plan assembly. Delegates to assemble_client_meal_plan_core after asserting the caller coaches this client''s tenant. Split 2026-09 (the self-serve plan) — behaviour for coached tenants is unchanged.';

-- (3) Self-serve wrapper. Service-role only: intake-submit calls it after publishing the
-- program for a client whose tenant is self_serve. Assigns in the same transaction, so a
-- buyer never sits with a program and no nutrition. Refuses for a coached tenant — a coach's
-- Release button remains the only door there. On any non-'ok' status from the core (a real
-- refusal — missing body metrics, allergy unreviewed, meal pool too thin, etc), raises a
-- real exception carrying the reason rather than returning null, so intake-submit's caller
-- sees a named error instead of a silent no-op (THE GATE).
create or replace function public.assemble_client_meal_plan_system(p_client_id uuid)
returns uuid
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_tenant uuid;
  v_mode   text;
  v_result jsonb;
  v_plan   uuid;
begin
  select c.tenant_id into v_tenant from public.clients c where c.id = p_client_id;
  if v_tenant is null then raise exception 'assemble_client_meal_plan_system: client % not found', p_client_id; end if;
  select mode into v_mode from public.tenant_config where tenant_id = v_tenant;
  if v_mode is distinct from 'self_serve' then
    raise exception 'assemble_client_meal_plan_system: tenant is not self_serve (mode=%)', coalesce(v_mode, 'null');
  end if;

  -- The previous assigned plan is archived, not deleted — adherence logs reference it, and
  -- 'archived' is the existing convention this same core function already uses elsewhere
  -- (its own draft-superseding step) rather than a new status value the CHECK doesn't allow.
  update public.client_meal_plans
     set status = 'archived', updated_at = now()
   where client_id = p_client_id and status = 'assigned';

  v_result := public.assemble_client_meal_plan_core(p_client_id, null, null);
  if (v_result->>'status') is distinct from 'ok' then
    raise exception 'assemble_client_meal_plan_system: %', coalesce(v_result->>'reason', 'assembly did not succeed');
  end if;
  v_plan := (v_result->>'plan_id')::uuid;
  -- Defensive: the core's contract always carries plan_id when status='ok'. If that
  -- contract is ever changed without updating this dependency, a bare NULL id would
  -- otherwise match zero rows below and return silently — a false success, exactly the
  -- silent no-op this function exists to avoid (THE GATE). Fail loud instead.
  if v_plan is null then
    raise exception 'assemble_client_meal_plan_system: assembly reported ok but returned no plan_id — core contract violation';
  end if;

  update public.client_meal_plans
     set status = 'assigned', assigned_at = now(), updated_at = now()
   where id = v_plan;

  return v_plan;
end;
$$;

comment on function public.assemble_client_meal_plan_system(uuid) is
  'Self-serve meal-plan assembly + assign, atomic. Refuses (raises) for any tenant whose tenant_config.mode is not self_serve — no coach exists to press Release for such a client, so this is the only door. Called by intake-submit after publish, service-role only.';

revoke all on function public.assemble_client_meal_plan_system(uuid) from public, anon, authenticated;
grant execute on function public.assemble_client_meal_plan_system(uuid) to service_role;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260903102000_mint_my_intake_token.sql =====
-- Re-intake for self-serve buyers: mint a fresh intake_forms token for MY client row, at most
-- once per 28 days. Client-callable; the function does its own authorization — the row it
-- writes is always the caller's own, in a self_serve tenant, or nothing.
create or replace function public.mint_my_intake_token()
returns text
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_client uuid := public.current_client_id();
  v_tenant uuid := public.current_tenant_id();
  v_mode   text;
  v_last   timestamptz;
  v_token  text;
begin
  if v_client is null or v_tenant is null then raise exception 'not_a_client'; end if;
  select mode into v_mode from public.tenant_config where tenant_id = v_tenant;
  if v_mode is distinct from 'self_serve' then raise exception 'not_self_serve'; end if;

  -- Measured from when the buyer SUBMITTED, not when the token was minted (a token can sit
  -- unused for days before submission; created_at would start the 28-day clock too early).
  select max(submitted_at) into v_last
    from public.intake_forms
   where client_id = v_client and status = 'submitted';
  if v_last is not null and v_last > now() - interval '28 days' then
    raise exception 'too_soon:%', to_char(v_last + interval '28 days', 'YYYY-MM-DD');
  end if;

  -- An unused pending token is reused rather than multiplied.
  select token into v_token from public.intake_forms
   where client_id = v_client and status = 'pending' and (expires_at is null or expires_at > now())
   order by created_at desc limit 1;
  if v_token is not null then return v_token; end if;

  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.intake_forms (tenant_id, client_id, token, status, expires_at)
  values (v_tenant, v_client, v_token, 'pending', now() + interval '24 hours');
  return v_token;
end;
$$;

revoke all on function public.mint_my_intake_token() from public, anon;
grant execute on function public.mint_my_intake_token() to authenticated;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260903103000_provision_system_buyer.sql =====
-- Atomic SYSTEM buyer provisioning: clients row + intake_forms token (with the pre-pay
-- health-screen answers pre-filled) in ONE transaction, or nothing. Modelled on
-- provision_licensed_coach (20260824200000): a mid-way failure must never burn a payment.
-- Idempotent on the checkout session id (unique index below). The auth user is created by
-- the calling edge function AFTER this returns (GoTrue is not in this transaction); the
-- existing on_auth_user_confirmed → link_client_by_email links it on first sign-in.
--
-- client_type = 'lifestyle' hardcoded below — confirmed live 2026-09-02 against
-- clients_client_type_ck (CHECK: null or 'lifestyle'/'prep'). SYSTEM buyers are always
-- lifestyle, never prep (there is no coach to run a prep cycle against).
alter table public.clients add column if not exists system_checkout_session_id text;
create unique index if not exists clients_system_checkout_session_key
  on public.clients (system_checkout_session_id) where system_checkout_session_id is not null;

create or replace function public.provision_system_buyer(p_email text, p_session_id text, p_parq jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_tenant uuid;
  v_client uuid;
  v_token  text;
  v_email  text := lower(trim(p_email));
begin
  if v_email is null or v_email = '' or position('@' in v_email) = 0 then
    raise exception 'provision_system_buyer: email required';
  end if;
  if p_session_id is null or p_session_id = '' then
    raise exception 'provision_system_buyer: session id required';
  end if;

  select t.id into v_tenant from public.tenants t join public.tenant_config c on c.tenant_id = t.id
   where t.slug = 'self-serve' and c.mode = 'self_serve';
  if v_tenant is null then raise exception 'provision_system_buyer: self-serve tenant missing or not self_serve'; end if;

  -- Idempotency: this payment already produced a client.
  select id into v_client from public.clients where system_checkout_session_id = p_session_id;
  if v_client is not null then
    select token into v_token from public.intake_forms
     where client_id = v_client order by created_at desc limit 1;
    return jsonb_build_object('client_id', v_client, 'intake_token', v_token, 'already_provisioned', true);
  end if;

  -- One SYSTEM client per email inside the system tenant. A second purchase by the same
  -- email attaches to the same client rather than creating a twin (Stripe refund is the platform owner's).
  select id into v_client from public.clients
   where tenant_id = v_tenant and lower(email) = v_email limit 1;
  if v_client is null then
    insert into public.clients (tenant_id, display_name, email, status, client_type, system_checkout_session_id)
    values (v_tenant, split_part(v_email, '@', 1), v_email, 'invited', 'lifestyle', p_session_id)
    returning id into v_client;
  else
    update public.clients set system_checkout_session_id = p_session_id, updated_at = now() where id = v_client;
  end if;

  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.intake_forms (tenant_id, client_id, token, status, expires_at, answers)
  values (v_tenant, v_client, v_token, 'pending', now() + interval '14 days', coalesce(p_parq, '{}'::jsonb));

  return jsonb_build_object('client_id', v_client, 'intake_token', v_token, 'already_provisioned', false);
end;
$$;

revoke all on function public.provision_system_buyer(text, text, jsonb) from public, anon, authenticated;
grant execute on function public.provision_system_buyer(text, text, jsonb) to service_role;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

