-- ===== migration 20260904000000_list_system_buyers.sql =====
-- Phase 4, part A.
-- Who bought the self-serve plan, for the platform owner only. SYSTEM buyers live in self-serve
-- tenants that no coach can read under RLS, so this is a SECURITY DEFINER reader gated on
-- the caller being a coach of the tenant whose slug is 'owner' (the same rule as the MCP's
-- requireOwnerTenant), or the service role (the MCP tool, which applies that rule itself).
-- Any other caller gets an exception, never an empty list — "no rows" must mean "no buyers".
--
-- Every column is derived from existing tables; nothing is estimated. Booleans are real
-- yes/no facts (a row exists or it does not). last_seen_at is the latest of: an AI
-- connection being used, an intake being submitted, the client row being updated — named
-- so it is not mistaken for app opens, which are not tracked.
create or replace function public.list_system_buyers()
returns table (
  client_id uuid,
  tenant_id uuid,
  app_name text,
  display_name text,
  email_masked text,
  status text,
  joined_at timestamptz,
  intake_status text,
  intake_submitted_at timestamptz,
  program_published boolean,
  meal_plan_assigned boolean,
  ai_connected boolean,
  ai_scope text,
  last_seen_at timestamptz
)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
begin
  if not (
    coalesce(auth.role(), '') = 'service_role'
    or exists (
      select 1 from public.profiles p
      join public.tenants t on t.id = p.tenant_id
      where p.user_id = auth.uid() and p.role = 'coach' and t.slug = 'owner'
    )
  ) then
    raise exception 'list_system_buyers is restricted to the platform owner' using errcode = '42501';
  end if;

  return query
  select
    c.id,
    c.tenant_id,
    tc.app_name,
    c.display_name,
    case when c.email is null then null
         else left(split_part(c.email, '@', 1), 2) || '…@' || split_part(c.email, '@', 2) end,
    c.status::text,
    c.joined_at,
    coalesce(li.status, 'none'),
    li.submitted_at,
    exists (select 1 from public.assignments a where a.client_id = c.id and a.active),
    exists (select 1 from public.client_meal_plans m where m.client_id = c.id and m.status = 'assigned'),
    exists (select 1 from public.connector_tokens k where k.client_id = c.id and k.kind = 'client' and k.revoked_at is null),
    (select max(k.scope) from public.connector_tokens k where k.client_id = c.id and k.kind = 'client' and k.revoked_at is null),
    greatest(
      (select max(k.last_used_at) from public.connector_tokens k where k.client_id = c.id),
      li.submitted_at,
      c.updated_at
    )
  from public.clients c
  join public.tenant_config tc on tc.tenant_id = c.tenant_id and tc.mode = 'self_serve'
  left join lateral (
    select f.status::text as status, f.submitted_at
      from public.intake_forms f
     where f.client_id = c.id
     order by f.submitted_at desc nulls last, f.created_at desc
     limit 1
  ) li on true
  where c.status <> 'archived'
  order by c.joined_at desc nulls last;
end;
$$;

revoke all on function public.list_system_buyers() from public, anon;
grant execute on function public.list_system_buyers() to authenticated, service_role;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260904100000_client_origin_and_system_conversion.sql =====
-- Phase 4 parts B and C (plan + 2026-09-04 amendment:
-- the original design notes (not included)).
--
-- 1. clients.origin — where a client record came from. NULL means "before this column
--    existed / not tracked" and is displayed as nothing, never as a guess (twin-facts rule).
-- 2. clients.converted_from_client_id — the SYSTEM buyer row a coaching client was moved
--    from. One direction only; the buyer row is untouched apart from losing its login.
-- 3. Writers stamp origin: provision_system_buyer → 'system', create_coach_client →
--    'coach_invite'. (trainerize-import stamps 'trainerize_import' from the edge function.)
-- 4. convert_system_buyer_to_coaching(): the only cross-tenant write in the app. Moves a
--    signed-in SYSTEM buyer's login onto a new row on the owner tenant's roster. Refuses
--    anyone who is not an owner-tenant coach, a buyer who never signed in, a duplicate email on
--    the roster, and a second move.
-- 5. list_system_buyers() v2 — adds has_account, converted_client_id, converted_at. Return
--    type changes, so it is dropped and recreated (grants re-applied below).

-- ── 1–2. Columns ─────────────────────────────────────────────────────────────────────
alter table public.clients
  add column if not exists origin text null;
alter table public.clients
  drop constraint if exists clients_origin_ck;
alter table public.clients
  add constraint clients_origin_ck
  check (origin is null or origin in ('system', 'coach_invite', 'trainerize_import'));
comment on column public.clients.origin is
  'How this client record came to exist: system (bought the self-serve plan), coach_invite (coach added them), trainerize_import. NULL = created before 2026-09-04, not tracked — display nothing, never infer.';

alter table public.clients
  add column if not exists converted_from_client_id uuid null references public.clients(id) on delete set null;
create index if not exists clients_converted_from_idx
  on public.clients (converted_from_client_id) where converted_from_client_id is not null;
comment on column public.clients.converted_from_client_id is
  'Set on a coaching client that was moved from a self-serve buyer row by convert_system_buyer_to_coaching(). Points at the buyer row, which keeps its history.';

-- ── 3a. provision_system_buyer stamps origin = system ────────────────────────────────
create or replace function public.provision_system_buyer(p_email text, p_session_id text, p_parq jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_tenant uuid;
  v_client uuid;
  v_token  text;
  v_email  text := lower(trim(p_email));
begin
  if v_email is null or v_email = '' or position('@' in v_email) = 0 then
    raise exception 'provision_system_buyer: email required';
  end if;
  if p_session_id is null or p_session_id = '' then
    raise exception 'provision_system_buyer: session id required';
  end if;

  select t.id into v_tenant from public.tenants t join public.tenant_config c on c.tenant_id = t.id
   where t.slug = 'self-serve' and c.mode = 'self_serve';
  if v_tenant is null then raise exception 'provision_system_buyer: self-serve tenant missing or not self_serve'; end if;

  -- Idempotency: this payment already produced a client.
  select id into v_client from public.clients where system_checkout_session_id = p_session_id;
  if v_client is not null then
    select token into v_token from public.intake_forms
     where client_id = v_client order by created_at desc limit 1;
    return jsonb_build_object('client_id', v_client, 'intake_token', v_token, 'already_provisioned', true);
  end if;

  -- One SYSTEM client per email inside the system tenant. A second purchase by the same
  -- email attaches to the same client rather than creating a twin (Stripe refund is the platform owner's).
  select id into v_client from public.clients
   where tenant_id = v_tenant and lower(email) = v_email limit 1;
  if v_client is null then
    insert into public.clients (tenant_id, display_name, email, status, client_type, system_checkout_session_id, origin)
    values (v_tenant, split_part(v_email, '@', 1), v_email, 'invited', 'lifestyle', p_session_id, 'system')
    returning id into v_client;
  else
    update public.clients set system_checkout_session_id = p_session_id, updated_at = now() where id = v_client;
  end if;

  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.intake_forms (tenant_id, client_id, token, status, expires_at, answers)
  values (v_tenant, v_client, v_token, 'pending', now() + interval '14 days', coalesce(p_parq, '{}'::jsonb));

  return jsonb_build_object('client_id', v_client, 'intake_token', v_token, 'already_provisioned', false);
end;
$$;

-- Existing SYSTEM buyers are a known fact (system_checkout_session_id is set only by the
-- SYSTEM path), so backfilling them is not an inference.
update public.clients set origin = 'system'
 where origin is null and system_checkout_session_id is not null;

-- ── 3b. create_coach_client stamps origin = coach_invite ─────────────────────────────
create or replace function public.create_coach_client(
  p_display_name text,
  p_email text default null,
  p_coaching_tier text default null,
  p_status text default 'invited',
  p_client_type text default null,
  p_show_date date default null,
  p_show_name text default null
)
returns public.clients
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me public.profiles;
  rec public.clients;
  cleaned_name text := trim(coalesce(p_display_name, ''));
  cleaned_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
  cleaned_type text := nullif(trim(coalesce(p_client_type, '')), '');
  st text := coalesce(nullif(trim(coalesce(p_status, '')), ''), 'invited');
begin
  select * into me from public.profiles where user_id = auth.uid();
  if me.user_id is null or me.role is distinct from 'coach' then
    raise exception 'Only a coach can add a client.';
  end if;
  if me.tenant_id is null then
    raise exception 'Your coaching session has no tenant. Sign out and sign back in.';
  end if;
  if cleaned_name = '' then
    raise exception 'Name is required.';
  end if;
  if cleaned_type is not null and cleaned_type not in ('lifestyle', 'prep') then
    raise exception 'Client type must be lifestyle, prep, or unset.';
  end if;
  if cleaned_email is not null and exists (
    select 1 from public.clients c
    where c.tenant_id = me.tenant_id and lower(c.email) = cleaned_email
  ) then
    raise exception 'A client with that email already exists.';
  end if;

  insert into public.clients (
    tenant_id, display_name, email, coaching_tier, status,
    client_type, show_date, show_name, origin
  ) values (
    me.tenant_id,
    cleaned_name,
    cleaned_email,
    nullif(trim(coalesce(p_coaching_tier, '')), ''),
    st::public.client_status,
    cleaned_type,
    case when cleaned_type = 'prep' then p_show_date else null end,
    case when cleaned_type = 'prep' then nullif(trim(coalesce(p_show_name, '')), '') else null end,
    'coach_invite'
  )
  returning * into rec;
  return rec;
end;
$$;

-- ── 4. Move a SYSTEM buyer to coaching ───────────────────────────────────────────────
create or replace function public.convert_system_buyer_to_coaching(p_buyer_client_id uuid)
returns uuid
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  me        public.profiles;
  v_slug    text;
  buyer     public.clients;
  v_mode    text;
  v_new     uuid;
begin
  -- Caller: a coach whose tenant is the platform owner (slug 'owner'). Service role is
  -- deliberately not accepted — this is the platform owner's finger on a button, not an agent's.
  select * into me from public.profiles where user_id = auth.uid();
  if me.user_id is null or me.role is distinct from 'coach' then
    raise exception 'Only a coach can move a buyer to coaching.' using errcode = '42501';
  end if;
  select slug into v_slug from public.tenants where id = me.tenant_id;
  if v_slug is distinct from 'owner' then
    raise exception 'Moving SYSTEM buyers is restricted to the platform owner.' using errcode = '42501';
  end if;

  select * into buyer from public.clients where id = p_buyer_client_id;
  if buyer.id is null then
    raise exception 'Buyer not found.';
  end if;
  select mode into v_mode from public.tenant_config where tenant_id = buyer.tenant_id;
  if v_mode is distinct from 'self_serve' then
    raise exception 'That client is not a SYSTEM buyer.';
  end if;
  if buyer.client_user_id is null then
    raise exception 'This buyer has never signed in to SYSTEM, so there is no login to move. Add them as a client and send an invite instead.';
  end if;
  if exists (select 1 from public.clients where converted_from_client_id = buyer.id) then
    raise exception 'This buyer has already been moved to coaching.';
  end if;
  if buyer.email is not null and exists (
    select 1 from public.clients c where c.tenant_id = me.tenant_id and lower(c.email) = lower(buyer.email)
  ) then
    raise exception 'A client with that email already exists on your roster.';
  end if;
  if public.tenant_is_suspended(me.tenant_id) then
    raise exception 'Your app is paused; reactivate billing before adding clients.' using errcode = '42501';
  end if;

  -- The coaching row. Body metrics and units copied as facts the buyer entered; client_type
  -- left null — SYSTEM hardcodes lifestyle, which is not a coach's classification.
  insert into public.clients (
    tenant_id, display_name, email, status, origin, converted_from_client_id,
    sex, age, height_cm, weight_kg, goal_weight_kg, height_in, weight_lb, goal_weight_lb,
    activity_level, body_fat_pct, unit_pref
  ) values (
    me.tenant_id, buyer.display_name, buyer.email, 'active', 'system', buyer.id,
    buyer.sex, buyer.age, buyer.height_cm, buyer.weight_kg, buyer.goal_weight_kg, buyer.height_in, buyer.weight_lb, buyer.goal_weight_lb,
    buyer.activity_level, buyer.body_fat_pct, buyer.unit_pref
  ) returning id into v_new;

  -- Move the login. Order matters: clients_user_unique allows one row per user.
  update public.clients set client_user_id = null, updated_at = now() where id = buyer.id;
  update public.clients set client_user_id = buyer.client_user_id, updated_at = now() where id = v_new;
  update public.profiles set tenant_id = me.tenant_id where user_id = buyer.client_user_id and role = 'client';

  -- AI tokens were scoped to the buyer row (and owner scope cannot exist on a coached
  -- tenant). Revoke; the client reconnects from the coaching app if they want to.
  update public.connector_tokens set revoked_at = now()
   where client_id = buyer.id and revoked_at is null;

  return v_new;
end;
$$;

revoke all on function public.convert_system_buyer_to_coaching(uuid) from public, anon;
grant execute on function public.convert_system_buyer_to_coaching(uuid) to authenticated;
comment on function public.convert_system_buyer_to_coaching(uuid) is
  'Platform owner only. Creates a coaching row (origin=system, converted_from_client_id) on the caller''s roster, moves the buyer''s login to it, re-points profiles.tenant_id, revokes the buyer''s AI tokens. Buyer row keeps its history. Refuses a never-signed-in buyer.';

-- ── 5. list_system_buyers v2 ─────────────────────────────────────────────────────────
drop function if exists public.list_system_buyers();
create function public.list_system_buyers()
returns table (
  client_id uuid,
  tenant_id uuid,
  app_name text,
  display_name text,
  email_masked text,
  status text,
  joined_at timestamptz,
  intake_status text,
  intake_submitted_at timestamptz,
  program_published boolean,
  meal_plan_assigned boolean,
  ai_connected boolean,
  ai_scope text,
  last_seen_at timestamptz,
  has_account boolean,
  converted_client_id uuid,
  converted_at timestamptz
)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
begin
  if not (
    coalesce(auth.role(), '') = 'service_role'
    or exists (
      select 1 from public.profiles p
      join public.tenants t on t.id = p.tenant_id
      where p.user_id = auth.uid() and p.role = 'coach' and t.slug = 'owner'
    )
  ) then
    raise exception 'list_system_buyers is restricted to the platform owner' using errcode = '42501';
  end if;

  return query
  select
    c.id,
    c.tenant_id,
    tc.app_name,
    c.display_name,
    case when c.email is null then null
         else left(split_part(c.email, '@', 1), 2) || '…@' || split_part(c.email, '@', 2) end,
    c.status::text,
    c.joined_at,
    coalesce(li.status, 'none'),
    li.submitted_at,
    exists (select 1 from public.assignments a where a.client_id = c.id and a.active),
    exists (select 1 from public.client_meal_plans m where m.client_id = c.id and m.status = 'assigned'),
    exists (select 1 from public.connector_tokens k where k.client_id = c.id and k.kind = 'client' and k.revoked_at is null),
    (select max(k.scope) from public.connector_tokens k where k.client_id = c.id and k.kind = 'client' and k.revoked_at is null),
    greatest(
      (select max(k.last_used_at) from public.connector_tokens k where k.client_id = c.id),
      li.submitted_at,
      c.updated_at
    ),
    -- has_account: they signed in at least once (login on this row, or moved with them).
    (c.client_user_id is not null or conv.id is not null),
    conv.id,
    conv.joined_at
  from public.clients c
  join public.tenant_config tc on tc.tenant_id = c.tenant_id and tc.mode = 'self_serve'
  left join lateral (
    select f.status::text as status, f.submitted_at
      from public.intake_forms f
     where f.client_id = c.id
     order by f.submitted_at desc nulls last, f.created_at desc
     limit 1
  ) li on true
  left join lateral (
    select k.id, k.joined_at from public.clients k
     where k.converted_from_client_id = c.id
     order by k.joined_at desc limit 1
  ) conv on true
  where c.status <> 'archived'
  order by c.joined_at desc nulls last;
end;
$$;

revoke all on function public.list_system_buyers() from public, anon;
grant execute on function public.list_system_buyers() to authenticated, service_role;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260904110000_connector_coach_tokens_read_only.sql =====
-- Coach-minted connector tokens are read-only by policy, not just by UI.
--
-- Finding (2026-09-03, standing state): the migration safety.test.ts describes,
-- 20260819034500_connector_read_only.sql, was never committed. Live pg_policies showed
-- ct_coach_all — a coach could insert a read_write token with a hand-made REST call against
-- their own tenant. The app stopped offering coach write tokens on 2026-08-19; this closes
-- the database side. safety.test.ts now points at this file.
--
-- What changes: the single ct_coach_all policy becomes four. SELECT / UPDATE / DELETE keep
-- the exact same predicate (tenant match + coach role). INSERT additionally requires
-- kind = 'coach', scope = 'read', created_by = the caller. A BEFORE trigger adds two
-- guarantees the policy cannot: immutability of a token's identity columns after creation,
-- and no un-revoking.
--
-- What does not change: Existing read_write rows may be revoked and keep working until
-- they are (20 live today; canUseTool still gates writes on that scope). Client-minted
-- tokens (ct_client_insert, owner_scope migration) are untouched. The connector sign-in
-- page mints through the service role, which bypasses RLS and is unaffected. The MCP's
-- last_used_at touch (service role, UPDATE) is allowed by the trigger.

-- ── 1. Policies ──────────────────────────────────────────────────────────────────────
drop policy if exists ct_coach_all on public.connector_tokens;

create policy ct_coach_select on public.connector_tokens
  for select to public
  using (tenant_id = current_tenant_id() and current_app_role() = 'coach');

create policy ct_coach_insert on public.connector_tokens
  for insert to public
  with check (
    tenant_id = current_tenant_id()
    and current_app_role() = 'coach'
    and kind = 'coach'
    and scope = 'read'
    and created_by = auth.uid()
  );

create policy ct_coach_update on public.connector_tokens
  for update to public
  using (tenant_id = current_tenant_id() and current_app_role() = 'coach')
  with check (tenant_id = current_tenant_id() and current_app_role() = 'coach');

create policy ct_coach_delete on public.connector_tokens
  for delete to public
  using (tenant_id = current_tenant_id() and current_app_role() = 'coach');

-- ── 2. Trigger: no write-scope coach inserts from the browser; identity immutable ────
create or replace function public.connector_tokens_guard()
returns trigger
language plpgsql
security invoker
set search_path to 'public'
as $$
begin
  if TG_OP = 'INSERT' then
    -- Belt to the policy's braces: a coach session may only create read tokens. Service
    -- role and the DB owner (SECURITY DEFINER bodies) pass — they mint client tokens.
    if current_user in ('authenticated', 'anon')
       and public.current_app_role() = 'coach'
       and new.scope is distinct from 'read' then
      raise exception 'Coach tokens are read-only. Write scope is not available.' using errcode = '42501';
    end if;
    return new;
  end if;

  -- UPDATE: a token's identity never changes after creation. Only label, last_used_at and
  -- revoked_at may move.
  if new.id is distinct from old.id
     or new.tenant_id is distinct from old.tenant_id
     or new.created_by is distinct from old.created_by
     or new.kind is distinct from old.kind
     or new.scope is distinct from old.scope
     or new.client_id is distinct from old.client_id
     or new.token_hash is distinct from old.token_hash
     or new.created_at is distinct from old.created_at then
    raise exception 'connector token identity is immutable' using errcode = '42501';
  end if;
  -- A revoked token stays revoked.
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'a revoked connector token cannot be reactivated' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_connector_tokens_guard on public.connector_tokens;
create trigger trg_connector_tokens_guard
  before insert or update on public.connector_tokens
  for each row execute function public.connector_tokens_guard();

comment on function public.connector_tokens_guard() is
  'BEFORE INSERT/UPDATE on connector_tokens. Insert: a coach session (authenticated + coach role) may only create scope=read. Update: id/tenant_id/created_by/kind/scope/client_id/token_hash/created_at are immutable; revoked_at cannot be cleared. Existing read_write rows may be revoked; nothing else about them changes.';

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260904200000_coach_push_subscriptions.sql =====
-- Coach-side Web Push (2026-09-04, the platform owner: "I need notifications button on my ui").
--
-- Clients have had push since P4 (clients.push_subscription + send-nudge). Coaches had
-- nowhere to store a subscription and nothing that would ever send them one. This adds:
--   1. coach_push_subscriptions — one row per (coach, device). RLS: a coach manages only
--      their own rows inside their own tenant. Nobody else can read an endpoint.
--   2. A trigger on the two client events a coach actually wants a buzz for — a client
--      message and a submitted check-in — that asks the notify-coach edge function to
--      send. The DB cannot do Web Push itself (VAPID signing lives with the function).
--
-- Transport: pg_net (async; the client's write never waits on the push) with the same
-- vault bearer the pg_cron jobs already use ('cron_reconcile_bearer'); notify-coach
-- checks it as CRON_SECRET exactly like license-reconcile. No new secret anywhere.
-- Failure posture: the trigger swallows every error — a notification must never fail
-- the client's message or check-in.

create table if not exists public.coach_push_subscriptions (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  user_id       uuid not null references auth.users(id) on delete cascade,
  endpoint      text not null,
  subscription  jsonb not null,
  label         text,
  created_at    timestamptz not null default now(),
  last_used_at  timestamptz,
  revoked_at    timestamptz,
  unique (user_id, endpoint)
);

create index if not exists coach_push_subscriptions_tenant_live
  on public.coach_push_subscriptions (tenant_id) where revoked_at is null;

alter table public.coach_push_subscriptions enable row level security;

drop policy if exists cps_own_select on public.coach_push_subscriptions;
create policy cps_own_select on public.coach_push_subscriptions
  for select to public
  using (user_id = auth.uid() and tenant_id = current_tenant_id() and current_app_role() = 'coach');

drop policy if exists cps_own_insert on public.coach_push_subscriptions;
create policy cps_own_insert on public.coach_push_subscriptions
  for insert to public
  with check (user_id = auth.uid() and tenant_id = current_tenant_id() and current_app_role() = 'coach');

drop policy if exists cps_own_update on public.coach_push_subscriptions;
create policy cps_own_update on public.coach_push_subscriptions
  for update to public
  using (user_id = auth.uid() and tenant_id = current_tenant_id() and current_app_role() = 'coach')
  with check (user_id = auth.uid() and tenant_id = current_tenant_id() and current_app_role() = 'coach');

drop policy if exists cps_own_delete on public.coach_push_subscriptions;
create policy cps_own_delete on public.coach_push_subscriptions
  for delete to public
  using (user_id = auth.uid() and tenant_id = current_tenant_id() and current_app_role() = 'coach');

-- ---------------------------------------------------------------------------------
-- Trigger: client event → notify-coach (pg_net, vault bearer). SECURITY DEFINER so it
-- can read the vault and call net.* on behalf of a plain authenticated insert.
-- ---------------------------------------------------------------------------------
create or replace function public.notify_coach_of_client_event()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_kind   text;
  v_secret text;
  v_url    text;
begin
  if tg_table_name = 'messages' then
    if new.sender_role::text <> 'client' then
      return new;                       -- coach → client messages are not events for the coach
    end if;
    v_kind := 'message';
  elsif tg_table_name = 'checkins' then
    v_kind := 'checkin';
  else
    return new;
  end if;

  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = 'cron_reconcile_bearer'
   limit 1;
  if v_secret is null then
    return new;                         -- no bearer, no call; never block the write
  end if;

  select decrypted_secret into v_url
    from vault.decrypted_secrets
   where name = 'project_url'
   limit 1;
  if v_url is null then
    return new;                         -- project URL not configured; never block the write
  end if;

  perform net.http_post(
    url     := v_url || '/functions/v1/notify-coach',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_secret
    ),
    body    := jsonb_build_object(
      'kind',      v_kind,
      'tenant_id', new.tenant_id,
      'client_id', new.client_id,
      'row_id',    new.id
    )
  );
  return new;
exception when others then
  return new;                           -- a notification must never fail the client's write
end
$$;

revoke all on function public.notify_coach_of_client_event() from public;

drop trigger if exists trg_notify_coach_message on public.messages;
create trigger trg_notify_coach_message
  after insert on public.messages
  for each row execute function public.notify_coach_of_client_event();

drop trigger if exists trg_notify_coach_checkin on public.checkins;
create trigger trg_notify_coach_checkin
  after insert on public.checkins
  for each row execute function public.notify_coach_of_client_event();

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260905210000_revoke_anon_execute_on_mutators.sql =====
-- Pentest F3 (2026-09-05). Remove the anon EXECUTE grant from four coach/client
-- mutator RPCs. Each already refuses an anonymous caller (they require
-- auth.uid() / current_client_id(), which is null for anon), none is referenced by
-- any RLS policy (verified against pg_policies), and no pre-login flow calls them.
-- So this removes unnecessary attack surface with zero behavior change, and is
-- reversible by re-granting. The legitimately-anon helpers used inside RLS
-- (current_tenant_id, current_app_role, tenant_is_suspended, get_app_config) and
-- the trigger functions are deliberately left untouched.
revoke execute on function public.create_coach_client(text, text, text, text, text, date, text) from anon;
revoke execute on function public.send_coach_message(uuid, text) from anon;
revoke execute on function public.adjust_my_schedule(uuid, uuid[], text, text) from anon;
revoke execute on function public.set_brief_slide_order(uuid[], uuid) from anon;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260906120000_coaching_provision.sql =====
-- Slice 0 of the original design notes (not included) — paid → intake link, automatic.
--
-- 1. clients.stripe_checkout_session_id — the owner-tenant coaching Checkout Session that created
--    or attached this client. Unique where set: one payment provisions once, however many
--    times the /welcome page or the webhook replays it. Separate from
--    system_checkout_session_id on purpose (different product, different tenant).
-- 2. origin gains 'stripe_coaching' (a coaching client created by an owner-tenant payment).
-- 3. provision_coaching_client(): the twin of provision_system_buyer for the owner tenant.
--    Service-role only — called by coaching-provision and stripe-webhook, never a browser.
--    Matches an existing owner-tenant client by email (two matches → refuses, 'ambiguous', same
--    rule as intake_match_or_create_client), otherwise inserts an invited client with the
--    tier from the price map; mints a 14-day intake token either way.

alter table public.clients
  add column if not exists stripe_checkout_session_id text;
create unique index if not exists clients_stripe_checkout_session_uidx
  on public.clients (stripe_checkout_session_id) where stripe_checkout_session_id is not null;
comment on column public.clients.stripe_checkout_session_id is
  'Owner-tenant coaching Checkout Session (cs_…) that provisioned or attached this client. NULL = paid outside this path or before 2026-09-06 — not tracked, never inferred.';

alter table public.clients drop constraint if exists clients_origin_ck;
alter table public.clients
  add constraint clients_origin_ck
  check (origin is null or origin in ('system', 'coach_invite', 'trainerize_import', 'stripe_coaching'));

create or replace function public.provision_coaching_client(p_email text, p_session_id text, p_tier text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_tenant  uuid;
  v_client  uuid;
  v_token   text;
  v_matches int;
  v_email   text := lower(trim(p_email));
begin
  if v_email is null or v_email = '' or position('@' in v_email) = 0 then
    raise exception 'provision_coaching_client: email required';
  end if;
  if p_session_id is null or p_session_id = '' then
    raise exception 'provision_coaching_client: session id required';
  end if;
  if p_tier is null or p_tier not in ('entry', 'standard') then
    raise exception 'provision_coaching_client: tier must be entry or standard, got %', coalesce(p_tier, 'null');
  end if;

  select id into v_tenant from public.tenants where slug = 'owner';
  if v_tenant is null then raise exception 'provision_coaching_client: owner tenant missing'; end if;

  -- Idempotency: this payment already produced or attached a client.
  select id into v_client from public.clients where stripe_checkout_session_id = p_session_id;
  if v_client is not null then
    select token into v_token from public.intake_forms
     where client_id = v_client order by created_at desc limit 1;
    return jsonb_build_object('client_id', v_client, 'intake_token', v_token, 'outcome', 'existed');
  end if;

  select count(*) into v_matches from public.clients
   where tenant_id = v_tenant and lower(trim(email)) = v_email;
  if v_matches > 1 then
    return jsonb_build_object('outcome', 'ambiguous', 'matches', v_matches,
      'detail', format('%s owner-tenant client records share this email; which one paid is not knowable from the data. Merge the duplicates, then attach the session by hand.', v_matches));
  end if;

  if v_matches = 1 then
    select id into v_client from public.clients
     where tenant_id = v_tenant and lower(trim(email)) = v_email;
    update public.clients
       set stripe_checkout_session_id = p_session_id,
           coaching_tier = coalesce(coaching_tier, p_tier),
           status = case when status = 'archived' then 'invited' else status end,
           updated_at = now()
     where id = v_client;
  else
    insert into public.clients (tenant_id, display_name, email, status, coaching_tier, stripe_checkout_session_id, origin)
    values (v_tenant, split_part(v_email, '@', 1), v_email, 'invited', p_tier, p_session_id, 'stripe_coaching')
    returning id into v_client;
  end if;

  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.intake_forms (tenant_id, client_id, token, status, expires_at)
  values (v_tenant, v_client, v_token, 'pending', now() + interval '14 days');

  return jsonb_build_object('client_id', v_client, 'intake_token', v_token,
    'outcome', case when v_matches = 1 then 'attached' else 'created' end);
end;
$$;

revoke all on function public.provision_coaching_client(text, text, text) from public, anon, authenticated;
grant execute on function public.provision_coaching_client(text, text, text) to service_role;
comment on function public.provision_coaching_client(text, text, text) is
  'Service role only. Provisions or attaches an owner-tenant coaching client from a paid Checkout Session and mints a 14-day intake token. Idempotent on session id; refuses an ambiguous email match.';

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260906130000_canonical_food_keys_security_invoker.sql =====
-- Supabase security advisor (2026-09-06, level ERROR): view public.canonical_food_keys runs as
-- SECURITY DEFINER (the Postgres default for views), so it reads its base tables with the
-- view owner's rights, not the caller's. Real exposure: none — the view is the union of two
-- public vocabulary tables (allergen_dictionary, dietary_pattern_dictionary: 44 keys, no
-- client or tenant data) that anon and authenticated can already SELECT directly. Flipping
-- to security_invoker keeps behaviour identical and silences the finding honestly.
alter view public.canonical_food_keys set (security_invoker = on);

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260906150000_client_onboarding_facts.sql =====
-- Slice 1 of the original design notes (not included) — the status view.
--
-- client_onboarding_facts(): one row per non-archived client, every onboarding fact derived
-- from tables that already exist, and ONE next_action per client by fixed precedence. Nothing
-- here writes. Twin-facts rules are enforced in the OUTPUT, not the UI:
--   * 'none' (never sent) and 'pending' (sent, not done) are different values;
--   * paid_via_platform is true or NULL (not tracked) — never false, because paying outside
--     this platform (every client before 2026-09-06, every external payment link) is unknowable;
--   * a client with a LIVE program is never told to redo an intake: an old expired form is not
--     the thing blocking someone who is already training (deviation from the plan's first
--     draft of the precedence, recorded 2026-09-06).
-- Security invoker: a coach session reads through RLS; the MCP service role passes the tenant.

create or replace function public.client_onboarding_facts(p_tenant_id uuid default null)
returns table (
  client_id uuid,
  display_name text,
  client_status text,
  paid_via_platform boolean,
  intake_state text,
  intake_sent_at timestamptz,
  intake_expires_at timestamptz,
  intake_submitted_at timestamptz,
  draft_state text,
  program_live boolean,
  nutrition_state text,
  invite_state text,
  invite_expires_at timestamptz,
  opened_app boolean,
  first_set_logged boolean,
  first_checkin boolean,
  stalled_since timestamptz,
  stalled_days integer,
  next_action text
)
language plpgsql stable security invoker
set search_path = public as $fn$
declare
  v_tenant uuid := coalesce(p_tenant_id, current_tenant_id());
begin
  if v_tenant is null then
    raise exception 'client_onboarding_facts: no tenant in session';
  end if;
  -- A signed-in user (coach JWT) may only read their own tenant. The service role and a
  -- direct database session (SQL editor, migrations) may pass any tenant.
  if auth.uid() is not null and auth.role() is distinct from 'service_role'
     and v_tenant is distinct from current_tenant_id() then
    raise exception 'client_onboarding_facts: tenant mismatch';
  end if;

  return query
  with c as (
    select cl.* from clients cl where cl.tenant_id = v_tenant and cl.status <> 'archived'
  ),
  intake as (
    select distinct on (i.client_id) i.client_id, i.status, i.created_at, i.expires_at, i.submitted_at
    from intake_forms i where i.tenant_id = v_tenant order by i.client_id, i.created_at desc
  ),
  draft as (
    select distinct on (d.client_id) d.client_id, d.status, d.generated_at, d.decided_at
    from program_drafts d where d.tenant_id = v_tenant order by d.client_id, d.generated_at desc
  ),
  asg as (
    select a.client_id, bool_or(a.active) as live, max(a.assigned_at) as assigned_at
    from assignments a where a.tenant_id = v_tenant group by a.client_id
  ),
  -- Nutrition lives in TWO tables: client_meal_plans (structured, current) and meal_plans
  -- (the older uploaded/legacy plans, still assigned for some clients — 5 of 35 on
  -- 2026-09-06 had a plan ONLY there). A client is "assigned" if either table says so.
  mp_all as (
    select m.client_id, m.status, m.assigned_at, m.updated_at
    from client_meal_plans m where m.tenant_id = v_tenant
    union all
    select l.client_id,
           case when l.assigned_at is not null or l.status = 'assigned' then 'assigned' else 'draft' end,
           l.assigned_at, l.updated_at
    from meal_plans l where l.tenant_id = v_tenant
  ),
  mp as (
    select x.client_id,
           bool_or(x.status = 'assigned') as assigned,
           bool_or(x.status = 'draft') as drafted,
           max(x.assigned_at) as assigned_at,
           max(x.updated_at) as updated_at
    from mp_all x group by x.client_id
  ),
  -- A logged set lives in workout_logs (done = true). history_workout_sets is the Trainerize
  -- import table and was empty for every client on 2026-09-06 — the plan named it, the data
  -- said otherwise. Both are read so an imported history still counts.
  sets as (
    select x.client_id, true as any_set from (
      select l.client_id from workout_logs l where l.tenant_id = v_tenant and l.done
      union all
      select h.client_id from history_workout_sets h where h.tenant_id = v_tenant
    ) x group by x.client_id
  ),
  sess as (
    select w.client_id, max(w.session_date) as last_session from workout_sessions w where w.tenant_id = v_tenant group by w.client_id
  ),
  ck as (
    select k.client_id, max(k.submitted_at) as last_checkin from checkins k where k.tenant_id = v_tenant group by k.client_id
  ),
  facts as (
    select
      c.id,
      c.display_name,
      c.status::text as client_status,
      case when c.stripe_checkout_session_id is not null then true else null end as paid_via_platform,
      case
        when i.client_id is null then 'none'
        when i.status = 'submitted' then 'submitted'
        when i.expires_at < now() then 'expired'
        else 'pending' end as intake_state,
      i.created_at as intake_sent_at,
      i.expires_at as intake_expires_at,
      i.submitted_at as intake_submitted_at,
      coalesce(d.status::text, 'none') as draft_state,
      coalesce(a.live, false) as program_live,
      case when m.assigned then 'assigned' when m.drafted then 'draft' else 'none' end as nutrition_state,
      case
        when c.client_user_id is not null then 'claimed'
        when c.invite_token is null then 'none'
        when c.invite_expires_at < now() then 'expired'
        else 'pending' end as invite_state,
      c.invite_expires_at,
      coalesce(c.welcome_seen, false) as opened_app,
      coalesce(s.any_set, false) as first_set_logged,
      (ck.last_checkin is not null) as first_checkin,
      greatest(c.joined_at, c.updated_at, i.created_at, i.submitted_at, d.generated_at, d.decided_at,
               a.assigned_at, m.assigned_at, m.updated_at, se.last_session::timestamptz, ck.last_checkin) as stalled_since
    from c
    left join intake i on i.client_id = c.id
    left join draft  d on d.client_id = c.id
    left join asg    a on a.client_id = c.id
    left join mp     m on m.client_id = c.id
    left join sets   s on s.client_id = c.id
    left join sess   se on se.client_id = c.id
    left join ck     on ck.client_id = c.id
  )
  select
    f.id, f.display_name, f.client_status, f.paid_via_platform,
    f.intake_state, f.intake_sent_at, f.intake_expires_at, f.intake_submitted_at,
    f.draft_state, f.program_live, f.nutrition_state,
    f.invite_state, f.invite_expires_at,
    f.opened_app, f.first_set_logged, f.first_checkin,
    f.stalled_since,
    greatest(0, floor(extract(epoch from (now() - coalesce(f.stalled_since, now()))) / 86400))::int as stalled_days,
    case
      when not f.program_live and f.intake_state = 'none'    then 'send_intake'
      when not f.program_live and f.intake_state = 'expired' then 'intake_expired_resend'
      when not f.program_live and f.intake_state = 'pending' then 'awaiting_client_intake'
      when not f.program_live and f.draft_state in ('draft', 'held_medical') then 'review_draft'
      when not f.program_live                                then 'unclassified'
      when f.nutrition_state = 'none'                        then 'assemble_nutrition'
      when f.nutrition_state = 'draft'                       then 'release'
      when f.invite_state = 'none'                           then 'send_invite'
      when f.invite_state = 'expired'                        then 'invite_expired_resend'
      when f.invite_state = 'pending'                        then 'awaiting_client_claim'
      when not f.opened_app                                  then 'awaiting_first_open'
      when not f.first_set_logged                            then 'awaiting_first_set'
      else 'onboarded' end as next_action
  from facts f
  order by f.display_name;
end $fn$;

revoke all on function public.client_onboarding_facts(uuid) from public, anon;
grant execute on function public.client_onboarding_facts(uuid) to authenticated, service_role;
comment on function public.client_onboarding_facts(uuid) is
  'Slice 1 status view: one row per non-archived client with every onboarding fact and one next_action by fixed precedence. Security invoker (RLS); service role may pass any tenant. Read-only.';

-- ---------- rm_coach_overview: decisions card reads the facts function ----------
-- Verbatim copy of 20260826170000's body with ONE change: the ord-4 account_unreachable row
-- is replaced by four onboarding rows (see the Slice 1 comment inline). Everything else is
-- byte-identical so the deploy diff shows exactly that.
create or replace function public.rm_coach_overview()
returns jsonb
language plpgsql stable security invoker
set search_path = public as $fn$
declare
  v_tenant  uuid := current_tenant_id();
  v_sources jsonb;
  v_conf    jsonb;
  v_out     jsonb;
begin
  if v_tenant is null then
    raise exception 'rm_coach_overview: no tenant in session';
  end if;

  -- Sources first. Nothing below is readable without them.
  select jsonb_agg(to_jsonb(s) order by
           case s.key when 'training' then 1 when 'checkins' then 2
                      when 'messages' then 3 else 4 end)
    into v_sources
  from rm_source_health() s;

  select jsonb_object_agg(s->>'key', (s->>'confidence')::numeric)
    into v_conf
  from jsonb_array_elements(v_sources) s;

  with cand_raw as (
    -- Computed once. Previously called a second time, from scratch, by the
    -- suppressed-signal count below — the whole severity/recency/scoring
    -- pipeline ran twice per page load for one page.
    select * from rm_attention_candidates()
  ),
  cand as (
    select c.*, coalesce((v_conf->>c.source_key)::numeric, 0) as conf
    from cand_raw c
  ),
  scored as (
    select cand.*, round(severity * recency * conf, 4) as score from cand
  ),
  banded as (
    select scored.*,
      case
        -- 'decide' is not a score band. It is any item whose resolution is a
        -- coach decision with a deadline, and it always renders.
        when is_decision then 'decide'
        when score >= 0.7 then 'act'
        when score >= 0.4 then 'watch'
        else 'hold'
      end as band
    from scored
    -- RULE 1: a signal from a source that is not live or stale cannot produce
    -- an attention item. conf = 0 for unavailable / not_configured.
    where conf > 0
  ),
  -- ---------------- grouping ----------------
  -- The mockup collapses a repeated signal into one card ("6 clients — Active
  -- assignment, no meal plan") rather than printing six. Without this the queue
  -- is 33 rows deep on the current data and stops being a ranking at all.
  -- Threshold 3: up to three named clients read as individuals; four or more is
  -- a pattern, and for a pattern the coach wants a list, not a queue.
  sized as (
    select b.*, count(*) over (partition by b.signal_type) as sig_n from banded b
  ),
  singles as (
    select client_id, display_name, band, score, signal_type, source_key,
           mechanism, evidence, actions, since, deadline, 1 as member_count
    from sized where sig_n <= 3
  ),
  grouped as (
    select
      null::uuid as client_id,
      rm__n(count(*), 'client') as display_name,
      -- A group is at least as urgent as its most urgent member.
      (array_agg(band order by score desc))[1] as band,
      max(score) as score,
      signal_type, source_key,
      -- Plural copy per signal, in SQL, so the connector reads the same sentence
      -- The coach reads.
      case signal_type
        when 'training_silent' then
          'No logged session in over three days against an active assignment.'
        when 'account_unreachable' then
          'Client records with no account attached and no invite issued. They cannot open the app.'
        when 'no_meal_plan' then
          'Active assignment with no meal plan attached. The nutrition surface is blank on their side.'
        when 'unread_message' then 'Messages waiting over 24 hours, unanswered.'
        when 'overreach' then
          'More sessions logged in seven days than the program prescribes.'
        when 'paused_no_resume' then
          'Paused with no resume date recorded, so nothing will surface them again on its own.'
        when 'load_regression' then
          'Top-set load falling across three sessions running while volume holds.'
        when 'first_week_strong' then
          'First full week complete, every prescribed session logged.'
        else 'Multiple clients on the same signal.'
      end as mechanism,
      jsonb_build_array(
        jsonb_build_object('label', 'clients', 'value', count(*)::text),
        jsonb_build_object('label', 'longest waiting',
          'value', (array_agg(display_name order by score desc, display_name))[1]
                   || case when count(*) > 1 then ' +' || (count(*) - 1) else '' end)
      ) as evidence,
      jsonb_build_array(
        jsonb_build_object('key','review_list','label','Review list','primary',true)
      ) as actions,
      min(since) as since,
      min(deadline) as deadline,
      count(*)::int as member_count
    from sized where sig_n > 3
    group by signal_type, source_key
  ),
  queue as (
    select * from singles
    union all
    select * from grouped
  )
  select jsonb_build_object(
    'schema_version', 1,
    'generated_at',   now(),

    -- ---------------- tenant brand ----------------
    'tenant', (
      select jsonb_build_object(
        'tenant_id',          t.id,
        'slug',               t.slug,
        'app_name',           coalesce(tc.app_name, 'Coach App'),
        'coach_display_name', tc.coach_display_name,
        'logo_url',           tc.logo_url,
        'brand_color',        tc.brand_color,
        'theme_key',          tc.theme_key,
        -- Direct column reads. Previously routed through rm__cfg_text(), which
        -- ran a live information_schema.columns existence check on every call
        -- for two columns that have existed since the schema-gap migration —
        -- see 2026-08-26 perf fix note at the top of this migration.
        'surface_mode',       coalesce(tc.surface_mode, 'dark'),
        'type_key',           coalesce(tc.type_key, 'grotesk'),
        'weight_unit',        tc.weight_unit,
        'features', jsonb_build_object(
          'messaging',       tc.messaging_on,
          'progress_photos', tc.progress_photos_on,
          'progress_weight', tc.progress_weight_on,
          'approval_gate',   tc.program_approval_gate
        ))
      from tenant_config tc join tenants t on t.id = tc.tenant_id
      where tc.tenant_id = v_tenant
    ),

    'sources', v_sources,

    -- ---------------- roster pulse ----------------
    -- A metric whose backing source is unhealthy is returned as JSON null, NOT
    -- 0. The UI renders null as a hatched em-dash. A false zero here is the
    -- specific failure this page exists to prevent: 0 reads as "nobody trained"
    -- and would have a coach message a client who did train.
    'roster', (
      select jsonb_build_object(
        'total',   count(*),
        'active',  count(*) filter (where status = 'active'),
        'paused',  count(*) filter (where status = 'paused'),
        'invited', count(*) filter (where status = 'invited'),
        'trained_7d', case when (v_conf->>'training')::numeric > 0 then (
            select count(distinct ws.client_id) from workout_sessions ws
            where ws.tenant_id = v_tenant
              and ws.session_date > (now() - interval '7 days')::date) end,
        'silent_7d', case when (v_conf->>'training')::numeric > 0 then (
            select count(*) from assignments a
            join clients cc on cc.id = a.client_id and cc.status = 'active'
            where a.tenant_id = v_tenant and a.active
              and not exists (select 1 from workout_sessions ws
                where ws.client_id = a.client_id
                  and ws.session_date > (now() - interval '7 days')::date)) end,
        'checked_in_7d', case when (v_conf->>'checkins')::numeric > 0 then (
            select count(distinct ck.client_id) from checkins ck
            where ck.tenant_id = v_tenant
              and ck.submitted_at > now() - interval '7 days') end
      )
      from clients where tenant_id = v_tenant
    ),

    -- ---------------- ranked attention ----------------
    'attention', coalesce((
      select jsonb_agg(jsonb_build_object(
        'client_id', client_id, 'display_name', display_name,
        'band', band, 'score', score,
        'signal_type', signal_type, 'source_key', source_key,
        'mechanism', mechanism, 'evidence', evidence, 'actions', actions,
        'since', since, 'deadline', deadline,
        -- >1 means this card stands for a group, not one person. The UI uses it
        -- to label the action button and to avoid implying a single client.
        'member_count', member_count)
      order by case band when 'act' then 1 when 'decide' then 2
                         when 'watch' then 3 else 4 end,
               score desc, display_name)
      from queue), '[]'::jsonb),

    -- ---------------- suppression ----------------
    -- RULE 2: an unhealthy source yields a count, never a flag. RULE 3: the UI
    -- renders this hatched, and never as an empty queue.
    'suppressed', coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_key', x.source_key, 'withheld_count', x.n,
        'reason', x.reason, 'since', x.since) order by x.n desc)
      from (
        select c.source_key, count(*)::int as n,
          (select s->>'note' from jsonb_array_elements(v_sources) s
            where s->>'key' = c.source_key) as reason,
          (select (s->>'last_event_at')::timestamptz from jsonb_array_elements(v_sources) s
            where s->>'key' = c.source_key) as since
        from cand_raw c
        where coalesce((v_conf->>c.source_key)::numeric, 0) = 0
        group by c.source_key
      ) x), '[]'::jsonb),

    -- ---------------- decisions ----------------
    -- Roster-derived, so this card never empties just because a feed died.
    'decisions', coalesce((
      select jsonb_agg(d order by d->>'ord')
      from (
        select jsonb_build_object('ord','1','kind','draft_approval',
          'title','Program drafts awaiting approval',
          'detail', case when (select program_approval_gate from tenant_config
                               where tenant_id = v_tenant)
                    then 'Approval gate is on. Nothing reaches a client until you release it.'
                    else 'Approval gate is off — drafts publish without review.' end,
          'count', (select count(*) from program_drafts
                     where tenant_id = v_tenant and status = 'draft')) as d
        union all
        select jsonb_build_object('ord','2','kind','no_meal_plan',
          'title','Active clients without a meal plan',
          'detail','Assignment live, nutrition surface blank on their side.',
          'count', (select count(*) from assignments a
                     join clients c on c.id = a.client_id and c.status = 'active'
                     where a.tenant_id = v_tenant and a.active
                       and not exists (select 1 from meal_plans mp
                         where mp.client_id = c.id)))
        union all
        -- Drafted but never released. One click each, and the client currently
        -- sees a blank nutrition surface despite the work already being done.
        select jsonb_build_object('ord','3','kind','meal_plan_unreleased',
          'title','Meal plans drafted, never released',
          'detail','The work is done. Until it is assigned, the client cannot see it.',
          'count', (select count(*) from meal_plans
                     where tenant_id = v_tenant and assigned_at is null))
        union all
        -- Slice 1 (2026-09-06): the single account_unreachable row became four rows fed by
        -- client_onboarding_facts(), one per place a client can be stuck. Each is a real
        -- count from the same function the Clients page and the connector read.
        select jsonb_build_object('ord','4a','kind','intakes_unanswered',
          'title','Intakes out, unanswered',
          'detail','Sent and not submitted, or expired before it was. Resend from the client profile.',
          'count', (select count(*) from client_onboarding_facts(v_tenant) f
                     where f.client_status <> 'paused'
                       and f.next_action in ('awaiting_client_intake','intake_expired_resend')),
          'deadline', (select min(f.intake_expires_at) from client_onboarding_facts(v_tenant) f
                     where f.client_status <> 'paused' and f.next_action = 'awaiting_client_intake'))
        union all
        select jsonb_build_object('ord','4b','kind','released_no_invite',
          'title','Released, invite not sent',
          'detail','Program and nutrition are live. They have no way into the app yet.',
          'count', (select count(*) from client_onboarding_facts(v_tenant) f
                     where f.client_status <> 'paused' and f.next_action = 'send_invite'))
        union all
        select jsonb_build_object('ord','4c','kind','invites_unclaimed',
          'title','Invites out, unclaimed',
          'detail','Invited and never signed in, or the invite expired first.',
          'count', (select count(*) from client_onboarding_facts(v_tenant) f
                     where f.client_status <> 'paused'
                       and f.next_action in ('awaiting_client_claim','invite_expired_resend')),
          'deadline', (select min(f.invite_expires_at) from client_onboarding_facts(v_tenant) f
                     where f.client_status <> 'paused' and f.next_action = 'awaiting_client_claim'))
        union all
        select jsonb_build_object('ord','4d','kind','never_trained',
          'title','In the app, never trained',
          'detail','Signed in, program live, not one set logged. A real zero, not a gap.',
          'count', (select count(*) from client_onboarding_facts(v_tenant) f
                     where f.client_status <> 'paused'
                       and f.next_action in ('awaiting_first_open','awaiting_first_set')))
        union all
        select jsonb_build_object('ord','5','kind','paused_no_resume',
          'title','Paused without a resume date',
          'detail','Will not resurface on its own until a resume date is set.',
          'count', (select count(*) from clients
                     where tenant_id = v_tenant and status = 'paused'
                       and pause_resume_date is null))
      ) dec_rows
      where (d->>'count')::int > 0), '[]'::jsonb),

    -- ---------------- prep timelines ----------------
    -- clients.show_date now exists (20260729120100). Undated clients are EXCLUDED
    -- from this rail, never ranked lower on it. With every show_date still null
    -- this returns [] with unavailable=false, so the UI shows the SOLID "no dates
    -- set" empty state -- we know, and there are none -- not the hatched
    -- "cannot see" state. That distinction is the whole point of the page.
    'timelines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'client_id', c.id, 'display_name', c.display_name,
        'event_date', c.show_date,
        'weeks_out', ceil((c.show_date - now()::date) / 7.0),
        'phase', case
          when c.show_date - now()::date <= 7  then 'peak week'
          when c.show_date - now()::date <= 28 then 'final month'
          else 'build' end,
        'note', coalesce(c.show_name, 'no show name set'))
      order by c.show_date)
      from clients c
      where c.tenant_id = v_tenant and c.status = 'active'
        and c.show_date is not null and c.show_date >= now()::date
    ), '[]'::jsonb),
    'timelines_unavailable', false,
    'timelines_note', null,

    -- Signals the read model knows about but cannot compute on this schema.
    -- Reported so the page can be honest instead of silently omitting them.
    -- program_ending is now computable: assignments.ends_on exists and the
    -- signal is live in rm_attention_candidates. Nothing is currently
    -- uncomputable, so this list is empty and the UI hides the block.
    'unavailable_signals', '[]'::jsonb,

    -- ---------------- activity ----------------
    -- Chronological, deliberately last, capped at 8.
    'activity', coalesce((
      select jsonb_agg(e order by (e->>'at') desc)
      from (
        select jsonb_build_object('at', ws.completed_at, 'client_id', ws.client_id,
          'display_name', c.display_name, 'kind','session_complete',
          'summary','completed a session'
            || coalesce((select ' — ' || count(*) || ' sets' from workout_logs wl
                 where wl.session_id = ws.id and wl.done
                 having count(*) > 0), '')) as e
        from workout_sessions ws join clients c on c.id = ws.client_id
        where ws.tenant_id = v_tenant and ws.completed_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', wl.logged_at, 'client_id', wl.client_id,
          'display_name', c.display_name, 'kind','set_logged',
          'summary','logged a set'
            || coalesce(' — ' || wl.weight || ' x ' || wl.reps, ''))
        from workout_logs wl join clients c on c.id = wl.client_id
        where wl.tenant_id = v_tenant and wl.logged_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', m.sent_at, 'client_id', m.client_id,
          'display_name', c.display_name, 'kind','message', 'summary','messaged you')
        from messages m join clients c on c.id = m.client_id
        where m.tenant_id = v_tenant and m.sender_role = 'client'
          and m.sent_at > now() - interval '24 hours'
        union all
        select jsonb_build_object('at', ck.submitted_at, 'client_id', ck.client_id,
          'display_name', c.display_name, 'kind','checkin','summary','submitted a check-in')
        from checkins ck join clients c on c.id = ck.client_id
        where ck.tenant_id = v_tenant and ck.submitted_at > now() - interval '24 hours'
        order by 1 desc
        limit 8
      ) ev), '[]'::jsonb)
  ) into v_out;

  return v_out;
end;
$fn$;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260906170000_release_client.sql =====
-- Slice 3 of the original design notes (not included) — one release.
--
-- D6: clients.nutrition_declined_at records the coach's explicit choice "no nutrition plan
-- for this client" (training-only coaching). It satisfies the release checklist and the
-- status view's nutrition item; it is never inferred, only set by release_client(…, true).
alter table public.clients add column if not exists nutrition_declined_at timestamptz null;
comment on column public.clients.nutrition_declined_at is
  'Coach recorded "no nutrition plan for this client" (D6). Set only by release_client(p_no_nutrition => true). NULL = not declined.';

-- release_checklist(): the three items as they stand, for the Release button to render
-- before anything is written. Same rules as release_client(); read-only.
create or replace function public.release_checklist(p_client_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public as $fn$
declare
  cli          public.clients%rowtype;
  v_live       boolean;
  v_draft      public.program_drafts%rowtype;
  v_days       int := 0;
  v_assigned   boolean;
  v_splan_id   uuid;
  v_slots      int := 0;
  v_lplan_id   uuid;
  v_held       public.program_drafts%rowtype;
  v_intake     public.intake_forms%rowtype;
  v_flags      jsonb;
  v_reviewed   boolean := false;
  v_program    jsonb;
  v_nutrition  jsonb;
  v_email      jsonb;
  v_health     jsonb;
begin
  if coalesce(public.current_app_role(), '') is distinct from 'coach' then
    raise exception 'not authorized: coach role required';
  end if;
  select * into cli from public.clients where id = p_client_id;
  if not found then raise exception 'client % not found', p_client_id; end if;
  if public.current_tenant_id() is null or cli.tenant_id is distinct from public.current_tenant_id() then
    raise exception 'not authorized: wrong tenant';
  end if;

  -- 1. program
  select exists (select 1 from public.assignments a where a.client_id = cli.id and a.active) into v_live;
  select * into v_draft from public.program_drafts d
   where d.client_id = cli.id and d.status in ('draft','approved')
   order by d.generated_at desc limit 1;
  if found then v_days := jsonb_array_length(coalesce(v_draft.training->'days','[]'::jsonb)); end if;
  -- A medical hold is a program state the coach must resolve in Programs; release never
  -- approves a held draft on the coach's behalf.
  select * into v_held from public.program_drafts d
   where d.client_id = cli.id and d.status = 'held_medical'
   order by d.generated_at desc limit 1;
  v_program := case
    when v_live then jsonb_build_object('ok', true, 'state', 'live', 'detail', 'Program live')
    when v_draft.id is null and v_held.id is not null then jsonb_build_object('ok', false, 'state', 'held_medical', 'detail', 'Program draft held for medical review — review and approve it in Programs first')
    when v_draft.id is not null and v_days > 0 then jsonb_build_object('ok', true, 'state', 'draft', 'detail', format('Program draft (%s day%s)', v_days, case when v_days = 1 then '' else 's' end), 'draft_id', v_draft.id)
    when v_draft.id is not null then jsonb_build_object('ok', false, 'state', 'empty_draft', 'detail', 'Program draft has no training days')
    else jsonb_build_object('ok', false, 'state', 'none', 'detail', 'No program draft') end;

  -- 2. nutrition — structured (client_meal_plans) first, then the legacy meal_plans table.
  select exists (select 1 from public.client_meal_plans m where m.client_id = cli.id and m.status = 'assigned')
      or exists (select 1 from public.meal_plans l where l.client_id = cli.id and (l.assigned_at is not null or l.status = 'assigned'))
    into v_assigned;
  select m.id into v_splan_id from public.client_meal_plans m
   where m.client_id = cli.id and m.status = 'draft' order by m.created_at desc limit 1;
  if v_splan_id is not null then
    select count(*) into v_slots from public.client_meal_plan_slots s where s.plan_id = v_splan_id;
  end if;
  select l.id into v_lplan_id from public.meal_plans l
   where l.client_id = cli.id and l.assigned_at is null and coalesce(l.status,'draft') = 'draft'
   order by l.created_at desc limit 1;
  v_nutrition := case
    when v_assigned then jsonb_build_object('ok', true, 'state', 'assigned', 'detail', 'Nutrition assigned')
    when cli.nutrition_declined_at is not null then jsonb_build_object('ok', true, 'state', 'declined', 'detail', 'No nutrition plan (recorded ' || to_char(cli.nutrition_declined_at, 'YYYY-MM-DD') || ')')
    when v_splan_id is not null and v_slots > 0 then jsonb_build_object('ok', true, 'state', 'draft', 'detail', format('Nutrition (%s meal%s)', v_slots, case when v_slots = 1 then '' else 's' end), 'plan_id', v_splan_id, 'source', 'structured')
    when v_splan_id is not null then jsonb_build_object('ok', false, 'state', 'empty_draft', 'detail', 'Nutrition draft has no meals')
    when v_lplan_id is not null then jsonb_build_object('ok', true, 'state', 'draft', 'detail', 'Nutrition (uploaded plan)', 'plan_id', v_lplan_id, 'source', 'legacy')
    else jsonb_build_object('ok', false, 'state', 'none', 'detail', 'No nutrition plan — or tick "no nutrition for this client"') end;

  -- 3. email — present AND syntactically valid (one @, something either side, a dot after).
  v_email := case
    when nullif(trim(coalesce(cli.email, '')), '') is null then jsonb_build_object('ok', false, 'state', 'missing', 'detail', 'Email missing')
    when trim(cli.email) !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then jsonb_build_object('ok', false, 'state', 'invalid', 'detail', 'Email looks invalid: ' || cli.email)
    else jsonb_build_object('ok', true, 'state', 'valid', 'detail', 'Email ' || trim(cli.email)) end;

  -- 4. health / compliance — authoritative at the database boundary. Reads the latest
  -- SUBMITTED intake's health_flags (written by intake-submit from the PAR-Q answers).
  -- Fails closed: no screen on record, or an unreadable one, blocks; a flagged screen
  -- blocks unless a coach has explicitly reviewed it — the only clearance this app records
  -- is a coach approving the draft that carried the flags (approve_program_draft on the held
  -- draft, decided_by set). Nothing here infers clearance.
  select * into v_intake from public.intake_forms i
   where i.client_id = cli.id and i.status = 'submitted'
   order by i.submitted_at desc nulls last, i.created_at desc limit 1;
  if v_intake.id is null then
    v_health := jsonb_build_object('ok', false, 'state', 'no_screen', 'detail', 'No health screen on record — a submitted intake is required');
  elsif jsonb_typeof(v_intake.health_flags) is distinct from 'array' then
    v_health := jsonb_build_object('ok', false, 'state', 'unreadable', 'detail', 'Health screen not readable — fix the intake record before releasing');
  elsif jsonb_array_length(v_intake.health_flags) = 0 then
    v_health := jsonb_build_object('ok', true, 'state', 'clear', 'detail', 'Health screen clear');
  else
    v_flags := v_intake.health_flags;
    select exists (select 1 from public.program_drafts d
                    where d.intake_id = v_intake.id and d.status in ('approved', 'published')
                      and d.decided_by is not null) into v_reviewed;
    v_health := case
      when v_reviewed then jsonb_build_object('ok', true, 'state', 'flagged_reviewed', 'flags', v_flags,
                              'detail', 'Health screen flagged, reviewed and approved by coach')
      else jsonb_build_object('ok', false, 'state', 'flagged', 'flags', v_flags,
                              'detail', 'Health screen flagged (' || (select string_agg(x, ', ') from jsonb_array_elements_text(v_flags) x) || ') — review and approve the held draft in Programs first') end;
  end if;

  return jsonb_build_object(
    'client_id', cli.id,
    'program', v_program, 'nutrition', v_nutrition, 'email', v_email, 'health', v_health,
    'invite_state', case when cli.client_user_id is not null then 'claimed'
                         when cli.invite_token is null then 'none'
                         when cli.invite_expires_at < now() then 'expired' else 'pending' end,
    'ready', (v_program->>'ok')::boolean and (v_nutrition->>'ok')::boolean and (v_email->>'ok')::boolean and (v_health->>'ok')::boolean);
end $fn$;

-- release_client(): the one button. Refuses with the FIRST missing item named (program /
-- nutrition / email / health); otherwise, in one transaction: publish the draft (existing
-- publish_program_draft path), assign the nutrition draft (releaseStructuredPlan /
-- releaseMealPlan logic, server-side), mint the invite token (client-invite's token logic)
-- and return its claim_path. Any failure rolls back everything: no half-released client.
--
-- Never silently partial, end to end: the auth account cannot be created inside SQL, so the
-- SPA pre-creates it FIRST via client-invite {account_only: true} — an unconfirmed,
-- passwordless account with no invite token is inert and idempotent — and only then calls
-- this function. If the account step fails nothing has been released; if this function
-- fails nothing has been released; if both succeed the claim link returned here is the
-- one the client receives. No second token mint after release.
create or replace function public.release_client(p_client_id uuid, p_no_nutrition boolean default false)
returns jsonb
language plpgsql security definer
set search_path = public as $fn$
declare
  cli          public.clients%rowtype;
  chk          jsonb;
  v_draft_id   uuid;
  v_program_id uuid;
  v_program    jsonb;
  v_nutrition  jsonb;
  v_plan_id    uuid;
  v_token      text;
  v_expires    timestamptz;
begin
  -- release_checklist() carries the role + tenant checks; a refusal there is a refusal here.
  chk := public.release_checklist(p_client_id);
  -- Serialise concurrent releases of the same client: the second waits, then re-reads.
  select * into cli from public.clients where id = p_client_id for update;
  chk := public.release_checklist(p_client_id);
  if public.tenant_is_suspended(cli.tenant_id) then
    raise exception 'This app is paused: its hosting subscription has lapsed. Existing data stays readable, but new changes are unavailable until it is reactivated.'
      using errcode = '42501';
  end if;

  -- Checklist, first missing item named. p_no_nutrition satisfies item 2 only when nothing
  -- else does; it never overrides a plan that exists.
  if not (chk->'program'->>'ok')::boolean then
    raise exception 'release refused: %', chk->'program'->>'detail' using errcode = 'P0001', hint = 'program';
  end if;
  -- The D6 tick only stands in for NOTHING. An empty draft is a draft to fix, not a decline.
  if not (chk->'nutrition'->>'ok')::boolean and not (p_no_nutrition and chk->'nutrition'->>'state' = 'none') then
    raise exception 'release refused: %', chk->'nutrition'->>'detail' using errcode = 'P0001', hint = 'nutrition';
  end if;
  if not (chk->'email'->>'ok')::boolean then
    raise exception 'release refused: %', chk->'email'->>'detail' using errcode = 'P0001', hint = 'email';
  end if;
  if not (chk->'health'->>'ok')::boolean then
    raise exception 'release refused: %', chk->'health'->>'detail' using errcode = 'P0001', hint = 'health';
  end if;

  -- 1. program: publish through the existing path, or leave a live assignment alone.
  if chk->'program'->>'state' = 'live' then
    select a.program_id into v_program_id from public.assignments a where a.client_id = cli.id and a.active limit 1;
    v_program := jsonb_build_object('action', 'already_live', 'program_id', v_program_id);
  else
    v_draft_id := (chk->'program'->>'draft_id')::uuid;
    update public.program_drafts
       set status = 'approved', decided_at = coalesce(decided_at, now()), decided_by = coalesce(decided_by, auth.uid()),
           decision_note = coalesce(decision_note, 'released via release_client')
     where id = v_draft_id and status = 'draft';
    v_program_id := public.publish_program_draft(v_draft_id);
    v_program := jsonb_build_object('action', 'published', 'program_id', v_program_id, 'draft_id', v_draft_id);
  end if;

  -- 2. nutrition
  if chk->'nutrition'->>'state' in ('assigned', 'declined') then
    v_nutrition := jsonb_build_object('action', 'already_' || (chk->'nutrition'->>'state'));
  elsif chk->'nutrition'->>'state' = 'draft' then
    v_plan_id := (chk->'nutrition'->>'plan_id')::uuid;
    if chk->'nutrition'->>'source' = 'structured' then
      -- releaseStructuredPlan(): two columns, status-guarded, never nulls an assigned_at.
      update public.client_meal_plans set status = 'assigned', assigned_at = now(), updated_at = now()
       where id = v_plan_id and status = 'draft';
    else
      -- releaseMealPlan(): the legacy table, same two-column write.
      update public.meal_plans set status = 'assigned', assigned_at = now(), updated_at = now()
       where id = v_plan_id and assigned_at is null;
    end if;
    if not found then raise exception 'release: nutrition plan % was not in draft state', v_plan_id; end if;
    v_nutrition := jsonb_build_object('action', 'assigned', 'plan_id', v_plan_id, 'source', chk->'nutrition'->>'source');
  else
    -- p_no_nutrition, and nothing else satisfied the item: record the choice (D6).
    update public.clients set nutrition_declined_at = now(), updated_at = now() where id = cli.id;
    v_nutrition := jsonb_build_object('action', 'declined');
  end if;

  -- 3. invite token (client-invite's minting; the SPA calls that function next for the auth account).
  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  v_expires := now() + interval '14 days';
  update public.clients
     set invite_token = v_token, invite_expires_at = v_expires, updated_at = now()
   where id = cli.id;

  return jsonb_build_object(
    'status', 'released',
    'client_id', cli.id,
    'program', v_program,
    'nutrition', v_nutrition,
    'invite', jsonb_build_object('token_minted', true, 'expires_at', v_expires,
                                 'claim_path', '/claim?token=' || v_token,
                                 'already_claimed', cli.client_user_id is not null),
    'needs_account', cli.client_user_id is null,
    'email', cli.email);
end $fn$;

revoke all on function public.release_checklist(uuid) from public, anon;
revoke all on function public.release_client(uuid, boolean) from public, anon;
grant execute on function public.release_checklist(uuid) to authenticated, service_role;
grant execute on function public.release_client(uuid, boolean) to authenticated, service_role;
comment on function public.release_client(uuid, boolean) is
  'Slice 3: one release. Coach-only, tenant-checked. Refuses naming the first missing item (program / nutrition / email); otherwise publishes the draft, assigns nutrition (or records D6 decline), mints the invite token — atomically. SPA calls client-invite next for the auth account.';

-- ---------- client_onboarding_facts: nutrition_state gains 'declined' (D6) ----------
-- Verbatim re-issue of 20260906150000's function with one CASE branch added.
create or replace function public.client_onboarding_facts(p_tenant_id uuid default null)
returns table (
  client_id uuid,
  display_name text,
  client_status text,
  paid_via_platform boolean,
  intake_state text,
  intake_sent_at timestamptz,
  intake_expires_at timestamptz,
  intake_submitted_at timestamptz,
  draft_state text,
  program_live boolean,
  nutrition_state text,
  invite_state text,
  invite_expires_at timestamptz,
  opened_app boolean,
  first_set_logged boolean,
  first_checkin boolean,
  stalled_since timestamptz,
  stalled_days integer,
  next_action text
)
language plpgsql stable security invoker
set search_path = public as $fn$
declare
  v_tenant uuid := coalesce(p_tenant_id, current_tenant_id());
begin
  if v_tenant is null then
    raise exception 'client_onboarding_facts: no tenant in session';
  end if;
  -- A signed-in user (coach JWT) may only read their own tenant. The service role and a
  -- direct database session (SQL editor, migrations) may pass any tenant.
  if auth.uid() is not null and auth.role() is distinct from 'service_role'
     and v_tenant is distinct from current_tenant_id() then
    raise exception 'client_onboarding_facts: tenant mismatch';
  end if;

  return query
  with c as (
    select cl.* from clients cl where cl.tenant_id = v_tenant and cl.status <> 'archived'
  ),
  intake as (
    select distinct on (i.client_id) i.client_id, i.status, i.created_at, i.expires_at, i.submitted_at
    from intake_forms i where i.tenant_id = v_tenant order by i.client_id, i.created_at desc
  ),
  draft as (
    select distinct on (d.client_id) d.client_id, d.status, d.generated_at, d.decided_at
    from program_drafts d where d.tenant_id = v_tenant order by d.client_id, d.generated_at desc
  ),
  asg as (
    select a.client_id, bool_or(a.active) as live, max(a.assigned_at) as assigned_at
    from assignments a where a.tenant_id = v_tenant group by a.client_id
  ),
  -- Nutrition lives in TWO tables: client_meal_plans (structured, current) and meal_plans
  -- (the older uploaded/legacy plans, still assigned for some clients — 5 of 35 on
  -- 2026-09-06 had a plan ONLY there). A client is "assigned" if either table says so.
  mp_all as (
    select m.client_id, m.status, m.assigned_at, m.updated_at
    from client_meal_plans m where m.tenant_id = v_tenant
    union all
    select l.client_id,
           case when l.assigned_at is not null or l.status = 'assigned' then 'assigned' else 'draft' end,
           l.assigned_at, l.updated_at
    from meal_plans l where l.tenant_id = v_tenant
  ),
  mp as (
    select x.client_id,
           bool_or(x.status = 'assigned') as assigned,
           bool_or(x.status = 'draft') as drafted,
           max(x.assigned_at) as assigned_at,
           max(x.updated_at) as updated_at
    from mp_all x group by x.client_id
  ),
  -- A logged set lives in workout_logs (done = true). history_workout_sets is the Trainerize
  -- import table and was empty for every client on 2026-09-06 — the plan named it, the data
  -- said otherwise. Both are read so an imported history still counts.
  sets as (
    select x.client_id, true as any_set from (
      select l.client_id from workout_logs l where l.tenant_id = v_tenant and l.done
      union all
      select h.client_id from history_workout_sets h where h.tenant_id = v_tenant
    ) x group by x.client_id
  ),
  sess as (
    select w.client_id, max(w.session_date) as last_session from workout_sessions w where w.tenant_id = v_tenant group by w.client_id
  ),
  ck as (
    select k.client_id, max(k.submitted_at) as last_checkin from checkins k where k.tenant_id = v_tenant group by k.client_id
  ),
  facts as (
    select
      c.id,
      c.display_name,
      c.status::text as client_status,
      case when c.stripe_checkout_session_id is not null then true else null end as paid_via_platform,
      case
        when i.client_id is null then 'none'
        when i.status = 'submitted' then 'submitted'
        when i.expires_at < now() then 'expired'
        else 'pending' end as intake_state,
      i.created_at as intake_sent_at,
      i.expires_at as intake_expires_at,
      i.submitted_at as intake_submitted_at,
      coalesce(d.status::text, 'none') as draft_state,
      coalesce(a.live, false) as program_live,
      -- D6 (Slice 3): a coach may record 'no nutrition plan for this client'. That is a
      -- satisfied checklist item, not a missing plan — it must never read as 'none'.
      case when m.assigned then 'assigned'
           when c.nutrition_declined_at is not null then 'declined'
           when m.drafted then 'draft' else 'none' end as nutrition_state,
      case
        when c.client_user_id is not null then 'claimed'
        when c.invite_token is null then 'none'
        when c.invite_expires_at < now() then 'expired'
        else 'pending' end as invite_state,
      c.invite_expires_at,
      coalesce(c.welcome_seen, false) as opened_app,
      coalesce(s.any_set, false) as first_set_logged,
      (ck.last_checkin is not null) as first_checkin,
      greatest(c.joined_at, c.updated_at, i.created_at, i.submitted_at, d.generated_at, d.decided_at,
               a.assigned_at, m.assigned_at, m.updated_at, se.last_session::timestamptz, ck.last_checkin) as stalled_since
    from c
    left join intake i on i.client_id = c.id
    left join draft  d on d.client_id = c.id
    left join asg    a on a.client_id = c.id
    left join mp     m on m.client_id = c.id
    left join sets   s on s.client_id = c.id
    left join sess   se on se.client_id = c.id
    left join ck     on ck.client_id = c.id
  )
  select
    f.id, f.display_name, f.client_status, f.paid_via_platform,
    f.intake_state, f.intake_sent_at, f.intake_expires_at, f.intake_submitted_at,
    f.draft_state, f.program_live, f.nutrition_state,
    f.invite_state, f.invite_expires_at,
    f.opened_app, f.first_set_logged, f.first_checkin,
    f.stalled_since,
    greatest(0, floor(extract(epoch from (now() - coalesce(f.stalled_since, now()))) / 86400))::int as stalled_days,
    case
      when not f.program_live and f.intake_state = 'none'    then 'send_intake'
      when not f.program_live and f.intake_state = 'expired' then 'intake_expired_resend'
      when not f.program_live and f.intake_state = 'pending' then 'awaiting_client_intake'
      when not f.program_live and f.draft_state in ('draft', 'held_medical') then 'review_draft'
      when not f.program_live                                then 'unclassified'
      when f.nutrition_state = 'none'                        then 'assemble_nutrition'
      when f.nutrition_state = 'draft'                       then 'release'
      when f.invite_state = 'none'                           then 'send_invite'
      when f.invite_state = 'expired'                        then 'invite_expired_resend'
      when f.invite_state = 'pending'                        then 'awaiting_client_claim'
      when not f.opened_app                                  then 'awaiting_first_open'
      when not f.first_set_logged                            then 'awaiting_first_set'
      else 'onboarded' end as next_action
  from facts f
  order by f.display_name;
end $fn$;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260906180000_release_checklist_mirrors_release_triggers.sql =====
-- Slice 3 follow-up (found by the live test suite, 2026-09-06 19:52 CDT): the first
-- release_checklist() said a structured nutrition draft was ready when it had ≥1 slot, but the
-- assign is guarded by check_client_meal_plan_release() (meals_per_day, four macro targets,
-- day-0 slots = meals_per_day, every day-0 meal published) and the legacy table by
-- check_meal_plan_release() (macros set, ≥1 meal). release_client() already refused atomically
-- when the trigger fired — nothing was ever half-released — but the panel showed a tick the
-- write would refuse. This re-issue mirrors both triggers so the checklist and the write agree.
create or replace function public.release_checklist(p_client_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public as $fn$
declare
  cli          public.clients%rowtype;
  v_live       boolean;
  v_draft      public.program_drafts%rowtype;
  v_days       int := 0;
  v_assigned   boolean;
  v_splan      public.client_meal_plans%rowtype;
  v_splan_id   uuid;
  v_slots      int := 0;
  v_day0       int := 0;
  v_unpub      int := 0;
  v_sreason    text;
  v_lplan      public.meal_plans%rowtype;
  v_lplan_id   uuid;
  v_lreason    text;
  v_held       public.program_drafts%rowtype;
  v_intake     public.intake_forms%rowtype;
  v_flags      jsonb;
  v_reviewed   boolean := false;
  v_program    jsonb;
  v_nutrition  jsonb;
  v_email      jsonb;
  v_health     jsonb;
begin
  if coalesce(public.current_app_role(), '') is distinct from 'coach' then
    raise exception 'not authorized: coach role required';
  end if;
  select * into cli from public.clients where id = p_client_id;
  if not found then raise exception 'client % not found', p_client_id; end if;
  if public.current_tenant_id() is null or cli.tenant_id is distinct from public.current_tenant_id() then
    raise exception 'not authorized: wrong tenant';
  end if;

  -- 1. program
  select exists (select 1 from public.assignments a where a.client_id = cli.id and a.active) into v_live;
  select * into v_draft from public.program_drafts d
   where d.client_id = cli.id and d.status in ('draft','approved')
   order by d.generated_at desc limit 1;
  if found then v_days := jsonb_array_length(coalesce(v_draft.training->'days','[]'::jsonb)); end if;
  -- A medical hold is a program state the coach must resolve in Programs; release never
  -- approves a held draft on the coach's behalf.
  select * into v_held from public.program_drafts d
   where d.client_id = cli.id and d.status = 'held_medical'
   order by d.generated_at desc limit 1;
  v_program := case
    when v_live then jsonb_build_object('ok', true, 'state', 'live', 'detail', 'Program live')
    when v_draft.id is null and v_held.id is not null then jsonb_build_object('ok', false, 'state', 'held_medical', 'detail', 'Program draft held for medical review — review and approve it in Programs first')
    when v_draft.id is not null and v_days > 0 then jsonb_build_object('ok', true, 'state', 'draft', 'detail', format('Program draft (%s day%s)', v_days, case when v_days = 1 then '' else 's' end), 'draft_id', v_draft.id)
    when v_draft.id is not null then jsonb_build_object('ok', false, 'state', 'empty_draft', 'detail', 'Program draft has no training days')
    else jsonb_build_object('ok', false, 'state', 'none', 'detail', 'No program draft') end;

  -- 2. nutrition — structured (client_meal_plans) first, then the legacy meal_plans table.
  select exists (select 1 from public.client_meal_plans m where m.client_id = cli.id and m.status = 'assigned')
      or exists (select 1 from public.meal_plans l where l.client_id = cli.id and (l.assigned_at is not null or l.status = 'assigned'))
    into v_assigned;
  -- Mirrors check_client_meal_plan_release() (the trigger that guards the assign) exactly,
  -- so the checklist never shows a tick the write would refuse.
  select * into v_splan from public.client_meal_plans m
   where m.client_id = cli.id and m.status = 'draft' order by m.created_at desc limit 1;
  if v_splan.id is not null then
    v_splan_id := v_splan.id;
    select count(*) into v_slots from public.client_meal_plan_slots s where s.plan_id = v_splan_id;
    select count(*) filter (where s.meal_id is not null),
           count(*) filter (where mm.id is null or mm.status <> 'published')
      into v_day0, v_unpub
      from public.client_meal_plan_slots s left join public.meals mm on mm.id = s.meal_id
     where s.plan_id = v_splan_id and s.day_index = 0;
    v_sreason := case
      when v_slots = 0 then 'no meals'
      when v_splan.meals_per_day is null or v_splan.meals_per_day < 1 then 'meals per day not set'
      when v_splan.target_calories is null or v_splan.target_protein_g is null or v_splan.target_fat_g is null or v_splan.target_carb_g is null then 'macro targets not set'
      when v_day0 is distinct from v_splan.meals_per_day then format('day 1 has %s filled slot%s, meals per day says %s', v_day0, case when v_day0 = 1 then '' else 's' end, v_splan.meals_per_day)
      when v_unpub > 0 then format('%s meal%s not published', v_unpub, case when v_unpub = 1 then '' else 's' end)
      else null end;
  end if;
  -- Mirrors check_meal_plan_release() for the legacy table.
  select * into v_lplan from public.meal_plans l
   where l.client_id = cli.id and l.assigned_at is null and coalesce(l.status,'draft') = 'draft'
   order by l.created_at desc limit 1;
  if v_lplan.id is not null then
    v_lplan_id := v_lplan.id;
    v_lreason := case
      when v_lplan.calories is null or v_lplan.protein_g is null or v_lplan.fat_g is null or v_lplan.carb_g is null then 'macros not set'
      when jsonb_array_length(coalesce(v_lplan.meals, '[]'::jsonb)) = 0 then 'no meals'
      else null end;
  end if;
  v_nutrition := case
    when v_assigned then jsonb_build_object('ok', true, 'state', 'assigned', 'detail', 'Nutrition assigned')
    when cli.nutrition_declined_at is not null then jsonb_build_object('ok', true, 'state', 'declined', 'detail', 'No nutrition plan (recorded ' || to_char(cli.nutrition_declined_at, 'YYYY-MM-DD') || ')')
    when v_splan_id is not null and v_sreason is null then jsonb_build_object('ok', true, 'state', 'draft', 'detail', format('Nutrition (%s meal%s)', v_slots, case when v_slots = 1 then '' else 's' end), 'plan_id', v_splan_id, 'source', 'structured')
    when v_splan_id is not null then jsonb_build_object('ok', false, 'state', case when v_slots = 0 then 'empty_draft' else 'incomplete_draft' end, 'detail', 'Nutrition draft not ready: ' || v_sreason, 'plan_id', v_splan_id, 'source', 'structured')
    when v_lplan_id is not null and v_lreason is null then jsonb_build_object('ok', true, 'state', 'draft', 'detail', 'Nutrition (uploaded plan)', 'plan_id', v_lplan_id, 'source', 'legacy')
    when v_lplan_id is not null then jsonb_build_object('ok', false, 'state', 'incomplete_draft', 'detail', 'Nutrition draft not ready: ' || v_lreason, 'plan_id', v_lplan_id, 'source', 'legacy')
    else jsonb_build_object('ok', false, 'state', 'none', 'detail', 'No nutrition plan — or tick "no nutrition for this client"') end;

  -- 3. email — present AND syntactically valid (one @, something either side, a dot after).
  v_email := case
    when nullif(trim(coalesce(cli.email, '')), '') is null then jsonb_build_object('ok', false, 'state', 'missing', 'detail', 'Email missing')
    when trim(cli.email) !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then jsonb_build_object('ok', false, 'state', 'invalid', 'detail', 'Email looks invalid: ' || cli.email)
    else jsonb_build_object('ok', true, 'state', 'valid', 'detail', 'Email ' || trim(cli.email)) end;

  -- 4. health / compliance — authoritative at the database boundary. Reads the latest
  -- SUBMITTED intake's health_flags (written by intake-submit from the PAR-Q answers).
  -- Fails closed: no screen on record, or an unreadable one, blocks; a flagged screen
  -- blocks unless a coach has explicitly reviewed it — the only clearance this app records
  -- is a coach approving the draft that carried the flags (approve_program_draft on the held
  -- draft, decided_by set). Nothing here infers clearance.
  select * into v_intake from public.intake_forms i
   where i.client_id = cli.id and i.status = 'submitted'
   order by i.submitted_at desc nulls last, i.created_at desc limit 1;
  if v_intake.id is null then
    v_health := jsonb_build_object('ok', false, 'state', 'no_screen', 'detail', 'No health screen on record — a submitted intake is required');
  elsif jsonb_typeof(v_intake.health_flags) is distinct from 'array' then
    v_health := jsonb_build_object('ok', false, 'state', 'unreadable', 'detail', 'Health screen not readable — fix the intake record before releasing');
  elsif jsonb_array_length(v_intake.health_flags) = 0 then
    v_health := jsonb_build_object('ok', true, 'state', 'clear', 'detail', 'Health screen clear');
  else
    v_flags := v_intake.health_flags;
    select exists (select 1 from public.program_drafts d
                    where d.intake_id = v_intake.id and d.status in ('approved', 'published')
                      and d.decided_by is not null) into v_reviewed;
    v_health := case
      when v_reviewed then jsonb_build_object('ok', true, 'state', 'flagged_reviewed', 'flags', v_flags,
                              'detail', 'Health screen flagged, reviewed and approved by coach')
      else jsonb_build_object('ok', false, 'state', 'flagged', 'flags', v_flags,
                              'detail', 'Health screen flagged (' || (select string_agg(x, ', ') from jsonb_array_elements_text(v_flags) x) || ') — review and approve the held draft in Programs first') end;
  end if;

  return jsonb_build_object(
    'client_id', cli.id,
    'program', v_program, 'nutrition', v_nutrition, 'email', v_email, 'health', v_health,
    'invite_state', case when cli.client_user_id is not null then 'claimed'
                         when cli.invite_token is null then 'none'
                         when cli.invite_expires_at < now() then 'expired' else 'pending' end,
    'ready', (v_program->>'ok')::boolean and (v_nutrition->>'ok')::boolean and (v_email->>'ok')::boolean and (v_health->>'ok')::boolean);
end $fn$;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260907100000_onboarding_reminders.sql =====
-- Slice 2 of the original design notes (not included) — reminders on the stalls.
--
-- Three things, all read-side except two config columns and one index:
--   1. tenant_config.sender_email + tenant_config.onboarding_reminders — the sending identity
--      and the four per-tenant switches (D3: default ALL OFF; the platform owner flips them in Settings).
--   2. onboarding_reminders_due() — the selection. Reads client_onboarding_facts() for every
--      tenant, applies the approved thresholds, drops anything already sent (idempotent on
--      client × template × threshold day × the token it points at), and returns each candidate
--      WITH the facts the sender needs to decide honestly: is the switch on, is there a sender,
--      is there an email, is there a push subscription. The edge function onboarding-nudge does
--      not shape anything — it sends, or logs why it did not.
--   3. onboarding_coach_digest() — the coach-owed section that folds into send-digest, and
--      onboarding_reminder_status() — what the coach home and Settings show about the switches.
--
-- Thresholds (approved 2026-09-06 20:08):
--   intake_reminder     intake pending, day 3 and day 10 (link dies at 14)
--   invite_reminder     invite pending, day 3 and day 10 (link dies at 14)
--   first_open_reminder claimed, never opened, day 2
--   coach digest        daily, once, inside send-digest — not a separate email
-- A threshold fires ONCE per token. Day 3 fires while days 3–9; day 10 fires while days 10–12
-- ("four days left" is not honest at day 13, and the coach resends at 14). If the switch was off
-- when a threshold passed and is flipped on later inside the window, that threshold fires then.

-- ---------- 1. config ----------
alter table public.tenant_config
  add column if not exists sender_email text,
  add column if not exists onboarding_reminders jsonb not null
    default '{"intake": false, "invite": false, "first_open": false, "coach_digest": false}'::jsonb;

alter table public.tenant_config drop constraint if exists tenant_config_sender_email_check;
alter table public.tenant_config add constraint tenant_config_sender_email_check
  check (sender_email is null or sender_email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$');

alter table public.tenant_config drop constraint if exists tenant_config_onboarding_reminders_check;
alter table public.tenant_config add constraint tenant_config_onboarding_reminders_check
  check (jsonb_typeof(onboarding_reminders) = 'object');

comment on column public.tenant_config.sender_email is
  'Address automated client reminders leave from (Resend). NULL = reminders are logged skipped_no_sender, never sent. Must be on a domain verified in Resend; the sender checks that at run time.';
comment on column public.tenant_config.onboarding_reminders is
  'Slice 2 switches: {intake, invite, first_open, coach_digest}. Default all false. A missing key reads as false.';

-- ---------- 2. idempotency: one SENT row per client × template × threshold × token ----------
-- channel is in the key because first_open goes out on email AND push, logged separately.
create unique index if not exists notification_log_onboarding_reminder_once
  on public.notification_log (client_id, channel, template, (consent_snapshot->>'threshold_day'), (consent_snapshot->>'ref'), status)
  where template in ('intake_reminder', 'invite_reminder', 'first_open_reminder');

-- ---------- 3. the selection ----------
create or replace function public.onboarding_reminders_due()
returns table (
  tenant_id uuid,
  tenant_slug text,
  client_id uuid,
  display_name text,
  email text,
  template text,
  threshold_day integer,
  ref text,
  link_path text,
  expires_at timestamptz,
  since timestamptz,
  days_since integer,
  switch_on boolean,
  sender_email text,
  push_subscription jsonb,
  push_ok boolean
)
language plpgsql stable security definer
set search_path = public as $fn$
declare
  t record;
begin
  -- Service role (the cron-driven edge function) or a direct database session (SQL editor,
  -- the test suite). Never a signed-in user: this reads every tenant.
  if auth.uid() is not null and auth.role() is distinct from 'service_role' then
    raise exception 'onboarding_reminders_due: service role only';
  end if;

  for t in
    select tn.id, tn.slug, tc.sender_email, coalesce(tc.onboarding_reminders, '{}'::jsonb) as sw
      from tenants tn left join tenant_config tc on tc.tenant_id = tn.id
  loop
    return query
    with f as (
      select * from client_onboarding_facts(t.id) x where x.client_status not in ('paused', 'archived')
    ),
    cl as (
      select c.id, c.email, c.invite_token, c.invite_expires_at, c.client_user_id, c.updated_at,
             c.push_subscription, c.notif_enabled, c.notif_channels,
             u.last_sign_in_at
        from clients c left join auth.users u on u.id = c.client_user_id
       where c.tenant_id = t.id
    ),
    it as (
      select distinct on (i.client_id) i.client_id, i.id, i.token, i.created_at, i.expires_at
        from intake_forms i where i.tenant_id = t.id order by i.client_id, i.created_at desc
    ),
    raw as (
      -- intake: sent, not submitted, not expired. Clock = when this token was minted.
      select f.client_id, f.display_name, cl.email,
             'intake_reminder'::text as template,
             it.id::text as ref,
             '/intake?token=' || it.token as link_path,
             it.expires_at,
             it.created_at as since,
             'intake'::text as switch_key,
             cl.push_subscription, cl.notif_enabled, cl.notif_channels
        from f join cl on cl.id = f.client_id join it on it.client_id = f.client_id
       where f.next_action = 'awaiting_client_intake' and it.token is not null
      union all
      -- invite: token out, not claimed, not expired. Clock = expiry minus the 14-day TTL
      -- (client-invite's INVITE_TTL_DAYS); the mint time itself is not stored.
      select f.client_id, f.display_name, cl.email,
             'invite_reminder',
             md5(cl.invite_token),
             '/claim?token=' || cl.invite_token,
             cl.invite_expires_at,
             cl.invite_expires_at - interval '14 days',
             'invite',
             cl.push_subscription, cl.notif_enabled, cl.notif_channels
        from f join cl on cl.id = f.client_id
       where f.next_action = 'awaiting_client_claim' and cl.invite_token is not null
      union all
      -- first open: claimed, program and nutrition live, never opened the app. Clock = the
      -- sign-in that claimed it (auth), else the claim's own row update.
      select f.client_id, f.display_name, cl.email,
             'first_open_reminder',
             cl.client_user_id::text,
             '/client',
             null::timestamptz,
             coalesce(cl.last_sign_in_at, cl.updated_at),
             'first_open',
             cl.push_subscription, cl.notif_enabled, cl.notif_channels
        from f join cl on cl.id = f.client_id
       where f.next_action = 'awaiting_first_open' and cl.client_user_id is not null
    ),
    aged as (
      select r.*, floor(extract(epoch from (now() - r.since)) / 86400)::int as days
        from raw r
    ),
    thresholded as (
      select a.*,
             case
               when a.template in ('intake_reminder', 'invite_reminder') and a.days between 10 and 12 then 10
               when a.template in ('intake_reminder', 'invite_reminder') and a.days between 3 and 9 then 3
               when a.template = 'first_open_reminder' and a.days >= 2 then 2
             end as threshold
        from aged a
    )
    select t.id, t.slug, th.client_id, th.display_name, th.email,
           th.template, th.threshold, th.ref, th.link_path, th.expires_at, th.since, th.days,
           coalesce((t.sw ->> th.switch_key)::boolean, false),
           t.sender_email,
           th.push_subscription,
           (coalesce(th.notif_enabled, false) and coalesce((th.notif_channels ->> 'push')::boolean, false)
             and th.push_subscription is not null)
      from thresholded th
     where th.threshold is not null
       and not exists (
         select 1 from notification_log n
          where n.client_id = th.client_id and n.template = th.template and n.status = 'sent'
            and n.consent_snapshot ->> 'threshold_day' = th.threshold::text
            and n.consent_snapshot ->> 'ref' = th.ref)
     order by th.template, th.days desc;
  end loop;
end $fn$;

revoke all on function public.onboarding_reminders_due() from public, anon, authenticated;
grant execute on function public.onboarding_reminders_due() to service_role;
comment on function public.onboarding_reminders_due() is
  'Slice 2: every reminder due today across all tenants, minus those already sent, each with switch/sender/email/push facts so the sender can act or log why not. Service role only. Read-only.';

-- ---------- 4. coach digest section (folds into send-digest) ----------
-- Everything owed BY THE COACH for 3+ days, bucketed the way the approved digest line reads.
-- "nutrition drafts without macros" is the release bucket split by the same macro rule
-- release_checklist() applies (target_* on client_meal_plans, calories/protein/fat/carb on the
-- legacy meal_plans) — so the digest never counts as "ready" something Release would refuse.
create or replace function public.onboarding_coach_digest(p_tenant_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public as $fn$
declare
  v_out jsonb;
begin
  if auth.uid() is not null and auth.role() is distinct from 'service_role' then
    if coalesce(current_app_role(), '') <> 'coach' or p_tenant_id is distinct from current_tenant_id() then
      raise exception 'onboarding_coach_digest: coach of this tenant only';
    end if;
  end if;

  with f as (
    select * from client_onboarding_facts(p_tenant_id) x
     where x.client_status not in ('paused', 'archived') and x.stalled_days >= 3
  ),
  splan as (
    select distinct on (m.client_id) m.client_id,
           (m.target_calories is null or m.target_protein_g is null or m.target_fat_g is null or m.target_carb_g is null) as no_macros
      from client_meal_plans m where m.tenant_id = p_tenant_id and m.status = 'draft'
     order by m.client_id, m.created_at desc
  ),
  lplan as (
    select distinct on (l.client_id) l.client_id,
           (l.calories is null or l.protein_g is null or l.fat_g is null or l.carb_g is null) as no_macros
      from meal_plans l where l.tenant_id = p_tenant_id and l.assigned_at is null and coalesce(l.status, 'draft') = 'draft'
     order by l.client_id, l.created_at desc
  ),
  owed as (
    select f.client_id, f.display_name, f.stalled_days,
           case
             when f.next_action = 'review_draft' then 'drafts_to_review'
             when f.next_action = 'assemble_nutrition' then 'no_nutrition_plan'
             when f.next_action = 'release' and coalesce(s.no_macros, l.no_macros, false) then 'drafts_without_macros'
             when f.next_action = 'release' then 'ready_to_release'
             when f.next_action = 'send_invite' then 'invite_not_sent'
             when f.next_action in ('intake_expired_resend', 'invite_expired_resend') then 'expired_links'
             when f.next_action = 'send_intake' then 'intake_never_sent'
           end as bucket
      from f left join splan s on s.client_id = f.client_id left join lplan l on l.client_id = f.client_id
  ),
  o as (select * from owed where bucket is not null)
  select jsonb_build_object(
    'owed', (select count(*) from o),
    'buckets', coalesce((
      select jsonb_agg(jsonb_build_object('key', b.bucket, 'label', b.label, 'n', b.n) order by b.ord)
        from (
          select bucket, count(*)::int as n,
                 case bucket
                   when 'drafts_without_macros' then 'nutrition drafts without macros'
                   when 'no_nutrition_plan' then 'no nutrition plan'
                   when 'invite_not_sent' then 'invite not sent'
                   when 'ready_to_release' then 'ready to release'
                   when 'drafts_to_review' then 'program drafts to review'
                   when 'expired_links' then 'expired links to resend'
                   when 'intake_never_sent' then 'intake never sent'
                 end as label,
                 case bucket
                   when 'drafts_without_macros' then 1 when 'no_nutrition_plan' then 2 when 'invite_not_sent' then 3
                   when 'ready_to_release' then 4 when 'drafts_to_review' then 5 when 'expired_links' then 6 else 7
                 end as ord
            from o group by bucket) b), '[]'::jsonb),
    'longest', (select jsonb_build_object('display_name', x.display_name, 'days', x.stalled_days)
                  from o x order by x.stalled_days desc, x.display_name limit 1),
    'switch_on', coalesce((select (tc.onboarding_reminders ->> 'coach_digest')::boolean
                             from tenant_config tc where tc.tenant_id = p_tenant_id), false)
  ) into v_out;
  return v_out;
end $fn$;

revoke all on function public.onboarding_coach_digest(uuid) from public, anon;
grant execute on function public.onboarding_coach_digest(uuid) to authenticated, service_role;
comment on function public.onboarding_coach_digest(uuid) is
  'Slice 2: what the coach owes for 3+ days, bucketed for the daily digest line. Service role, or the coach of that tenant. Read-only.';

-- ---------- 5. what the coach sees about reminders ----------
create or replace function public.onboarding_reminder_status()
returns jsonb
language plpgsql stable security definer
set search_path = public as $fn$
declare
  v_tenant uuid := current_tenant_id();
begin
  if v_tenant is null or coalesce(current_app_role(), '') <> 'coach' then
    raise exception 'onboarding_reminder_status: coach only';
  end if;
  return (
    select jsonb_build_object(
      'sender_email', tc.sender_email,
      'switches', coalesce(tc.onboarding_reminders, '{}'::jsonb),
      -- (as applied 2026-09-07 this read `v` and errored; corrected in 20260907101000 — kept
      -- correct here so a fresh database gets the working body)
      'any_on', coalesce((select bool_or(e.value::boolean)
                            from jsonb_each_text(coalesce(tc.onboarding_reminders, '{}'::jsonb)) e), false),
      'sent_24h', (select count(*) from notification_log n where n.tenant_id = v_tenant
                     and n.template in ('intake_reminder', 'invite_reminder', 'first_open_reminder')
                     and n.status = 'sent' and n.sent_at > now() - interval '24 hours'),
      'skipped_no_sender_24h', (select count(*) from notification_log n where n.tenant_id = v_tenant
                     and n.template in ('intake_reminder', 'invite_reminder', 'first_open_reminder')
                     and n.status in ('skipped_no_sender', 'skipped_sender_unverified') and n.sent_at > now() - interval '24 hours'),
      'skipped_switch_off_24h', (select count(*) from notification_log n where n.tenant_id = v_tenant
                     and n.template in ('intake_reminder', 'invite_reminder', 'first_open_reminder')
                     and n.status = 'skipped_switch_off' and n.sent_at > now() - interval '24 hours'),
      'last_run', (select jsonb_build_object('finished_at', r.finished_at, 'outcome', r.outcome, 'healthy', r.healthy)
                     from ops_job_runs r where r.job = 'onboarding-nudge' order by r.finished_at desc limit 1)
    )
    from tenant_config tc where tc.tenant_id = v_tenant
  );
end $fn$;

