-- ===== migration 20260908120000_challenge_capacity_and_coach_runs.sql =====
-- Slice 3 follow-through.
--
-- H1 — capacity. A challenge may carry a hard cap on entrants. The cap is enforced at the
-- database, not only in challenge-enroll: a BEFORE INSERT trigger on challenge_runs takes a
-- row lock on the parent challenge (SELECT … FOR UPDATE) so two concurrent enrolls are
-- serialised, then counts existing runs and refuses when the cap is reached. Every write
-- path (challenge-enroll, the MCP enroll tool, a coach in SQL) meets the same wall.
-- NULL max_entrants = no cap, which keeps every existing challenge exactly as it was.
--
-- H3 — the coach could not tell who a run belongs to (the runs view showed a user-id
-- fragment). challenge_runs_for_coach() returns the coach's own tenant's runs joined to
-- the participant's sign-in email, for coaches only.

alter table public.challenges
  add column if not exists max_entrants int null
  check (max_entrants is null or max_entrants > 0);

comment on column public.challenges.max_entrants is
  'Hard cap on runs for this challenge, enforced by trg_challenge_runs_capacity. NULL = no cap.';

create or replace function public.challenge_runs_enforce_capacity()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_cap   int;
  v_count int;
begin
  -- Lock the parent row: concurrent inserts for the same challenge queue here, so the
  -- count below is exact for whichever transaction holds the lock.
  select max_entrants into v_cap
    from public.challenges
   where id = new.challenge_id
     for update;
  if v_cap is null then
    return new;
  end if;
  select count(*) into v_count
    from public.challenge_runs
   where challenge_id = new.challenge_id;
  if v_count >= v_cap then
    raise exception 'challenge is full'
      using errcode = 'P0001', hint = 'challenge_full',
            detail = format('%s of %s places taken', v_count, v_cap);
  end if;
  return new;
end $$;

drop trigger if exists trg_challenge_runs_capacity on public.challenge_runs;
create trigger trg_challenge_runs_capacity
  before insert on public.challenge_runs
  for each row execute function public.challenge_runs_enforce_capacity();

-- Coach-facing runs with identity. SECURITY DEFINER because auth.users is not readable
-- by the authenticated role; the function itself refuses anyone who is not a coach and
-- scopes strictly to the caller's tenant.
create or replace function public.challenge_runs_for_coach(p_challenge_id uuid)
returns table (
  id uuid, participant_user_id uuid, participant_email text, client_id uuid,
  status text, current_day_index int, perfect_week boolean,
  started_at timestamptz, completed_at timestamptz, created_at timestamptz
)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_tenant uuid := public.current_tenant_id();
begin
  if public.current_app_role() is distinct from 'coach' or v_tenant is null then
    raise exception 'coach only' using errcode = '42501';
  end if;
  return query
    select r.id, r.participant_user_id, u.email::text, r.client_id,
           r.status::text, r.current_day_index, r.perfect_week,
           r.started_at, r.completed_at, r.created_at
      from public.challenge_runs r
      join public.challenges c on c.id = r.challenge_id
      left join auth.users u on u.id = r.participant_user_id
     where r.challenge_id = p_challenge_id
       and c.tenant_id = v_tenant
       and r.tenant_id = v_tenant
     order by r.created_at desc;
end $$;

revoke all on function public.challenge_runs_for_coach(uuid) from public, anon;
grant execute on function public.challenge_runs_for_coach(uuid) to authenticated;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260910073500_connector_coach_tokens_allow_read_write.sql =====
-- Coach-minted connector tokens may be read OR read_write again.
--
-- Why (2026-09-10, the platform owner): The coach AI screen offers "View & take actions", but since
-- 20260904110000_connector_coach_tokens_read_only.sql the database refused it with
-- "Coach tokens are read-only. Write scope is not available." The platform owner needs to mint write
-- tokens for their own agents (for example Claude). The MCP server never stopped honoring
-- read_write coach tokens (canUseTool gates every write tool on that scope, and every
-- write is audit-logged), so the lock only blocked new tokens, not the capability.
--
-- What changes: ct_coach_insert accepts scope in ('read', 'read_write'). The guard trigger's
-- INSERT branch enforces the same set instead of read only.
--
-- What does not change: kind must be 'coach', tenant must match, created_by must be the
-- caller. Token identity stays immutable after creation, revoked tokens stay revoked, client
-- tokens (ct_client_insert, owner-scope trigger) are untouched, and the table CHECK still
-- forbids client + read_write.

-- ── 1. Policy ────────────────────────────────────────────────────────────────────────
drop policy if exists ct_coach_insert on public.connector_tokens;

create policy ct_coach_insert on public.connector_tokens
  for insert to public
  with check (
    tenant_id = current_tenant_id()
    and current_app_role() = 'coach'
    and kind = 'coach'
    and scope in ('read', 'read_write')
    and created_by = auth.uid()
  );

-- ── 2. Trigger: coach sessions mint read or read_write; identity still immutable ─────
create or replace function public.connector_tokens_guard()
returns trigger
language plpgsql
security invoker
set search_path to 'public'
as $$
begin
  if TG_OP = 'INSERT' then
    -- A coach session may only create coach-kind tokens with a coach scope. Service role
    -- and the DB owner (SECURITY DEFINER bodies) pass — they mint client tokens.
    if current_user in ('authenticated', 'anon')
       and public.current_app_role() = 'coach'
       and new.scope not in ('read', 'read_write') then
      raise exception 'Coach tokens may be read or read_write only.' using errcode = '42501';
    end if;
    return new;
  end if;

  -- UPDATE: a token's identity never changes after creation. Only label, last_used_at and
  -- revoked_at may move.
  if new.id is distinct from old.id
     or new.tenant_id is distinct from old.tenant_id
     or new.created_by is distinct from old.created_by
     or new.kind is distinct from old.kind
     or new.scope is distinct from old.scope
     or new.client_id is distinct from old.client_id
     or new.token_hash is distinct from old.token_hash
     or new.created_at is distinct from old.created_at then
    raise exception 'connector token identity is immutable' using errcode = '42501';
  end if;
  -- A revoked token stays revoked.
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'a revoked connector token cannot be reactivated' using errcode = '42501';
  end if;
  return new;
end;
$$;

comment on function public.connector_tokens_guard() is
  'BEFORE INSERT/UPDATE on connector_tokens. Insert: a coach session (authenticated + coach role) may create scope=read or scope=read_write (2026-09-10; read-only 09-04 to 09-10). Update: id/tenant_id/created_by/kind/scope/client_id/token_hash/created_at are immutable; revoked_at cannot be cleared.';

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260918110000_upgrade_coach_tenant_admin.sql =====
-- ============================================================================
-- Fix: admin-provision-coach had no path to upgrade an existing coach's
-- tenant -- every call inserted a brand-new tenant row, unconditionally
-- (provision_coach_admin, 20260825120000).
--
-- Found 2026-09-18 via a live incident: Courtland Carson (Incentive Athletics,
-- tenant `incentive`, still on a 14-day trial) was meant to be granted full
-- comped access. The only tool available created a SECOND, separate tenant
-- (`incentiveathletics`, created 2026-09-17) instead of upgrading the one he
-- was actually using. That new tenant has never been claimed (coach_user_id
-- is null) -- Courtland never got the access, and his real trial kept
-- counting down unnoticed.
--
-- upgrade_coach_tenant_admin gives an explicit, opt-in path to upgrade an
-- ALREADY-CLAIMED tenant in place (comped or paid) instead of creating a new
-- one. It deliberately refuses an unclaimed tenant -- upgrading something
-- nobody has claimed yet isn't an upgrade, it's provisioning, which
-- provision_coach_admin already does.
-- ============================================================================

create or replace function public.upgrade_coach_tenant_admin(
  p_slug text,
  p_mode text,                    -- 'comped' | 'paid' -- upgrades only move a coach OFF trial
  p_reason text default null,
  p_subscription_id text default null,
  p_customer_id text default null
)
returns public.tenants
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  t public.tenants;
begin
  if p_mode not in ('comped', 'paid') then
    raise exception 'upgrade_coach_tenant_admin: mode must be comped or paid (got %)', p_mode;
  end if;
  if p_mode = 'comped' and coalesce(nullif(trim(p_reason), ''), '') = '' then
    raise exception 'upgrade_coach_tenant_admin: comped mode requires a reason';
  end if;
  if p_mode = 'paid' and (p_subscription_id is null or p_customer_id is null) then
    raise exception 'upgrade_coach_tenant_admin: paid mode requires both subscription_id and customer_id';
  end if;

  select * into t from public.tenants where slug = p_slug;
  if not found then
    raise exception 'upgrade_coach_tenant_admin: no tenant with slug %', p_slug;
  end if;
  if t.coach_user_id is null then
    raise exception 'upgrade_coach_tenant_admin: tenant % has not been claimed by a coach yet -- use provision_coach_admin to create a new tenant instead', p_slug;
  end if;

  update public.tenants set
    trial_ends_at       = null,
    comp_reason          = case when p_mode = 'comped' then p_reason else null end,
    subscription_id      = case when p_mode = 'paid' then p_subscription_id else null end,
    stripe_customer_id   = case when p_mode = 'paid' then p_customer_id else null end,
    subscription_status  = case when p_mode = 'paid' then 'active' else null end,
    updated_at           = now()
  where id = t.id
  returning * into t;

  return t;
end;
$$;

comment on function public.upgrade_coach_tenant_admin(text, text, text, text, text) is
  'Upgrades an ALREADY-CLAIMED tenant from trial to comped/paid in place. Service-role only -- the caller (admin-provision-coach edge function) must independently verify the caller is the owner-tenant coach, and for paid mode, that the subscription is real, before calling this. Refuses an unclaimed tenant -- that case belongs to provision_coach_admin.';

revoke all on function public.upgrade_coach_tenant_admin(text, text, text, text, text) from public;
revoke all on function public.upgrade_coach_tenant_admin(text, text, text, text, text) from anon;
revoke all on function public.upgrade_coach_tenant_admin(text, text, text, text, text) from authenticated;
grant execute on function public.upgrade_coach_tenant_admin(text, text, text, text, text) to service_role;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20260920210000_publish_refuses_to_replace_coach_built_program.sql =====
-- Publishing a generated draft must not silently replace a program the coach built by hand.
--
-- Found 2026-09-20 from coach Courtland Carson (tenant `incentive`). Twice — Ziri Pichardo
-- 2026-09-13 and Corey Carson 2026-09-17 — he built a client's program in Programs, assigned
-- it, and it went live. The client's intake had also produced an AI draft, which sat on Coach
-- Home as "Program drafts awaiting approval". He tapped Approve. approve_program_draft ->
-- publish_program_draft inserted the generated program, flipped his assignment to inactive
-- and made the generated one live. From his side: "after the client has full access the plan
-- changes to a preset plan already created by the app. All my notes and workouts then vanish."
-- (decided_by on both drafts is the coach's own user; decision_note null: the Approve card.)
--
-- Nothing was deleted — his program and its assignment rows still exist, inactive — but the
-- client sees the generated plan and every day he trains on it is history against the wrong
-- program. Ziri's was flipped back by hand on 2026-09-18. Corey's is still wrong at the time
-- of writing.
--
-- The guard lives in the publish path itself so every caller gets it (approve_program_draft,
-- release_client, the MCP connector). Rule: if the client already has an ACTIVE assignment to
-- a program that did not come from a draft (programs.source_draft_id is null = coach-built),
-- refuse with a message that names the program. The coach's intent is preserved either way:
-- to switch the client to the generated plan they unassign or archive their own in Programs
-- first, which is an explicit choice instead of a side effect of a button labelled Approve.
-- Replacing a previously PUBLISHED draft's program (source_draft_id set) is still allowed —
-- that is a regenerate, not a coach's work being overwritten.
--
-- release_client() already skips publishing when a live assignment exists (release_checklist
-- state 'live'), so this changes nothing there. approve_program_draft surfaces the exception
-- verbatim on the Coach Home row (ReviewProgramDrafts shows every failure as-is), so the
-- coach reads exactly why and what to do. No UI change is required for the guard to hold;
-- a follow-up may mark such rows "already live" before the tap.
--
-- Drift note, 2026-09-20: production's publish_program_draft was the pre-2026-07-31 text
-- (no hold-marker handling). Migration 20260731203000 is in the repo but its publish body was
-- not what pg_get_functiondef returned on the live project. This file re-issues that body in
-- full plus the guard, so applying it also lands the hold-marker fix.

create or replace function public.publish_program_draft(p_draft_id uuid)
 returns uuid
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  d public.program_drafts%rowtype;
  cli public.clients%rowtype;
  new_program_id uuid;
  v_meal_plan jsonb;
  v_live_name text;
begin
  select * into d from public.program_drafts where id = p_draft_id;
  if not found then raise exception 'draft % not found', p_draft_id; end if;
  if d.status = 'published' and d.published_program_id is not null then
    return d.published_program_id;  -- idempotent
  end if;
  if jsonb_array_length(coalesce(d.training->'days','[]'::jsonb)) = 0 then
    raise exception 'refusing to publish an empty training plan (draft %)', p_draft_id;
  end if;

  -- A coach-built program that is live for this client is never replaced as a side effect.
  select p.name into v_live_name
    from public.assignments a
    join public.programs p on p.id = a.program_id
   where a.client_id = d.client_id and a.active and p.source_draft_id is null
   order by a.assigned_at desc
   limit 1;
  if v_live_name is not null then
    raise exception 'This client already has a live program you built ("%"). Approving this draft would replace it. To use the generated plan instead, unassign or archive your program in Programs first, then approve.', v_live_name
      using errcode = 'P0001', hint = 'live_coach_program';
  end if;

  select * into cli from public.clients where id = d.client_id;

  -- A hold marker is not a nutrition plan. Never let one reach a live program.
  v_meal_plan := case
    when jsonb_typeof(d.meal_plan) = 'object'
     and (d.meal_plan ? 'held_for_medical_review' or d.meal_plan ? 'held_for_missing_metrics')
    then null
    else d.meal_plan
  end;

  insert into public.programs (tenant_id, name, structure, meal_plan, source_draft_id, is_default)
  values (d.tenant_id,
          'Plan — ' || coalesce(cli.display_name,'Client') || ' — ' || to_char(now(),'YYYY-MM-DD'),
          d.training, v_meal_plan, d.id, false)
  returning id into new_program_id;

  -- one active assignment per client
  update public.assignments set active = false, updated_at = now()
    where client_id = d.client_id and active = true;
  insert into public.assignments (tenant_id, client_id, program_id, active)
  values (d.tenant_id, d.client_id, new_program_id, true);

  update public.program_drafts
    set status = 'published', published_program_id = new_program_id,
        decided_at = coalesce(decided_at, now())
    where id = d.id;

  update public.clients set status = 'active', updated_at = now()
    where id = d.client_id and status <> 'active';

  return new_program_id;
end;
$function$;

-- CREATE OR REPLACE keeps the ACL; re-asserted anyway, matching 20260731203000.
revoke execute on function public.publish_program_draft(uuid) from public, anon;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20261112180000_link_by_email_completes_invite.sql =====
-- link_client_by_email() completes the invite the same way claim_client_invite() does.
--
-- The auth.users triggers (link_client_on_insert / link_client_on_confirm) call
-- link_client_by_email() the moment an invited client confirms their email by entering
-- their first code. That runs BEFORE the claim page calls claim_client_invite(), which
-- then sees the row already attached and answers 'already_yours' without touching it.
-- Before this file the row was attached but kept status 'invited' and a live invite
-- token: the coach's roster said "Invited" for a client who was already training.
--
-- Now linking by a confirmed email also flips 'invited' to 'active', as
-- claim_client_invite() does. Other statuses (paused, archived) are left alone. The invite
-- token is deliberately kept: the claim page calls claim_client_invite() right after, and
-- with the token still on the row it answers 'already_yours' (the "you're all set"
-- screen) instead of 'invalid'. The row is attached, so the token cannot attach anyone
-- else (any other account gets 'already_claimed'), and the next invite replaces it. Only the trigger path runs this, and the triggers
-- fire only on a confirmed email, so the mailbox proof is unchanged.
create or replace function public.link_client_by_email(p_user_id uuid, p_email text)
 returns integer
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_linked int;
  v_tenant uuid;
begin
  if p_email is null or p_user_id is null then return 0; end if;
  -- clients_user_unique: one auth user <-> at most one clients row (schema-enforced).
  -- An already-linked user never claims another row; a multi-tenant email links the
  -- oldest matching row only.
  if exists (select 1 from public.clients where client_user_id = p_user_id) then
    return 0;
  end if;

  update public.clients c
     set client_user_id    = p_user_id,
         status            = case when c.status = 'invited' then 'active'::client_status else c.status end,
         updated_at        = now()
   where c.id = (
     select id from public.clients
      where client_user_id is null and lower(email) = lower(p_email)
      order by joined_at asc limit 1
   );
  get diagnostics v_linked = row_count;

  if v_linked > 0 and not exists (select 1 from public.profiles where user_id = p_user_id) then
    select tenant_id into v_tenant
      from public.clients where client_user_id = p_user_id limit 1;
    insert into public.profiles (user_id, role, tenant_id)
    values (p_user_id, 'client', v_tenant)
    on conflict (user_id) do nothing;
  end if;
  return v_linked;
end;
$function$;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20261112190000_lock_function_execute_grants.sql =====
-- Who may call which database function (EXECUTE grants).
--
-- On a real Supabase project every function created in the public schema is executable by
-- anon and authenticated through default privileges, unless a migration takes that back.
-- The initial schema was rebuilt on plain Postgres, where those default grants do not exist,
-- so its "REVOKE ... FROM PUBLIC" lines looked sufficient there and are not on Supabase.
-- Measured on a fresh Supabase stack before this file: 30 callable SECURITY DEFINER functions
-- (25 beyond the five policy helpers kept below) were
-- callable with only the public anon key, among them
--   link_client_by_email(user_id, email)  -> attach ANY unclaimed client row to any account
--   auth_user_id_by_email(email)          -> look up anyone's account id by email
--   auth_clear_password(user_id)          -> write auth.users
--   schedule_client_checkins(client_id)   -> its owner check treats "no user" as the server
--   provision_coach(app_name, name)       -> any signed-in user (with sign-ups on, any stranger)
--                                            makes themselves a coach with a new tenant
--   accept_invite(token)                  -> legacy claim with no confirmed-email check
-- The original project allowed only seven SECURITY DEFINER functions to anon, and closed the
-- helpers in step 2 to authenticated as well; this file restores that.
--
-- 1. anon keeps EXECUTE only on the SECURITY DEFINER functions RLS policies and the signed-out
--    screens need. Everything else is revoked from PUBLIC and anon; authenticated keeps
--    whatever it had (re-granted explicitly, because revoking PUBLIC can remove it).
-- 2. Server-only helpers lose authenticated too. Only the service role (edge functions) and
--    the auth trigger call them.
-- 3. A new function added later gets Supabase's default grants again. Re-run the block in
--    step 1 (or write the revoke in that migration) when adding a SECURITY DEFINER function.
do $$
declare
  r record;
  keep_anon constant text[] := array[
    'current_app_role', 'current_client_id', 'current_tenant_id', 'get_app_config',
    'tenant_is_suspended'
  ];
  had_auth boolean;
begin
  for r in
    select p.oid, p.oid::regprocedure as sig, p.proname
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.prosecdef and p.prokind = 'f'
       and p.prorettype <> 'trigger'::regtype
       and not (p.proname = any (keep_anon))
  loop
    had_auth := has_function_privilege('authenticated', r.oid, 'execute');
    execute format('revoke execute on function %s from public, anon', r.sig);
    if had_auth then
      execute format('grant execute on function %s to authenticated', r.sig);
    end if;
    execute format('grant execute on function %s to service_role', r.sig);
  end loop;
end $$;

revoke execute on function public.link_client_by_email(uuid, text)      from public, anon, authenticated;
revoke execute on function public.auth_user_id_by_email(text)            from public, anon, authenticated;
revoke execute on function public.auth_clear_password(uuid)              from public, anon, authenticated;
revoke execute on function public.custom_access_token_hook(jsonb)        from public, anon, authenticated;
revoke execute on function public.onboarding_add_blocker(uuid, text, text, text) from public, anon, authenticated;
revoke execute on function public.onboarding_clear_blockers(uuid, text[])        from public, anon, authenticated;
revoke execute on function public.onboarding_recompute_stage(uuid)               from public, anon, authenticated;
revoke execute on function public.publish_program_draft(uuid)            from public, anon, authenticated;
revoke execute on function public.provision_coach(text, text)            from public, anon, authenticated;
revoke execute on function public.accept_invite(text)                    from public, anon, authenticated;
revoke execute on function public.assert_coach_owns_client(uuid)         from public, anon, authenticated;

grant execute on function public.link_client_by_email(uuid, text)  to service_role;
grant execute on function public.auth_user_id_by_email(text)        to service_role;
grant execute on function public.auth_clear_password(uuid)          to service_role;
grant execute on function public.custom_access_token_hook(jsonb)    to service_role, supabase_auth_admin;
grant execute on function public.onboarding_add_blocker(uuid, text, text, text) to service_role;
grant execute on function public.onboarding_clear_blockers(uuid, text[])        to service_role;
grant execute on function public.onboarding_recompute_stage(uuid)               to service_role;
grant execute on function public.publish_program_draft(uuid)        to service_role;
grant execute on function public.provision_coach(text, text)        to service_role;
grant execute on function public.accept_invite(text)                to service_role;
grant execute on function public.assert_coach_owns_client(uuid)     to service_role;

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

-- ===== migration 20261112200000_workout_logs_cardio_fields.sql =====
-- Cardio actuals on workout_logs: duration_seconds and distance_meters.
--
-- The app reads and writes these two columns everywhere a set is logged or shown (client
-- Train and History, coach client detail, the MCP log_workout_on_behalf tool), but no
-- migration ever created them; the original project added them outside the migration
-- files. On a fresh install every workout_logs read failed with 42703 "column
-- workout_logs.duration_seconds does not exist", so "last time" weights, history and the
-- coach's session view came back empty, and saving a set failed. Intensity reuses rpe.
alter table public.workout_logs add column if not exists duration_seconds integer;
alter table public.workout_logs add column if not exists distance_meters numeric;

comment on column public.workout_logs.duration_seconds is 'Cardio actual: duration in seconds. Null for strength sets.';
comment on column public.workout_logs.distance_meters  is 'Cardio actual: distance in meters. Null for strength sets.';

reset search_path;
reset check_function_bodies;
reset client_min_messages;
reset row_security;

